    { r = {"ROMEO"}, t = "She is too fair, too wise; wisely too fair," },
    { r = {"ROMEO"}, t = "To merit bliss by making me despair." },
    { r = {"ROMEO"}, t = "She hath forsworn to love, and in that vow" },
    { r = {"ROMEO"}, t = "Do I live dead, that live to tell it now." },
    { r = {"BENVOLIO"}, t = "Be rul’d by me, forget to think of her." },
    { r = {"ROMEO"}, t = "O teach me how I should forget to think." },
    { r = {"BENVOLIO"}, t = "By giving liberty unto thine eyes;" },
    { r = {"BENVOLIO"}, t = "Examine other beauties." },
    { r = {"ROMEO"}, t = "’Tis the way" },
    { r = {"ROMEO"}, t = "To call hers, exquisite, in question more." },
    { r = {"ROMEO"}, t = "These happy masks that kiss fair ladies’ brows," },
    { r = {"ROMEO"}, t = "Being black, puts us in mind they hide the fair;" },
    { r = {"ROMEO"}, t = "He that is strucken blind cannot forget" },
    { r = {"ROMEO"}, t = "The precious treasure of his eyesight lost." },
    { r = {"ROMEO"}, t = "Show me a mistress that is passing fair," },
    { r = {"ROMEO"}, t = "What doth her beauty serve but as a note" },
    { r = {"ROMEO"}, t = "Where I may read who pass’d that passing fair?" },
    { r = {"ROMEO"}, t = "Farewell, thou canst not teach me to forget." },
    { r = {"BENVOLIO"}, t = "I’ll pay that doctrine, or else die in debt." },
    { d = "Exeunt" },
    { d = "Act 1, Scene 2. A Street.", h = true },
    { d = "Enter Capulet, Paris and Servant" },
    { r = {"CAPULET"}, t = "But Montague is bound as well as I," },
    { r = {"CAPULET"}, t = "In penalty alike; and ’tis not hard, I think," },
    { r = {"CAPULET"}, t = "For men so old as we to keep the peace." },
    { r = {"PARIS"}, t = "Of honourable reckoning are you both," },
    { r = {"PARIS"}, t = "And pity ’tis you liv’d at odds so long." },
    { r = {"PARIS"}, t = "But now my lord, what say you to my suit?" },
    { r = {"CAPULET"}, t = "But saying o’er what I have said before." },
    { r = {"CAPULET"}, t = "My child is yet a stranger in the world," },
    { r = {"CAPULET"}, t = "She hath not seen the change of fourteen years;" },
    { r = {"CAPULET"}, t = "Let two more summers wither in their pride" },
    { r = {"CAPULET"}, t = "Ere we may think her ripe to be a bride." },
    { r = {"PARIS"}, t = "Younger than she are happy mothers made." },
    { r = {"CAPULET"}, t = "And too soon marr’d are those so early made." },
    { r = {"CAPULET"}, t = "The earth hath swallowed all my hopes but she," },
    { r = {"CAPULET"}, t = "She is the hopeful lady of my earth:" },
    { r = {"CAPULET"}, t = "But woo her, gentle Paris, get her heart," },
    { r = {"CAPULET"}, t = "My will to her consent is but a part;" },
    { r = {"CAPULET"}, t = "And she agree, within her scope of choice" },
    { r = {"CAPULET"}, t = "Lies my consent and fair according voice." },
    { r = {"CAPULET"}, t = "This night I hold an old accustom’d feast," },
    { r = {"CAPULET"}, t = "Whereto I have invited many a guest," },
    { r = {"CAPULET"}, t = "Such as I love, and you among the store," },
    { r = {"CAPULET"}, t = "One more, most welcome, makes my number more." },
    { r = {"CAPULET"}, t = "At my poor house look to behold this night" },
    { r = {"CAPULET"}, t = "Earth-treading stars that make dark heaven light:" },
    { r = {"CAPULET"}, t = "Such comfort as do lusty young men feel" },
    { r = {"CAPULET"}, t = "When well apparell’d April on the heel" },
    { r = {"CAPULET"}, t = "Of limping winter treads, even such delight" },
    { r = {"CAPULET"}, t = "Among fresh female buds shall you this night" },
    { r = {"CAPULET"}, t = "Inherit at my house. Hear all, all see," },
    { r = {"CAPULET"}, t = "And like her most whose merit most shall be:" },
    { r = {"CAPULET"}, t = "Which, on more view of many, mine, being one," },
    { r = {"CAPULET"}, t = "May stand in number, though in reckoning none." },
    { r = {"CAPULET"}, t = "Come, go with me. Go, sirrah, trudge about" },
    { r = {"CAPULET"}, t = "Through fair Verona; find those persons out" },
    { r = {"CAPULET"}, t = "Whose names are written there," },
    { r = {"CAPULET"}, t = "and to them say,", d = "gives a paper" },
    { r = {"CAPULET"}, t = "My house and welcome on their pleasure stay." },
    { d = "Exeunt Capulet and Paris" },
    { r = {"SERVANT"}, t = "Find them out whose names are written here!" },
    { r = {"SERVANT"}, t = "It is written that the shoemaker should meddle with his yard and the tailor with his last, the fisher with his pencil, and the painter with his nets;" },
    { r = {"SERVANT"}, t = "but I am sent to find those persons whose names are here writ, and can never find what names the writing person hath here writ." },
    { r = {"SERVANT"}, t = "I must to the learned." },
    { r = {"SERVANT"}, t = "In good time!" },
    { d = "Enter Benvolio and Romeo" },
    { r = {"BENVOLIO"}, t = "Tut, man, one fire burns out another’s burning," },
    { r = {"BENVOLIO"}, t = "One pain is lessen’d by another’s anguish;" },
    { r = {"BENVOLIO"}, t = "Turn giddy, and be holp by backward turning;" },
    { r = {"BENVOLIO"}, t = "One desperate grief cures with another’s languish:" },
    { r = {"BENVOLIO"}, t = "Take thou some new infection to thy eye," },
    { r = {"BENVOLIO"}, t = "And the rank poison of the old will die." },
    { r = {"ROMEO"}, t = "Your plantain leaf is excellent for that." },
    { r = {"BENVOLIO"}, t = "For what, I pray thee?" },
    { r = {"ROMEO"}, t = "For your broken shin." },
    { r = {"BENVOLIO"}, t = "Why, Romeo, art thou mad?" },
    { r = {"ROMEO"}, t = "Not mad, but bound more than a madman is:" },
    { r = {"ROMEO"}, t = "Shut up in prison, kept without my food," },
    { r = {"ROMEO"}, t = "Whipp’d and tormented and—God-den, good fellow." },
    { r = {"SERVANT"}, t = "God gi’ go-den. I pray, sir, can you read?" },
    { r = {"ROMEO"}, t = "Ay, mine own fortune in my misery." },
    { r = {"SERVANT"}, t = "Perhaps you have learned it without book." },
    { r = {"SERVANT"}, t = "But I pray, can you read anything you see?" },
    { r = {"ROMEO"}, t = "Ay, If I know the letters and the language." },
    { r = {"SERVANT"}, t = "Ye say honestly, rest you merry!" },
    { r = {"ROMEO"}, t = "Stay, fellow; I can read." },
    { d = "He reads the letter" },
    { r = {"ROMEO"}, t = "Signior Martino and his wife and daughters;" },
    { r = {"ROMEO"}, t = "County Anselmo and his beauteous sisters;" },
    { r = {"ROMEO"}, t = "The lady widow of Utruvio;" },
    { r = {"ROMEO"}, t = "Signior Placentio and his lovely nieces;" },
    { r = {"ROMEO"}, t = "Mercutio and his brother Valentine;" },
    { r = {"ROMEO"}, t = "Mine uncle Capulet, his wife, and daughters;" },
    { r = {"ROMEO"}, t = "My fair niece Rosaline and Livia;" },
    { r = {"ROMEO"}, t = "Signior Valentio and his cousin Tybalt;" },
    { r = {"ROMEO"}, t = "Lucio and the lively Helena." },
    { r = {"ROMEO"}, t = "A fair assembly." },
    { r = {"ROMEO"}, t = "Whither should they come?", d = "Gives back the paper" },
    { r = {"SERVANT"}, t = "Up." },
    { r = {"ROMEO"}, t = "Whither to supper?" },
    { r = {"SERVANT"}, t = "To our house." },
    { r = {"ROMEO"}, t = "Whose house?" },
    { r = {"SERVANT"}, t = "My master’s." },
    { r = {"ROMEO"}, t = "Indeed I should have ask’d you that before." },
    { r = {"SERVANT"}, t = "Now I’ll tell you without asking." },
    { r = {"SERVANT"}, t = "My master is the great rich Capulet, and if you be not of the house of Montagues, I pray come and crush a cup of wine." },
    { r = {"SERVANT"}, t = "Rest you merry." },
    { d = "Exit" },
    { r = {"BENVOLIO"}, t = "At this same ancient feast of Capulet’s" },
    { r = {"BENVOLIO"}, t = "Sups the fair Rosaline whom thou so lov’st;" },
    { r = {"BENVOLIO"}, t = "With all the admired beauties of Verona." },
    { r = {"BENVOLIO"}, t = "Go thither and with unattainted eye," },
    { r = {"BENVOLIO"}, t = "Compare her face with some that I shall show," },
    { r = {"BENVOLIO"}, t = "And I will make thee think thy swan a crow." },
    { r = {"ROMEO"}, t = "When the devout religion of mine eye" },
    { r = {"ROMEO"}, t = "Maintains such falsehood, then turn tears to fire;" },
    { r = {"ROMEO"}, t = "And these who, often drown’d, could never die," },
    { r = {"ROMEO"}, t = "Transparent heretics, be burnt for liars." },
    { r = {"ROMEO"}, t = "One fairer than my love? The all-seeing sun" },
    { r = {"ROMEO"}, t = "Ne’er saw her match since first the world begun." },
    { r = {"BENVOLIO"}, t = "Tut, you saw her fair, none else being by," },
    { r = {"BENVOLIO"}, t = "Herself pois’d with herself in either eye:" },
    { r = {"BENVOLIO"}, t = "But in that crystal scales let there be weigh’d" },
    { r = {"BENVOLIO"}, t = "Your lady’s love against some other maid" },
    { r = {"BENVOLIO"}, t = "That I will show you shining at this feast," },
    { r = {"BENVOLIO"}, t = "And she shall scant show well that now shows best." },
    { r = {"ROMEO"}, t = "I’ll go along, no such sight to be shown," },
    { r = {"ROMEO"}, t = "But to rejoice in splendour of my own." },
    { d = "Exeunt" },
    { d = "Act 1, Scene 3. Room in Capulet’s House.", h = true },
    { d = "Enter Lady Capulet and Nurse" },
    { r = {"LADY CAPULET"}, t = "Nurse, where’s my daughter? Call her forth to me." },
    { r = {"NURSE"}, t = "Now, by my maidenhead, at twelve year old," },
    { r = {"NURSE"}, t = "I bade her come. What, lamb! What ladybird!" },
    { r = {"NURSE"}, t = "God forbid! Where’s this girl? What, Juliet!" },
    { d = "Enter Juliet" },
    { r = {"JULIET"}, t = "How now, who calls?" },
    { r = {"NURSE"}, t = "Your mother." },
    { r = {"JULIET"}, t = "Madam, I am here. What is your will?" },
    { r = {"LADY CAPULET"}, t = "This is the matter. Nurse, give leave awhile," },
    { r = {"LADY CAPULET"}, t = "We must talk in secret. Nurse, come back again," },
    { r = {"LADY CAPULET"}, t = "I have remember’d me, thou’s hear our counsel." },
    { r = {"LADY CAPULET"}, t = "Thou knowest my daughter’s of a pretty age." },
    { r = {"NURSE"}, t = "Faith, I can tell her age unto an hour." },
    { r = {"LADY CAPULET"}, t = "She’s not fourteen." },
    { r = {"NURSE"}, t = "I’ll lay fourteen of my teeth," },
    { r = {"NURSE"}, t = "And yet, to my teen be it spoken, I have but four," },
    { r = {"NURSE"}, t = "She is not fourteen. How long is it now" },
    { r = {"NURSE"}, t = "To Lammas-tide?" },
    { r = {"LADY CAPULET"}, t = "A fortnight and odd days." },
    { r = {"NURSE"}, t = "Even or odd, of all days in the year," },
    { r = {"NURSE"}, t = "Come Lammas Eve at night shall she be fourteen." },
    { r = {"NURSE"}, t = "Susan and she,—God rest all Christian souls!—" },
    { r = {"NURSE"}, t = "Were of an age. Well, Susan is with God;" },
    { r = {"NURSE"}, t = "She was too good for me. But as I said," },
    { r = {"NURSE"}, t = "On Lammas Eve at night shall she be fourteen;" },
    { r = {"NURSE"}, t = "That shall she, marry; I remember it well." },
    { r = {"NURSE"}, t = "’Tis since the earthquake now eleven years;" },
    { r = {"NURSE"}, t = "And she was wean’d,—I never shall forget it—," },
    { r = {"NURSE"}, t = "Of all the days of the year, upon that day:" },
    { r = {"NURSE"}, t = "For I had then laid wormwood to my dug," },
    { r = {"NURSE"}, t = "Sitting in the sun under the dovehouse wall;" },
    { r = {"NURSE"}, t = "My lord and you were then at Mantua:" },
    { r = {"NURSE"}, t = "Nay, I do bear a brain. But as I said," },
    { r = {"NURSE"}, t = "When it did taste the wormwood on the nipple" },
    { r = {"NURSE"}, t = "Of my dug and felt it bitter, pretty fool," },
    { r = {"NURSE"}, t = "To see it tetchy, and fall out with the dug!" },
    { r = {"NURSE"}, t = "Shake, quoth the dovehouse: ’twas no need, I trow," },
    { r = {"NURSE"}, t = "To bid me trudge." },
    { r = {"NURSE"}, t = "And since that time it is eleven years;" },
    { r = {"NURSE"}, t = "For then she could stand alone; nay, by th’rood" },
    { r = {"NURSE"}, t = "She could have run and waddled all about;" },
    { r = {"NURSE"}, t = "For even the day before she broke her brow," },
    { r = {"NURSE"}, t = "And then my husband,—God be with his soul!" },
    { r = {"NURSE"}, t = "A was a merry man,—took up the child:" },
    { r = {"NURSE"}, t = "‘Yea,’ quoth he, ‘dost thou fall upon thy face?" },
    { r = {"NURSE"}, t = "Thou wilt fall backward when thou hast more wit;" },
    { r = {"NURSE"}, t = "Wilt thou not, Jule?’ and, by my holidame," },
    { r = {"NURSE"}, t = "The pretty wretch left crying, and said ‘Ay’." },
    { r = {"NURSE"}, t = "To see now how a jest shall come about." },
    { r = {"NURSE"}, t = "I warrant, and I should live a thousand years," },
    { r = {"NURSE"}, t = "I never should forget it. ‘Wilt thou not, Jule?’ quoth he;" },
    { r = {"NURSE"}, t = "And, pretty fool, it stinted, and said ‘Ay.’" },
    { r = {"LADY CAPULET"}, t = "Enough of this; I pray thee hold thy peace." },
    { r = {"NURSE"}, t = "Yes, madam, yet I cannot choose but laugh," },
    { r = {"NURSE"}, t = "To think it should leave crying, and say ‘Ay’;" },
    { r = {"NURSE"}, t = "And yet I warrant it had upon it brow" },
    { r = {"NURSE"}, t = "A bump as big as a young cockerel’s stone;" },
    { r = {"NURSE"}, t = "A perilous knock, and it cried bitterly." },
    { r = {"NURSE"}, t = "‘Yea,’ quoth my husband, ‘fall’st upon thy face?" },
    { r = {"NURSE"}, t = "Thou wilt fall backward when thou comest to age;" },
    { r = {"NURSE"}, t = "Wilt thou not, Jule?’ it stinted, and said ‘Ay’." },
    { r = {"JULIET"}, t = "And stint thou too, I pray thee, Nurse, say I." },
    { r = {"NURSE"}, t = "Peace, I have done. God mark thee to his grace" },
    { r = {"NURSE"}, t = "Thou wast the prettiest babe that e’er I nurs’d:" },
    { r = {"NURSE"}, t = "And I might live to see thee married once, I have my wish." },
    { r = {"LADY CAPULET"}, t = "Marry, that marry is the very theme" },
    { r = {"LADY CAPULET"}, t = "I came to talk of. Tell me, daughter Juliet," },
    { r = {"LADY CAPULET"}, t = "How stands your disposition to be married?" },
    { r = {"JULIET"}, t = "It is an honour that I dream not of." },
    { r = {"NURSE"}, t = "An honour! Were not I thine only nurse," },
    { r = {"NURSE"}, t = "I would say thou hadst suck’d wisdom from thy teat." },
    { r = {"LADY CAPULET"}, t = "Well, think of marriage now: younger than you," },
    { r = {"LADY CAPULET"}, t = "Here in Verona, ladies of esteem," },
    { r = {"LADY CAPULET"}, t = "Are made already mothers. By my count" },
    { r = {"LADY CAPULET"}, t = "I was your mother much upon these years" },
    { r = {"LADY CAPULET"}, t = "That you are now a maid. Thus, then, in brief;" },
    { r = {"LADY CAPULET"}, t = "The valiant Paris seeks you for his love." },
    { r = {"NURSE"}, t = "A man, young lady! Lady, such a man" },
    { r = {"NURSE"}, t = "As all the world—why he’s a man of wax." },
    { r = {"LADY CAPULET"}, t = "Verona’s summer hath not such a flower." },
    { r = {"NURSE"}, t = "Nay, he’s a flower, in faith a very flower." },
    { r = {"LADY CAPULET"}, t = "What say you, can you love the gentleman?" },
    { r = {"LADY CAPULET"}, t = "This night you shall behold him at our feast;" },
    { r = {"LADY CAPULET"}, t = "Read o’er the volume of young Paris’ face," },
    { r = {"LADY CAPULET"}, t = "And find delight writ there with beauty’s pen." },
    { r = {"LADY CAPULET"}, t = "Examine every married lineament," },
    { r = {"LADY CAPULET"}, t = "And see how one another lends content;" },
    { r = {"LADY CAPULET"}, t = "And what obscur’d in this fair volume lies," },
    { r = {"LADY CAPULET"}, t = "Find written in the margent of his eyes." },
    { r = {"LADY CAPULET"}, t = "This precious book of love, this unbound lover," },
    { r = {"LADY CAPULET"}, t = "To beautify him, only lacks a cover:" },
    { r = {"LADY CAPULET"}, t = "The fish lives in the sea; and ’tis much pride" },
    { r = {"LADY CAPULET"}, t = "For fair without the fair within to hide." },
    { r = {"LADY CAPULET"}, t = "That book in many’s eyes doth share the glory," },
    { r = {"LADY CAPULET"}, t = "That in gold clasps locks in the golden story;" },
    { r = {"LADY CAPULET"}, t = "So shall you share all that he doth possess," },
    { r = {"LADY CAPULET"}, t = "By having him, making yourself no less." },
    { r = {"NURSE"}, t = "No less, nay bigger. Women grow by men." },
    { r = {"LADY CAPULET"}, t = "Speak briefly, can you like of Paris’ love?" },
    { r = {"JULIET"}, t = "I’ll look to like, if looking liking move:" },
    { r = {"JULIET"}, t = "But no more deep will I endart mine eye" },
    { r = {"JULIET"}, t = "Than your consent gives strength to make it fly." },
    { d = "Enter a Servant" },
    { r = {"SERVANT"}, t = "Madam, the guests are come, supper served up, you called, my young lady asked for, the Nurse cursed in the pantry, and everything in extremity." },
    { r = {"SERVANT"}, t = "I must hence to wait, I beseech you follow straight." },
    { r = {"LADY CAPULET"}, t = "We follow thee." },
    { d = "Exit Servant" },
    { r = {"LADY CAPULET"}, t = "Juliet, the County stays." },
    { r = {"NURSE"}, t = "Go, girl, seek happy nights to happy days." },
    { d = "Exeunt" },
    { d = "Act 1, Scene 4. A Street.", h = true },
    { d = "Enter Romeo, Mercutio, Benvolio, with five or six Maskers; Torch-bearers and others" },
    { r = {"ROMEO"}, t = "What, shall this speech be spoke for our excuse?" },
    { r = {"ROMEO"}, t = "Or shall we on without apology?" },
    { r = {"BENVOLIO"}, t = "The date is out of such prolixity:" },
    { r = {"BENVOLIO"}, t = "We’ll have no Cupid hoodwink’d with a scarf," },
    { r = {"BENVOLIO"}, t = "Bearing a Tartar’s painted bow of lath," },
    { r = {"BENVOLIO"}, t = "Scaring the ladies like a crow-keeper;" },
    { r = {"BENVOLIO"}, t = "Nor no without-book prologue, faintly spoke" },
    { r = {"BENVOLIO"}, t = "After the prompter, for our entrance:" },
    { r = {"BENVOLIO"}, t = "But let them measure us by what they will," },
    { r = {"BENVOLIO"}, t = "We’ll measure them a measure, and be gone." },
    { r = {"ROMEO"}, t = "Give me a torch, I am not for this ambling;" },
    { r = {"ROMEO"}, t = "Being but heavy I will bear the light." },
    { r = {"MERCUTIO"}, t = "Nay, gentle Romeo, we must have you dance." },
    { r = {"ROMEO"}, t = "Not I, believe me, you have dancing shoes," },
    { r = {"ROMEO"}, t = "With nimble soles, I have a soul of lead" },
    { r = {"ROMEO"}, t = "So stakes me to the ground I cannot move." },
    { r = {"MERCUTIO"}, t = "You are a lover, borrow Cupid’s wings," },
    { r = {"MERCUTIO"}, t = "And soar with them above a common bound." },
    { r = {"ROMEO"}, t = "I am too sore enpierced with his shaft" },
    { r = {"ROMEO"}, t = "To soar with his light feathers, and so bound," },
    { r = {"ROMEO"}, t = "I cannot bound a pitch above dull woe." },
    { r = {"ROMEO"}, t = "Under love’s heavy burden do I sink." },
    { r = {"MERCUTIO"}, t = "And, to sink in it, should you burden love;" },
    { r = {"MERCUTIO"}, t = "Too great oppression for a tender thing." },
    { r = {"ROMEO"}, t = "Is love a tender thing? It is too rough," },
    { r = {"ROMEO"}, t = "Too rude, too boisterous; and it pricks like thorn." },
    { r = {"MERCUTIO"}, t = "If love be rough with you, be rough with love;" },
    { r = {"MERCUTIO"}, t = "Prick love for pricking, and you beat love down." },
    { r = {"MERCUTIO"}, t = "Give me a case to put my visage in:" },
    { r = {"MERCUTIO"}, t = "A visor for a visor. What care I", d = "Putting on a mask" },
    { r = {"MERCUTIO"}, t = "What curious eye doth quote deformities?" },
    { r = {"MERCUTIO"}, t = "Here are the beetle-brows shall blush for me." },
    { r = {"BENVOLIO"}, t = "Come, knock and enter; and no sooner in" },
    { r = {"BENVOLIO"}, t = "But every man betake him to his legs." },
    { r = {"ROMEO"}, t = "A torch for me: let wantons, light of heart," },
    { r = {"ROMEO"}, t = "Tickle the senseless rushes with their heels;" },
    { r = {"ROMEO"}, t = "For I am proverb’d with a grandsire phrase," },
    { r = {"ROMEO"}, t = "I’ll be a candle-holder and look on," },
    { r = {"ROMEO"}, t = "The game was ne’er so fair, and I am done." },
    { r = {"MERCUTIO"}, t = "Tut, dun’s the mouse, the constable’s own word:" },
    { r = {"MERCUTIO"}, t = "If thou art dun, we’ll draw thee from the mire" },
    { r = {"MERCUTIO"}, t = "Or save your reverence love, wherein thou stickest" },
    { r = {"MERCUTIO"}, t = "Up to the ears. Come, we burn daylight, ho." },
    { r = {"ROMEO"}, t = "Nay, that’s not so." },
    { r = {"MERCUTIO"}, t = "I mean sir, in delay" },
    { r = {"MERCUTIO"}, t = "We waste our lights in vain, light lights by day." },
    { r = {"MERCUTIO"}, t = "Take our good meaning, for our judgment sits" },
    { r = {"MERCUTIO"}, t = "Five times in that ere once in our five wits." },
    { r = {"ROMEO"}, t = "And we mean well in going to this mask;" },
    { r = {"ROMEO"}, t = "But ’tis no wit to go." },
    { r = {"MERCUTIO"}, t = "Why, may one ask?" },
    { r = {"ROMEO"}, t = "I dreamt a dream tonight." },
    { r = {"MERCUTIO"}, t = "And so did I." },
    { r = {"ROMEO"}, t = "Well what was yours?" },
    { r = {"MERCUTIO"}, t = "That dreamers often lie." },
    { r = {"ROMEO"}, t = "In bed asleep, while they do dream things true." },
    { r = {"MERCUTIO"}, t = "O, then, I see Queen Mab hath been with you." },
    { r = {"MERCUTIO"}, t = "She is the fairies’ midwife, and she comes" },
    { r = {"MERCUTIO"}, t = "In shape no bigger than an agate-stone" },
    { r = {"MERCUTIO"}, t = "On the fore-finger of an alderman," },
    { r = {"MERCUTIO"}, t = "Drawn with a team of little atomies" },
    { r = {"MERCUTIO"}, t = "Over men’s noses as they lie asleep:" },
    { r = {"MERCUTIO"}, t = "Her waggon-spokes made of long spinners’ legs;" },
    { r = {"MERCUTIO"}, t = "The cover, of the wings of grasshoppers;" },
    { r = {"MERCUTIO"}, t = "Her traces, of the smallest spider’s web;" },
    { r = {"MERCUTIO"}, t = "The collars, of the moonshine’s watery beams;" },
    { r = {"MERCUTIO"}, t = "Her whip of cricket’s bone; the lash, of film;" },
    { r = {"MERCUTIO"}, t = "Her waggoner, a small grey-coated gnat," },
    { r = {"MERCUTIO"}, t = "Not half so big as a round little worm" },
    { r = {"MERCUTIO"}, t = "Prick’d from the lazy finger of a maid:" },
    { r = {"MERCUTIO"}, t = "Her chariot is an empty hazelnut," },
    { r = {"MERCUTIO"}, t = "Made by the joiner squirrel or old grub," },
    { r = {"MERCUTIO"}, t = "Time out o’ mind the fairies’ coachmakers." },
    { r = {"MERCUTIO"}, t = "And in this state she gallops night by night" },
    { r = {"MERCUTIO"}, t = "Through lovers’ brains, and then they dream of love;" },
    { r = {"MERCUTIO"}, t = "O’er courtiers’ knees, that dream on curtsies straight;" },
    { r = {"MERCUTIO"}, t = "O’er lawyers’ fingers, who straight dream on fees;" },
    { r = {"MERCUTIO"}, t = "O’er ladies’ lips, who straight on kisses dream," },
    { r = {"MERCUTIO"}, t = "Which oft the angry Mab with blisters plagues," },
    { r = {"MERCUTIO"}, t = "Because their breaths with sweetmeats tainted are:" },
    { r = {"MERCUTIO"}, t = "Sometime she gallops o’er a courtier’s nose," },
    { r = {"MERCUTIO"}, t = "And then dreams he of smelling out a suit;" },
    { r = {"MERCUTIO"}, t = "And sometime comes she with a tithe-pig’s tail," },
    { r = {"MERCUTIO"}, t = "Tickling a parson’s nose as a lies asleep," },
    { r = {"MERCUTIO"}, t = "Then dreams he of another benefice:" },
    { r = {"MERCUTIO"}, t = "Sometime she driveth o’er a soldier’s neck," },
    { r = {"MERCUTIO"}, t = "And then dreams he of cutting foreign throats," },
    { r = {"MERCUTIO"}, t = "Of breaches, ambuscados, Spanish blades," },
    { r = {"MERCUTIO"}, t = "Of healths five fathom deep; and then anon" },
    { r = {"MERCUTIO"}, t = "Drums in his ear, at which he starts and wakes;" },
    { r = {"MERCUTIO"}, t = "And, being thus frighted, swears a prayer or two," },
    { r = {"MERCUTIO"}, t = "And sleeps again. This is that very Mab" },
    { r = {"MERCUTIO"}, t = "That plats the manes of horses in the night;" },
    { r = {"MERCUTIO"}, t = "And bakes the elf-locks in foul sluttish hairs," },
    { r = {"MERCUTIO"}, t = "Which, once untangled, much misfortune bodes:" },
    { r = {"MERCUTIO"}, t = "This is the hag, when maids lie on their backs," },
    { r = {"MERCUTIO"}, t = "That presses them, and learns them first to bear," },
    { r = {"MERCUTIO"}, t = "Making them women of good carriage:" },
    { r = {"MERCUTIO"}, t = "This is she," },
    { r = {"ROMEO"}, t = "Peace, peace, Mercutio, peace," },
    { r = {"ROMEO"}, t = "Thou talk’st of nothing." },
    { r = {"MERCUTIO"}, t = "True, I talk of dreams," },
    { r = {"MERCUTIO"}, t = "Which are the children of an idle brain," },
    { r = {"MERCUTIO"}, t = "Begot of nothing but vain fantasy," },
    { r = {"MERCUTIO"}, t = "Which is as thin of substance as the air," },
    { r = {"MERCUTIO"}, t = "And more inconstant than the wind, who woos" },
    { r = {"MERCUTIO"}, t = "Even now the frozen bosom of the north," },
    { r = {"MERCUTIO"}, t = "And, being anger’d, puffs away from thence," },
    { r = {"MERCUTIO"}, t = "Turning his side to the dew-dropping south." },
    { r = {"BENVOLIO"}, t = "This wind you talk of blows us from ourselves:" },
    { r = {"BENVOLIO"}, t = "Supper is done, and we shall come too late." },
    { r = {"ROMEO"}, t = "I fear too early: for my mind misgives" },
    { r = {"ROMEO"}, t = "Some consequence yet hanging in the stars," },
    { r = {"ROMEO"}, t = "Shall bitterly begin his fearful date" },
    { r = {"ROMEO"}, t = "With this night’s revels; and expire the term" },
    { r = {"ROMEO"}, t = "Of a despised life, clos’d in my breast" },
    { r = {"ROMEO"}, t = "By some vile forfeit of untimely death." },
    { r = {"ROMEO"}, t = "But he that hath the steerage of my course" },
    { r = {"ROMEO"}, t = "Direct my suit. On, lusty gentlemen!" },
    { r = {"BENVOLIO"}, t = "Strike, drum." },
    { d = "Exeunt" },
    { d = "Act 1, Scene 5. A Hall in Capulet’s House.", h = true },
    { d = "Musicians waiting. Enter Servants" },
    { r = {"FIRST SERVANT"}, t = "Where’s Potpan, that he helps not to take away?" },
    { r = {"FIRST SERVANT"}, t = "He shift a trencher! He scrape a trencher!" },
    { r = {"SECOND SERVANT"}, t = "When good manners shall lie all in one or two men’s hands, and they unwash’d too, ’tis a foul thing." },
    { r = {"FIRST SERVANT"}, t = "Away with the join-stools, remove the court-cupboard, look to the plate." },
    { r = {"FIRST SERVANT"}, t = "Good thou, save me a piece of marchpane; and as thou loves me, let the porter let in Susan Grindstone and Nell." },
    { r = {"FIRST SERVANT"}, t = "Antony and Potpan!" },
    { r = {"SECOND SERVANT"}, t = "Ay, boy, ready." },
    { r = {"FIRST SERVANT"}, t = "You are looked for and called for, asked for and sought for, in the great chamber." },
    { r = {"SECOND SERVANT"}, t = "We cannot be here and there too." },
    { r = {"SECOND SERVANT"}, t = "Cheerly, boys." },
    { r = {"SECOND SERVANT"}, t = "Be brisk awhile, and the longer liver take all." },
    { d = "Exeunt" },
    { d = "Enter Capulet, &c. with the Guests and Gentlewomen to the Maskers" },
    { r = {"CAPULET"}, t = "Welcome, gentlemen, ladies that have their toes" },
    { r = {"CAPULET"}, t = "Unplagu’d with corns will have a bout with you." },
    { r = {"CAPULET"}, t = "Ah my mistresses, which of you all" },
    { r = {"CAPULET"}, t = "Will now deny to dance? She that makes dainty," },
    { r = {"CAPULET"}, t = "She I’ll swear hath corns. Am I come near ye now?" },
    { r = {"CAPULET"}, t = "Welcome, gentlemen! I have seen the day" },
    { r = {"CAPULET"}, t = "That I have worn a visor, and could tell" },
    { r = {"CAPULET"}, t = "A whispering tale in a fair lady’s ear," },
    { r = {"CAPULET"}, t = "Such as would please; ’tis gone, ’tis gone, ’tis gone," },
    { r = {"CAPULET"}, t = "You are welcome, gentlemen! Come, musicians, play." },
    { r = {"CAPULET"}, t = "A hall, a hall, give room! And foot it, girls." },
    { d = "Music plays, and they dance" },
    { r = {"CAPULET"}, t = "More light, you knaves; and turn the tables up," },
    { r = {"CAPULET"}, t = "And quench the fire, the room is grown too hot." },
    { r = {"CAPULET"}, t = "Ah sirrah, this unlook’d-for sport comes well." },
    { r = {"CAPULET"}, t = "Nay sit, nay sit, good cousin Capulet," },
    { r = {"CAPULET"}, t = "For you and I are past our dancing days;" },
    { r = {"CAPULET"}, t = "How long is’t now since last yourself and I" },
    { r = {"CAPULET"}, t = "Were in a mask?" },
    { r = {"CAPULET’S COUSIN"}, t = "By’r Lady, thirty years." },
    { r = {"CAPULET"}, t = "What, man, ’tis not so much, ’tis not so much:" },
    { r = {"CAPULET"}, t = "’Tis since the nuptial of Lucentio," },
    { r = {"CAPULET"}, t = "Come Pentecost as quickly as it will," },
    { r = {"CAPULET"}, t = "Some five and twenty years; and then we mask’d." },
    { r = {"CAPULET’S COUSIN"}, t = "’Tis more, ’tis more, his son is elder, sir;" },
    { r = {"CAPULET’S COUSIN"}, t = "His son is thirty." },
    { r = {"CAPULET"}, t = "Will you tell me that?" },
    { r = {"CAPULET"}, t = "His son was but a ward two years ago." },
    { r = {"ROMEO"}, t = "What lady is that, which doth enrich the hand" },
    { r = {"ROMEO"}, t = "Of yonder knight?" },
    { r = {"SERVANT"}, t = "I know not, sir." },
    { r = {"ROMEO"}, t = "O, she doth teach the torches to burn bright!" },
    { r = {"ROMEO"}, t = "It seems she hangs upon the cheek of night" },
    { r = {"ROMEO"}, t = "As a rich jewel in an Ethiop’s ear;" },
    { r = {"ROMEO"}, t = "Beauty too rich for use, for earth too dear!" },
    { r = {"ROMEO"}, t = "So shows a snowy dove trooping with crows" },
    { r = {"ROMEO"}, t = "As yonder lady o’er her fellows shows." },
    { r = {"ROMEO"}, t = "The measure done, I’ll watch her place of stand," },
    { r = {"ROMEO"}, t = "And touching hers, make blessed my rude hand." },
    { r = {"ROMEO"}, t = "Did my heart love till now? Forswear it, sight!" },
    { r = {"ROMEO"}, t = "For I ne’er saw true beauty till this night." },
    { r = {"TYBALT"}, t = "This by his voice, should be a Montague." },
    { r = {"TYBALT"}, t = "Fetch me my rapier, boy. What, dares the slave" },
    { r = {"TYBALT"}, t = "Come hither, cover’d with an antic face," },
    { r = {"TYBALT"}, t = "To fleer and scorn at our solemnity?" },
    { r = {"TYBALT"}, t = "Now by the stock and honour of my kin," },
    { r = {"TYBALT"}, t = "To strike him dead I hold it not a sin." },
    { r = {"CAPULET"}, t = "Why how now, kinsman!" },
    { r = {"CAPULET"}, t = "Wherefore storm you so?" },
    { r = {"TYBALT"}, t = "Uncle, this is a Montague, our foe;" },
    { r = {"TYBALT"}, t = "A villain that is hither come in spite," },
    { r = {"TYBALT"}, t = "To scorn at our solemnity this night." },
    { r = {"CAPULET"}, t = "Young Romeo, is it?" },
    { r = {"TYBALT"}, t = "’Tis he, that villain Romeo." },
    { r = {"CAPULET"}, t = "Content thee, gentle coz, let him alone," },
    { r = {"CAPULET"}, t = "A bears him like a portly gentleman;" },
    { r = {"CAPULET"}, t = "And, to say truth, Verona brags of him" },
    { r = {"CAPULET"}, t = "To be a virtuous and well-govern’d youth." },
    { r = {"CAPULET"}, t = "I would not for the wealth of all the town" },
    { r = {"CAPULET"}, t = "Here in my house do him disparagement." },
    { r = {"CAPULET"}, t = "Therefore be patient, take no note of him," },
    { r = {"CAPULET"}, t = "It is my will; the which if thou respect," },
    { r = {"CAPULET"}, t = "Show a fair presence and put off these frowns," },
    { r = {"CAPULET"}, t = "An ill-beseeming semblance for a feast." },
    { r = {"TYBALT"}, t = "It fits when such a villain is a guest:" },
    { r = {"TYBALT"}, t = "I’ll not endure him." },
    { r = {"CAPULET"}, t = "He shall be endur’d." },
    { r = {"CAPULET"}, t = "What, goodman boy! I say he shall, go to;" },
    { r = {"CAPULET"}, t = "Am I the master here, or you? Go to." },
    { r = {"CAPULET"}, t = "You’ll not endure him! God shall mend my soul," },
    { r = {"CAPULET"}, t = "You’ll make a mutiny among my guests!" },
    { r = {"CAPULET"}, t = "You will set cock-a-hoop, you’ll be the man!" },
    { r = {"TYBALT"}, t = "Why, uncle, ’tis a shame." },
    { r = {"CAPULET"}, t = "Go to, go to!" },
    { r = {"CAPULET"}, t = "You are a saucy boy. Is’t so, indeed?" },
    { r = {"CAPULET"}, t = "This trick may chance to scathe you, I know what." },
    { r = {"CAPULET"}, t = "You must contrary me! Marry, ’tis time." },
    { r = {"CAPULET"}, t = "Well said, my hearts!—You are a princox; go:" },
    { r = {"CAPULET"}, t = "Be quiet, or—More light, more light!—For shame!" },
    { r = {"CAPULET"}, t = "I’ll make you quiet. What, cheerly, my hearts." },
    { r = {"TYBALT"}, t = "Patience perforce with wilful choler meeting" },
    { r = {"TYBALT"}, t = "Makes my flesh tremble in their different greeting." },
    { r = {"TYBALT"}, t = "I will withdraw: but this intrusion shall," },
    { r = {"TYBALT"}, t = "Now seeming sweet, convert to bitter gall." },
    { d = "Exit" },
    { r = {"ROMEO"}, t = "If I profane with my unworthiest hand", d = "To Juliet" },
    { r = {"ROMEO"}, t = "This holy shrine, the gentle sin is this," },
    { r = {"ROMEO"}, t = "My lips, two blushing pilgrims, ready stand" },
    { r = {"ROMEO"}, t = "To smooth that rough touch with a tender kiss." },
    { r = {"JULIET"}, t = "Good pilgrim, you do wrong your hand too much," },
    { r = {"JULIET"}, t = "Which mannerly devotion shows in this;" },
    { r = {"JULIET"}, t = "For saints have hands that pilgrims’ hands do touch," },
    { r = {"JULIET"}, t = "And palm to palm is holy palmers’ kiss." },
    { r = {"ROMEO"}, t = "Have not saints lips, and holy palmers too?" },
    { r = {"JULIET"}, t = "Ay, pilgrim, lips that they must use in prayer." },
    { r = {"ROMEO"}, t = "O, then, dear saint, let lips do what hands do:" },
    { r = {"ROMEO"}, t = "They pray, grant thou, lest faith turn to despair." },
    { r = {"JULIET"}, t = "Saints do not move, though grant for prayers’ sake." },
    { r = {"ROMEO"}, t = "Then move not while my prayer’s effect I take." },
    { r = {"ROMEO"}, t = "Thus from my lips, by thine my sin is purg’d." },
    { r = {"ROMEO"}, d = "Kissing her", e = "/kiss", at = "JULIET" },
    { r = {"JULIET"}, t = "Then have my lips the sin that they have took." },
    { r = {"ROMEO"}, t = "Sin from my lips? O trespass sweetly urg’d!" },
    { r = {"ROMEO"}, t = "Give me my sin again.", e = "/kiss", at = "JULIET" },
    { r = {"JULIET"}, t = "You kiss by the book." },
    { r = {"NURSE"}, t = "Madam, your mother craves a word with you." },
    { r = {"ROMEO"}, t = "What is her mother?" },
    { r = {"NURSE"}, t = "Marry, bachelor," },
    { r = {"NURSE"}, t = "Her mother is the lady of the house," },
    { r = {"NURSE"}, t = "And a good lady, and a wise and virtuous." },
    { r = {"NURSE"}, t = "I nurs’d her daughter that you talk’d withal." },
    { r = {"NURSE"}, t = "I tell you, he that can lay hold of her" },
    { r = {"NURSE"}, t = "Shall have the chinks." },
    { r = {"ROMEO"}, t = "Is she a Capulet?" },
    { r = {"ROMEO"}, t = "O dear account! My life is my foe’s debt." },
    { r = {"BENVOLIO"}, t = "Away, be gone; the sport is at the best." },
    { r = {"ROMEO"}, t = "Ay, so I fear; the more is my unrest." },
    { r = {"CAPULET"}, t = "Nay, gentlemen, prepare not to be gone," },
    { r = {"CAPULET"}, t = "We have a trifling foolish banquet towards." },
    { r = {"CAPULET"}, t = "Is it e’en so? Why then, I thank you all;" },
    { r = {"CAPULET"}, t = "I thank you, honest gentlemen; good night." },
    { r = {"CAPULET"}, t = "More torches here! Come on then, let’s to bed." },
    { r = {"CAPULET"}, t = "Ah, sirrah, by my fay, it waxes late," },
    { r = {"CAPULET"}, t = "I’ll to my rest." },
    { d = "Exeunt all but Juliet and Nurse" },
    { r = {"JULIET"}, t = "Come hither, Nurse. What is yond gentleman?" },
    { r = {"NURSE"}, t = "The son and heir of old Tiberio." },
    { r = {"JULIET"}, t = "What’s he that now is going out of door?" },
    { r = {"NURSE"}, t = "Marry, that I think be young Petruchio." },
    { r = {"JULIET"}, t = "What’s he that follows here, that would not dance?" },
    { r = {"NURSE"}, t = "I know not." },
    { r = {"JULIET"}, t = "Go ask his name. If he be married," },
    { r = {"JULIET"}, t = "My grave is like to be my wedding bed." },
    { r = {"NURSE"}, t = "His name is Romeo, and a Montague," },
    { r = {"NURSE"}, t = "The only son of your great enemy." },
    { r = {"JULIET"}, t = "My only love sprung from my only hate!" },
    { r = {"JULIET"}, t = "Too early seen unknown, and known too late!" },
    { r = {"JULIET"}, t = "Prodigious birth of love it is to me," },
    { r = {"JULIET"}, t = "That I must love a loathed enemy." },
    { r = {"NURSE"}, t = "What’s this? What’s this?" },
    { r = {"JULIET"}, t = "A rhyme I learn’d even now" },
    { r = {"JULIET"}, t = "Of one I danc’d withal." },
    { d = "One calls within, ‘Juliet’" },
    { r = {"NURSE"}, t = "Anon, anon!" },
    { r = {"NURSE"}, t = "Come let’s away, the strangers all are gone." },
    { d = "Exeunt" },
    { d = "Act 2, Prologue", h = true },
    { d = "Enter Chorus" },
    { r = {"CHORUS"}, t = "Now old desire doth in his deathbed lie," },
    { r = {"CHORUS"}, t = "And young affection gapes to be his heir;" },
    { r = {"CHORUS"}, t = "That fair for which love groan’d for and would die," },
    { r = {"CHORUS"}, t = "With tender Juliet match’d, is now not fair." },
    { r = {"CHORUS"}, t = "Now Romeo is belov’d, and loves again," },
    { r = {"CHORUS"}, t = "Alike bewitched by the charm of looks;" },
    { r = {"CHORUS"}, t = "But to his foe suppos’d he must complain," },
    { r = {"CHORUS"}, t = "And she steal love’s sweet bait from fearful hooks:" },
    { r = {"CHORUS"}, t = "Being held a foe, he may not have access" },
    { r = {"CHORUS"}, t = "To breathe such vows as lovers use to swear;" },
    { r = {"CHORUS"}, t = "And she as much in love, her means much less" },
    { r = {"CHORUS"}, t = "To meet her new beloved anywhere." },
    { r = {"CHORUS"}, t = "But passion lends them power, time means, to meet," },
    { r = {"CHORUS"}, t = "Tempering extremities with extreme sweet." },
    { d = "Exit" },
    { d = "Act 2, Scene 1. An open place adjoining Capulet’s Garden.", h = true },
    { d = "Enter Romeo" },
    { r = {"ROMEO"}, t = "Can I go forward when my heart is here?" },
    { r = {"ROMEO"}, t = "Turn back, dull earth, and find thy centre out." },
    { d = "He climbs the wall and leaps down within it" },
    { d = "Enter Benvolio and Mercutio" },
    { r = {"BENVOLIO"}, t = "Romeo! My cousin Romeo! Romeo!" },
    { r = {"MERCUTIO"}, t = "He is wise," },
    { r = {"MERCUTIO"}, t = "And on my life hath stol’n him home to bed." },
    { r = {"BENVOLIO"}, t = "He ran this way, and leap’d this orchard wall:" },
    { r = {"BENVOLIO"}, t = "Call, good Mercutio." },
    { r = {"MERCUTIO"}, t = "Nay, I’ll conjure too." },
    { r = {"MERCUTIO"}, t = "Romeo! Humours! Madman! Passion! Lover!" },
    { r = {"MERCUTIO"}, t = "Appear thou in the likeness of a sigh," },
    { r = {"MERCUTIO"}, t = "Speak but one rhyme, and I am satisfied;" },
    { r = {"MERCUTIO"}, t = "Cry but ‘Ah me!’ Pronounce but Love and dove;" },
    { r = {"MERCUTIO"}, t = "Speak to my gossip Venus one fair word," },
    { r = {"MERCUTIO"}, t = "One nickname for her purblind son and heir," },
    { r = {"MERCUTIO"}, t = "Young Abraham Cupid, he that shot so trim" },
    { r = {"MERCUTIO"}, t = "When King Cophetua lov’d the beggar-maid." },
    { r = {"MERCUTIO"}, t = "He heareth not, he stirreth not, he moveth not;" },
    { r = {"MERCUTIO"}, t = "The ape is dead, and I must conjure him." },
    { r = {"MERCUTIO"}, t = "I conjure thee by Rosaline’s bright eyes," },
    { r = {"MERCUTIO"}, t = "By her high forehead and her scarlet lip," },
    { r = {"MERCUTIO"}, t = "By her fine foot, straight leg, and quivering thigh," },
    { r = {"MERCUTIO"}, t = "And the demesnes that there adjacent lie," },
    { r = {"MERCUTIO"}, t = "That in thy likeness thou appear to us." },
    { r = {"BENVOLIO"}, t = "An if he hear thee, thou wilt anger him." },
    { r = {"MERCUTIO"}, t = "This cannot anger him. ’Twould anger him" },
    { r = {"MERCUTIO"}, t = "To raise a spirit in his mistress’ circle," },
    { r = {"MERCUTIO"}, t = "Of some strange nature, letting it there stand" },
    { r = {"MERCUTIO"}, t = "Till she had laid it, and conjur’d it down;" },
    { r = {"MERCUTIO"}, t = "That were some spite. My invocation" },
    { r = {"MERCUTIO"}, t = "Is fair and honest, and, in his mistress’ name," },
    { r = {"MERCUTIO"}, t = "I conjure only but to raise up him." },
    { r = {"BENVOLIO"}, t = "Come, he hath hid himself among these trees" },
    { r = {"BENVOLIO"}, t = "To be consorted with the humorous night." },
    { r = {"BENVOLIO"}, t = "Blind is his love, and best befits the dark." },
    { r = {"MERCUTIO"}, t = "If love be blind, love cannot hit the mark." },
    { r = {"MERCUTIO"}, t = "Now will he sit under a medlar tree," },
    { r = {"MERCUTIO"}, t = "And wish his mistress were that kind of fruit" },
    { r = {"MERCUTIO"}, t = "As maids call medlars when they laugh alone." },
    { r = {"MERCUTIO"}, t = "O Romeo, that she were, O that she were" },
    { r = {"MERCUTIO"}, t = "An open-arse and thou a poperin pear!" },
    { r = {"MERCUTIO"}, t = "Romeo, good night. I’ll to my truckle-bed." },
    { r = {"MERCUTIO"}, t = "This field-bed is too cold for me to sleep." },
    { r = {"MERCUTIO"}, t = "Come, shall we go?" },
    { r = {"BENVOLIO"}, t = "Go then; for ’tis in vain" },
    { r = {"BENVOLIO"}, t = "To seek him here that means not to be found." },
    { d = "Exeunt" },
    { d = "Act 2, Scene 2. Capulet’s Garden.", h = true },
    { d = "Enter Romeo" },
    { r = {"ROMEO"}, t = "He jests at scars that never felt a wound." },
    { d = "Juliet appears above at a window" },
    { r = {"ROMEO"}, t = "But soft, what light through yonder window breaks?" },
    { r = {"ROMEO"}, t = "It is the east, and Juliet is the sun!" },
    { r = {"ROMEO"}, t = "Arise fair sun and kill the envious moon," },
    { r = {"ROMEO"}, t = "Who is already sick and pale with grief," },
    { r = {"ROMEO"}, t = "That thou her maid art far more fair than she." },
    { r = {"ROMEO"}, t = "Be not her maid since she is envious;" },
    { r = {"ROMEO"}, t = "Her vestal livery is but sick and green," },
    { r = {"ROMEO"}, t = "And none but fools do wear it; cast it off." },
    { r = {"ROMEO"}, t = "It is my lady, O it is my love!" },
    { r = {"ROMEO"}, t = "O, that she knew she were!" },
    { r = {"ROMEO"}, t = "She speaks, yet she says nothing. What of that?" },
    { r = {"ROMEO"}, t = "Her eye discourses, I will answer it." },
    { r = {"ROMEO"}, t = "I am too bold, ’tis not to me she speaks." },
    { r = {"ROMEO"}, t = "Two of the fairest stars in all the heaven," },
    { r = {"ROMEO"}, t = "Having some business, do entreat her eyes" },
    { r = {"ROMEO"}, t = "To twinkle in their spheres till they return." },
    { r = {"ROMEO"}, t = "What if her eyes were there, they in her head?" },
    { r = {"ROMEO"}, t = "The brightness of her cheek would shame those stars," },
    { r = {"ROMEO"}, t = "As daylight doth a lamp; her eyes in heaven" },
    { r = {"ROMEO"}, t = "Would through the airy region stream so bright" },
    { r = {"ROMEO"}, t = "That birds would sing and think it were not night." },
    { r = {"ROMEO"}, t = "See how she leans her cheek upon her hand." },
    { r = {"ROMEO"}, t = "O that I were a glove upon that hand," },
    { r = {"ROMEO"}, t = "That I might touch that cheek." },
    { r = {"JULIET"}, t = "Ay me." },
    { r = {"ROMEO"}, t = "She speaks." },
    { r = {"ROMEO"}, t = "O speak again bright angel, for thou art" },
    { r = {"ROMEO"}, t = "As glorious to this night, being o’er my head," },
    { r = {"ROMEO"}, t = "As is a winged messenger of heaven" },
    { r = {"ROMEO"}, t = "Unto the white-upturned wondering eyes" },
    { r = {"ROMEO"}, t = "Of mortals that fall back to gaze on him" },
    { r = {"ROMEO"}, t = "When he bestrides the lazy-puffing clouds" },
    { r = {"ROMEO"}, t = "And sails upon the bosom of the air." },
    { r = {"JULIET"}, t = "O Romeo, Romeo, wherefore art thou Romeo?" },
    { r = {"JULIET"}, t = "Deny thy father and refuse thy name." },
    { r = {"JULIET"}, t = "Or if thou wilt not, be but sworn my love," },
    { r = {"JULIET"}, t = "And I’ll no longer be a Capulet." },
    { r = {"ROMEO"}, t = "Shall I hear more, or shall I speak at this?", d = "Aside" },
    { r = {"JULIET"}, t = "’Tis but thy name that is my enemy;" },
    { r = {"JULIET"}, t = "Thou art thyself, though not a Montague." },
    { r = {"JULIET"}, t = "What’s Montague? It is nor hand nor foot," },
    { r = {"JULIET"}, t = "Nor arm, nor face, nor any other part" },
    { r = {"JULIET"}, t = "Belonging to a man. O be some other name." },
    { r = {"JULIET"}, t = "What’s in a name? That which we call a rose" },
    { r = {"JULIET"}, t = "By any other name would smell as sweet;" },
    { r = {"JULIET"}, t = "So Romeo would, were he not Romeo call’d," },
    { r = {"JULIET"}, t = "Retain that dear perfection which he owes" },
    { r = {"JULIET"}, t = "Without that title. Romeo, doff thy name," },
    { r = {"JULIET"}, t = "And for thy name, which is no part of thee," },
    { r = {"JULIET"}, t = "Take all myself." },
    { r = {"ROMEO"}, t = "I take thee at thy word." },
    { r = {"ROMEO"}, t = "Call me but love, and I’ll be new baptis’d;" },
    { r = {"ROMEO"}, t = "Henceforth I never will be Romeo." },
    { r = {"JULIET"}, t = "What man art thou that, thus bescreen’d in night" },
    { r = {"JULIET"}, t = "So stumblest on my counsel?" },
    { r = {"ROMEO"}, t = "By a name" },
    { r = {"ROMEO"}, t = "I know not how to tell thee who I am:" },
    { r = {"ROMEO"}, t = "My name, dear saint, is hateful to myself," },
    { r = {"ROMEO"}, t = "Because it is an enemy to thee." },
    { r = {"ROMEO"}, t = "Had I it written, I would tear the word." },
    { r = {"JULIET"}, t = "My ears have yet not drunk a hundred words" },
    { r = {"JULIET"}, t = "Of thy tongue’s utterance, yet I know the sound." },
    { r = {"JULIET"}, t = "Art thou not Romeo, and a Montague?" },
    { r = {"ROMEO"}, t = "Neither, fair maid, if either thee dislike." },
    { r = {"JULIET"}, t = "How cam’st thou hither, tell me, and wherefore?" },
    { r = {"JULIET"}, t = "The orchard walls are high and hard to climb," },
    { r = {"JULIET"}, t = "And the place death, considering who thou art," },
    { r = {"JULIET"}, t = "If any of my kinsmen find thee here." },
    { r = {"ROMEO"}, t = "With love’s light wings did I o’erperch these walls," },
    { r = {"ROMEO"}, t = "For stony limits cannot hold love out," },
    { r = {"ROMEO"}, t = "And what love can do, that dares love attempt:" },
    { r = {"ROMEO"}, t = "Therefore thy kinsmen are no stop to me." },
    { r = {"JULIET"}, t = "If they do see thee, they will murder thee." },
    { r = {"ROMEO"}, t = "Alack, there lies more peril in thine eye" },
    { r = {"ROMEO"}, t = "Than twenty of their swords. Look thou but sweet," },
    { r = {"ROMEO"}, t = "And I am proof against their enmity." },
    { r = {"JULIET"}, t = "I would not for the world they saw thee here." },
    { r = {"ROMEO"}, t = "I have night’s cloak to hide me from their eyes," },
    { r = {"ROMEO"}, t = "And but thou love me, let them find me here." },
    { r = {"ROMEO"}, t = "My life were better ended by their hate" },
    { r = {"ROMEO"}, t = "Than death prorogued, wanting of thy love." },
    { r = {"JULIET"}, t = "By whose direction found’st thou out this place?" },
    { r = {"ROMEO"}, t = "By love, that first did prompt me to enquire;" },
    { r = {"ROMEO"}, t = "He lent me counsel, and I lent him eyes." },
    { r = {"ROMEO"}, t = "I am no pilot; yet wert thou as far" },
    { r = {"ROMEO"}, t = "As that vast shore wash’d with the farthest sea," },
    { r = {"ROMEO"}, t = "I should adventure for such merchandise." },
    { r = {"JULIET"}, t = "Thou knowest the mask of night is on my face," },
    { r = {"JULIET"}, t = "Else would a maiden blush bepaint my cheek" },
    { r = {"JULIET"}, t = "For that which thou hast heard me speak tonight." },
    { r = {"JULIET"}, t = "Fain would I dwell on form, fain, fain deny" },
    { r = {"JULIET"}, t = "What I have spoke; but farewell compliment." },
    { r = {"JULIET"}, t = "Dost thou love me? I know thou wilt say Ay," },
    { r = {"JULIET"}, t = "And I will take thy word. Yet, if thou swear’st," },
    { r = {"JULIET"}, t = "Thou mayst prove false. At lovers’ perjuries," },
    { r = {"JULIET"}, t = "They say Jove laughs. O gentle Romeo," },
    { r = {"JULIET"}, t = "If thou dost love, pronounce it faithfully." },
    { r = {"JULIET"}, t = "Or if thou thinkest I am too quickly won," },
    { r = {"JULIET"}, t = "I’ll frown and be perverse, and say thee nay," },
    { r = {"JULIET"}, t = "So thou wilt woo. But else, not for the world." },
    { r = {"JULIET"}, t = "In truth, fair Montague, I am too fond;" },
    { r = {"JULIET"}, t = "And therefore thou mayst think my ’haviour light:" },
    { r = {"JULIET"}, t = "But trust me, gentleman, I’ll prove more true" },
    { r = {"JULIET"}, t = "Than those that have more cunning to be strange." },
    { r = {"JULIET"}, t = "I should have been more strange, I must confess," },
    { r = {"JULIET"}, t = "But that thou overheard’st, ere I was ’ware," },
    { r = {"JULIET"}, t = "My true-love passion; therefore pardon me," },
    { r = {"JULIET"}, t = "And not impute this yielding to light love," },
    { r = {"JULIET"}, t = "Which the dark night hath so discovered." },
    { r = {"ROMEO"}, t = "Lady, by yonder blessed moon I vow," },
    { r = {"ROMEO"}, t = "That tips with silver all these fruit-tree tops," },
    { r = {"JULIET"}, t = "O swear not by the moon, th’inconstant moon," },
    { r = {"JULIET"}, t = "That monthly changes in her circled orb," },
    { r = {"JULIET"}, t = "Lest that thy love prove likewise variable." },
    { r = {"ROMEO"}, t = "What shall I swear by?" },
    { r = {"JULIET"}, t = "Do not swear at all." },
    { r = {"JULIET"}, t = "Or if thou wilt, swear by thy gracious self," },
    { r = {"JULIET"}, t = "Which is the god of my idolatry," },
    { r = {"JULIET"}, t = "And I’ll believe thee." },
    { r = {"ROMEO"}, t = "If my heart’s dear love," },
    { r = {"JULIET"}, t = "Well, do not swear. Although I joy in thee," },
    { r = {"JULIET"}, t = "I have no joy of this contract tonight;" },
    { r = {"JULIET"}, t = "It is too rash, too unadvis’d, too sudden," },
    { r = {"JULIET"}, t = "Too like the lightning, which doth cease to be" },
    { r = {"JULIET"}, t = "Ere one can say “It lightens.” Sweet, good night." },
    { r = {"JULIET"}, t = "This bud of love, by summer’s ripening breath," },
    { r = {"JULIET"}, t = "May prove a beauteous flower when next we meet." },
    { r = {"JULIET"}, t = "Good night, good night. As sweet repose and rest" },
    { r = {"JULIET"}, t = "Come to thy heart as that within my breast." },
    { r = {"ROMEO"}, t = "O wilt thou leave me so unsatisfied?" },
    { r = {"JULIET"}, t = "What satisfaction canst thou have tonight?" },
    { r = {"ROMEO"}, t = "Th’exchange of thy love’s faithful vow for mine." },
    { r = {"JULIET"}, t = "I gave thee mine before thou didst request it;" },
    { r = {"JULIET"}, t = "And yet I would it were to give again." },
    { r = {"ROMEO"}, t = "Would’st thou withdraw it? For what purpose, love?" },
    { r = {"JULIET"}, t = "But to be frank and give it thee again." },
    { r = {"JULIET"}, t = "And yet I wish but for the thing I have;" },
    { r = {"JULIET"}, t = "My bounty is as boundless as the sea," },
    { r = {"JULIET"}, t = "My love as deep; the more I give to thee," },
    { r = {"JULIET"}, t = "The more I have, for both are infinite." },
    { r = {"JULIET"}, t = "I hear some noise within. Dear love, adieu." },
    { r = {"JULIET"}, t = "Anon, good Nurse!—Sweet Montague be true.", d = "Nurse calls within" },
    { r = {"JULIET"}, t = "Stay but a little, I will come again." },
    { d = "Exit" },
    { r = {"ROMEO"}, t = "O blessed, blessed night. I am afeard," },
    { r = {"ROMEO"}, t = "Being in night, all this is but a dream," },
    { r = {"ROMEO"}, t = "Too flattering sweet to be substantial." },
    { d = "Enter Juliet above" },
    { r = {"JULIET"}, t = "Three words, dear Romeo, and good night indeed." },
    { r = {"JULIET"}, t = "If that thy bent of love be honourable," },
    { r = {"JULIET"}, t = "Thy purpose marriage, send me word tomorrow," },
    { r = {"JULIET"}, t = "By one that I’ll procure to come to thee," },
    { r = {"JULIET"}, t = "Where and what time thou wilt perform the rite," },
    { r = {"JULIET"}, t = "And all my fortunes at thy foot I’ll lay" },
    { r = {"JULIET"}, t = "And follow thee my lord throughout the world." },
    { r = {"NURSE"}, t = "Madam.", d = "Within" },
    { r = {"JULIET"}, t = "I come, anon.— But if thou meanest not well," },
    { r = {"JULIET"}, t = "I do beseech thee," },
    { r = {"NURSE"}, t = "Madam.", d = "Within" },
    { r = {"JULIET"}, t = "By and by I come—" },
    { r = {"JULIET"}, t = "To cease thy strife and leave me to my grief." },
    { r = {"JULIET"}, t = "Tomorrow will I send." },
    { r = {"ROMEO"}, t = "So thrive my soul," },
    { r = {"JULIET"}, t = "A thousand times good night." },
    { d = "Exit" },
    { r = {"ROMEO"}, t = "A thousand times the worse, to want thy light." },
    { r = {"ROMEO"}, t = "Love goes toward love as schoolboys from their books," },
    { r = {"ROMEO"}, t = "But love from love, towards school with heavy looks." },
    { d = "Retiring slowly" },
    { d = "Re-enter Juliet, above" },
    { r = {"JULIET"}, t = "Hist! Romeo, hist! O for a falconer’s voice" },
    { r = {"JULIET"}, t = "To lure this tassel-gentle back again." },
    { r = {"JULIET"}, t = "Bondage is hoarse and may not speak aloud," },
    { r = {"JULIET"}, t = "Else would I tear the cave where Echo lies," },
    { r = {"JULIET"}, t = "And make her airy tongue more hoarse than mine" },
    { r = {"JULIET"}, t = "With repetition of my Romeo’s name." },
    { r = {"ROMEO"}, t = "It is my soul that calls upon my name." },
    { r = {"ROMEO"}, t = "How silver-sweet sound lovers’ tongues by night," },
    { r = {"ROMEO"}, t = "Like softest music to attending ears." },
    { r = {"JULIET"}, t = "Romeo." },
    { r = {"ROMEO"}, t = "My dear?" },
    { r = {"JULIET"}, t = "What o’clock tomorrow" },
    { r = {"JULIET"}, t = "Shall I send to thee?" },
    { r = {"ROMEO"}, t = "By the hour of nine." },
    { r = {"JULIET"}, t = "I will not fail. ’Tis twenty years till then." },
    { r = {"JULIET"}, t = "I have forgot why I did call thee back." },
    { r = {"ROMEO"}, t = "Let me stand here till thou remember it." },
    { r = {"JULIET"}, t = "I shall forget, to have thee still stand there," },
    { r = {"JULIET"}, t = "Remembering how I love thy company." },
    { r = {"ROMEO"}, t = "And I’ll still stay, to have thee still forget," },
    { r = {"ROMEO"}, t = "Forgetting any other home but this." },
    { r = {"JULIET"}, t = "’Tis almost morning; I would have thee gone," },
    { r = {"JULIET"}, t = "And yet no farther than a wanton’s bird," },
    { r = {"JULIET"}, t = "That lets it hop a little from her hand," },
    { r = {"JULIET"}, t = "Like a poor prisoner in his twisted gyves," },
    { r = {"JULIET"}, t = "And with a silk thread plucks it back again," },
    { r = {"JULIET"}, t = "So loving-jealous of his liberty." },
    { r = {"ROMEO"}, t = "I would I were thy bird." },
    { r = {"JULIET"}, t = "Sweet, so would I:" },
    { r = {"JULIET"}, t = "Yet I should kill thee with much cherishing." },
    { r = {"JULIET"}, t = "Good night, good night. Parting is such sweet sorrow" },
    { r = {"JULIET"}, t = "That I shall say good night till it be morrow." },
    { d = "Exit" },
    { r = {"ROMEO"}, t = "Sleep dwell upon thine eyes, peace in thy breast." },
    { r = {"ROMEO"}, t = "Would I were sleep and peace, so sweet to rest." },
    { r = {"ROMEO"}, t = "Hence will I to my ghostly Sire’s cell," },
    { r = {"ROMEO"}, t = "His help to crave and my dear hap to tell." },
    { d = "Exit" },
    { d = "Act 2, Scene 3. Friar Lawrence’s Cell.", h = true },
    { d = "Enter Friar Lawrence with a basket" },
    { r = {"FRIAR LAWRENCE"}, t = "The grey-ey’d morn smiles on the frowning night," },
    { r = {"FRIAR LAWRENCE"}, t = "Chequering the eastern clouds with streaks of light;" },
    { r = {"FRIAR LAWRENCE"}, t = "And fleckled darkness like a drunkard reels" },
    { r = {"FRIAR LAWRENCE"}, t = "From forth day’s pathway, made by Titan’s fiery wheels" },
    { r = {"FRIAR LAWRENCE"}, t = "Now, ere the sun advance his burning eye," },
    { r = {"FRIAR LAWRENCE"}, t = "The day to cheer, and night’s dank dew to dry," },
    { r = {"FRIAR LAWRENCE"}, t = "I must upfill this osier cage of ours" },
    { r = {"FRIAR LAWRENCE"}, t = "With baleful weeds and precious-juiced flowers." },
    { r = {"FRIAR LAWRENCE"}, t = "The earth that’s nature’s mother, is her tomb;" },
    { r = {"FRIAR LAWRENCE"}, t = "What is her burying grave, that is her womb:" },
    { r = {"FRIAR LAWRENCE"}, t = "And from her womb children of divers kind" },
    { r = {"FRIAR LAWRENCE"}, t = "We sucking on her natural bosom find." },
    { r = {"FRIAR LAWRENCE"}, t = "Many for many virtues excellent," },
    { r = {"FRIAR LAWRENCE"}, t = "None but for some, and yet all different." },
    { r = {"FRIAR LAWRENCE"}, t = "O, mickle is the powerful grace that lies" },
    { r = {"FRIAR LAWRENCE"}, t = "In plants, herbs, stones, and their true qualities." },
    { r = {"FRIAR LAWRENCE"}, t = "For naught so vile that on the earth doth live" },
    { r = {"FRIAR LAWRENCE"}, t = "But to the earth some special good doth give;" },
    { r = {"FRIAR LAWRENCE"}, t = "Nor aught so good but, strain’d from that fair use," },
    { r = {"FRIAR LAWRENCE"}, t = "Revolts from true birth, stumbling on abuse." },
    { r = {"FRIAR LAWRENCE"}, t = "Virtue itself turns vice being misapplied," },
    { r = {"FRIAR LAWRENCE"}, t = "And vice sometime’s by action dignified." },
    { d = "Enter Romeo" },
    { r = {"FRIAR LAWRENCE"}, t = "Within the infant rind of this weak flower" },
    { r = {"FRIAR LAWRENCE"}, t = "Poison hath residence, and medicine power:" },
    { r = {"FRIAR LAWRENCE"}, t = "For this, being smelt, with that part cheers each part;" },
    { r = {"FRIAR LAWRENCE"}, t = "Being tasted, slays all senses with the heart." },
    { r = {"FRIAR LAWRENCE"}, t = "Two such opposed kings encamp them still" },
    { r = {"FRIAR LAWRENCE"}, t = "In man as well as herbs,—grace and rude will;" },
    { r = {"FRIAR LAWRENCE"}, t = "And where the worser is predominant," },
    { r = {"FRIAR LAWRENCE"}, t = "Full soon the canker death eats up that plant." },
    { r = {"ROMEO"}, t = "Good morrow, father." },
    { r = {"FRIAR LAWRENCE"}, t = "Benedicite!" },
    { r = {"FRIAR LAWRENCE"}, t = "What early tongue so sweet saluteth me?" },
    { r = {"FRIAR LAWRENCE"}, t = "Young son, it argues a distemper’d head" },
    { r = {"FRIAR LAWRENCE"}, t = "So soon to bid good morrow to thy bed." },
    { r = {"FRIAR LAWRENCE"}, t = "Care keeps his watch in every old man’s eye," },
    { r = {"FRIAR LAWRENCE"}, t = "And where care lodges sleep will never lie;" },
    { r = {"FRIAR LAWRENCE"}, t = "But where unbruised youth with unstuff’d brain" },
    { r = {"FRIAR LAWRENCE"}, t = "Doth couch his limbs, there golden sleep doth reign." },
    { r = {"FRIAR LAWRENCE"}, t = "Therefore thy earliness doth me assure" },
    { r = {"FRIAR LAWRENCE"}, t = "Thou art uprous’d with some distemperature;" },
    { r = {"FRIAR LAWRENCE"}, t = "Or if not so, then here I hit it right," },
    { r = {"FRIAR LAWRENCE"}, t = "Our Romeo hath not been in bed tonight." },
    { r = {"ROMEO"}, t = "That last is true; the sweeter rest was mine." },
    { r = {"FRIAR LAWRENCE"}, t = "God pardon sin. Wast thou with Rosaline?" },
    { r = {"ROMEO"}, t = "With Rosaline, my ghostly father? No." },
    { r = {"ROMEO"}, t = "I have forgot that name, and that name’s woe." },
    { r = {"FRIAR LAWRENCE"}, t = "That’s my good son. But where hast thou been then?" },
    { r = {"ROMEO"}, t = "I’ll tell thee ere thou ask it me again." },
    { r = {"ROMEO"}, t = "I have been feasting with mine enemy," },
    { r = {"ROMEO"}, t = "Where on a sudden one hath wounded me" },
    { r = {"ROMEO"}, t = "That’s by me wounded. Both our remedies" },
    { r = {"ROMEO"}, t = "Within thy help and holy physic lies." },
    { r = {"ROMEO"}, t = "I bear no hatred, blessed man; for lo," },
    { r = {"ROMEO"}, t = "My intercession likewise steads my foe." },
    { r = {"FRIAR LAWRENCE"}, t = "Be plain, good son, and homely in thy drift;" },
    { r = {"FRIAR LAWRENCE"}, t = "Riddling confession finds but riddling shrift." },
    { r = {"ROMEO"}, t = "Then plainly know my heart’s dear love is set" },
    { r = {"ROMEO"}, t = "On the fair daughter of rich Capulet." },
    { r = {"ROMEO"}, t = "As mine on hers, so hers is set on mine;" },
    { r = {"ROMEO"}, t = "And all combin’d, save what thou must combine" },
    { r = {"ROMEO"}, t = "By holy marriage. When, and where, and how" },
    { r = {"ROMEO"}, t = "We met, we woo’d, and made exchange of vow," },
    { r = {"ROMEO"}, t = "I’ll tell thee as we pass; but this I pray," },
    { r = {"ROMEO"}, t = "That thou consent to marry us today." },
    { r = {"FRIAR LAWRENCE"}, t = "Holy Saint Francis! What a change is here!" },
    { r = {"FRIAR LAWRENCE"}, t = "Is Rosaline, that thou didst love so dear," },
    { r = {"FRIAR LAWRENCE"}, t = "So soon forsaken? Young men’s love then lies" },
    { r = {"FRIAR LAWRENCE"}, t = "Not truly in their hearts, but in their eyes." },
    { r = {"FRIAR LAWRENCE"}, t = "Jesu Maria, what a deal of brine" },
    { r = {"FRIAR LAWRENCE"}, t = "Hath wash’d thy sallow cheeks for Rosaline!" },
    { r = {"FRIAR LAWRENCE"}, t = "How much salt water thrown away in waste," },
    { r = {"FRIAR LAWRENCE"}, t = "To season love, that of it doth not taste." },
    { r = {"FRIAR LAWRENCE"}, t = "The sun not yet thy sighs from heaven clears," },
    { r = {"FRIAR LAWRENCE"}, t = "Thy old groans yet ring in mine ancient ears." },
    { r = {"FRIAR LAWRENCE"}, t = "Lo here upon thy cheek the stain doth sit" },
    { r = {"FRIAR LAWRENCE"}, t = "Of an old tear that is not wash’d off yet." },
    { r = {"FRIAR LAWRENCE"}, t = "If ere thou wast thyself, and these woes thine," },
    { r = {"FRIAR LAWRENCE"}, t = "Thou and these woes were all for Rosaline," },
    { r = {"FRIAR LAWRENCE"}, t = "And art thou chang’d? Pronounce this sentence then," },
    { r = {"FRIAR LAWRENCE"}, t = "Women may fall, when there’s no strength in men." },
    { r = {"ROMEO"}, t = "Thou chidd’st me oft for loving Rosaline." },
    { r = {"FRIAR LAWRENCE"}, t = "For doting, not for loving, pupil mine." },
    { r = {"ROMEO"}, t = "And bad’st me bury love." },
    { r = {"FRIAR LAWRENCE"}, t = "Not in a grave" },
    { r = {"FRIAR LAWRENCE"}, t = "To lay one in, another out to have." },
    { r = {"ROMEO"}, t = "I pray thee chide me not, her I love now" },
    { r = {"ROMEO"}, t = "Doth grace for grace and love for love allow." },
    { r = {"ROMEO"}, t = "The other did not so." },
    { r = {"FRIAR LAWRENCE"}, t = "O, she knew well" },
    { r = {"FRIAR LAWRENCE"}, t = "Thy love did read by rote, that could not spell." },
    { r = {"FRIAR LAWRENCE"}, t = "But come young waverer, come go with me," },
    { r = {"FRIAR LAWRENCE"}, t = "In one respect I’ll thy assistant be;" },
    { r = {"FRIAR LAWRENCE"}, t = "For this alliance may so happy prove," },
    { r = {"FRIAR LAWRENCE"}, t = "To turn your households’ rancour to pure love." },
    { r = {"ROMEO"}, t = "O let us hence; I stand on sudden haste." },
    { r = {"FRIAR LAWRENCE"}, t = "Wisely and slow; they stumble that run fast." },
    { d = "Exeunt" },
    { d = "Act 2, Scene 4. A Street.", h = true },
    { d = "Enter Benvolio and Mercutio" },
    { r = {"MERCUTIO"}, t = "Where the devil should this Romeo be? Came he not home tonight?" },
    { r = {"BENVOLIO"}, t = "Not to his father’s; I spoke with his man." },
    { r = {"MERCUTIO"}, t = "Why, that same pale hard-hearted wench, that Rosaline, torments him so that he will sure run mad." },
    { r = {"BENVOLIO"}, t = "Tybalt, the kinsman to old Capulet, hath sent a letter to his father’s house." },
    { r = {"MERCUTIO"}, t = "A challenge, on my life." },
    { r = {"BENVOLIO"}, t = "Romeo will answer it." },
    { r = {"MERCUTIO"}, t = "Any man that can write may answer a letter." },
    { r = {"BENVOLIO"}, t = "Nay, he will answer the letter’s master, how he dares, being dared." },
    { r = {"MERCUTIO"}, t = "Alas poor Romeo, he is already dead, stabbed with a white wench’s black eye; run through the ear with a love song, the very pin of his heart cleft with the blind bow-boy’s butt-shaft." },
    { r = {"MERCUTIO"}, t = "And is he a man to encounter Tybalt?" },
    { r = {"BENVOLIO"}, t = "Why, what is Tybalt?" },
    { r = {"MERCUTIO"}, t = "More than Prince of cats." },
    { r = {"MERCUTIO"}, t = "O, he’s the courageous captain of compliments." },
    { r = {"MERCUTIO"}, t = "He fights as you sing prick-song, keeps time, distance, and proportion." },
    { r = {"MERCUTIO"}, t = "He rests his minim rest, one, two, and the third in your bosom: the very butcher of a silk button, a duellist, a duellist; a gentleman of the very first house, of the first and second cause." },
    { r = {"MERCUTIO"}, t = "Ah, the immortal passado, the punto reverso, the hay." },
    { r = {"BENVOLIO"}, t = "The what?" },
    { r = {"MERCUTIO"}, t = "The pox of such antic lisping, affecting phantasies; these new tuners of accent." },
    { r = {"MERCUTIO"}, t = "By Jesu, a very good blade, a very tall man, a very good whore." },
    { r = {"MERCUTIO"}, t = "Why, is not this a lamentable thing, grandsire, that we should be thus afflicted with these strange flies, these fashion-mongers, these pardon-me’s, who stand so much on the new form that they cannot sit at ease on the old bench?" },
    { r = {"MERCUTIO"}, t = "O their bones, their bones!" },
    { d = "Enter Romeo" },
    { r = {"BENVOLIO"}, t = "Here comes Romeo, here comes Romeo!" },
    { r = {"MERCUTIO"}, t = "Without his roe, like a dried herring." },
    { r = {"MERCUTIO"}, t = "O flesh, flesh, how art thou fishified!" },
    { r = {"MERCUTIO"}, t = "Now is he for the numbers that Petrarch flowed in." },
    { r = {"MERCUTIO"}, t = "Laura, to his lady, was but a kitchen wench,—marry, she had a better love to berhyme her: Dido a dowdy; Cleopatra a gypsy; Helen and Hero hildings and harlots; Thisbe a grey eye or so, but not to the purpose." },
    { r = {"MERCUTIO"}, t = "Signior Romeo, bonjour!" },
    { r = {"MERCUTIO"}, t = "There’s a French salutation to your French slop." },
    { r = {"MERCUTIO"}, t = "You gave us the counterfeit fairly last night." },
    { r = {"ROMEO"}, t = "Good morrow to you both. What counterfeit did I give you?" },
    { r = {"MERCUTIO"}, t = "The slip sir, the slip; can you not conceive?" },
    { r = {"ROMEO"}, t = "Pardon, good Mercutio, my business was great, and in such a case as mine a man may strain courtesy." },
    { r = {"MERCUTIO"}, t = "That’s as much as to say, such a case as yours constrains a man to bow in the hams." },
    { r = {"ROMEO"}, t = "Meaning, to curtsy." },
    { r = {"MERCUTIO"}, t = "Thou hast most kindly hit it." },
    { r = {"ROMEO"}, t = "A most courteous exposition." },
    { r = {"MERCUTIO"}, t = "Nay, I am the very pink of courtesy." },
    { r = {"ROMEO"}, t = "Pink for flower." },
    { r = {"MERCUTIO"}, t = "Right." },
    { r = {"ROMEO"}, t = "Why, then is my pump well flowered." },
    { r = {"MERCUTIO"}, t = "Sure wit, follow me this jest now, till thou hast worn out thy pump, that when the single sole of it is worn, the jest may remain after the wearing, solely singular." },
    { r = {"ROMEO"}, t = "O single-soled jest, solely singular for the singleness!" },
    { r = {"MERCUTIO"}, t = "Come between us, good Benvolio; my wits faint." },
    { r = {"ROMEO"}, t = "Swits and spurs, swits and spurs; or I’ll cry a match." },
    { r = {"MERCUTIO"}, t = "Nay, if thy wits run the wild-goose chase, I am done." },
    { r = {"MERCUTIO"}, t = "For thou hast more of the wild-goose in one of thy wits, than I am sure, I have in my whole five." },
    { r = {"MERCUTIO"}, t = "Was I with you there for the goose?" },
    { r = {"ROMEO"}, t = "Thou wast never with me for anything, when thou wast not there for the goose." },
    { r = {"MERCUTIO"}, t = "I will bite thee by the ear for that jest." },
    { r = {"ROMEO"}, t = "Nay, good goose, bite not." },
    { r = {"MERCUTIO"}, t = "Thy wit is a very bitter sweeting, it is a most sharp sauce." },
    { r = {"ROMEO"}, t = "And is it not then well served in to a sweet goose?" },
    { r = {"MERCUTIO"}, t = "O here’s a wit of cheveril, that stretches from an inch narrow to an ell broad." },
    { r = {"ROMEO"}, t = "I stretch it out for that word broad, which added to the goose, proves thee far and wide a broad goose." },
    { r = {"MERCUTIO"}, t = "Why, is not this better now than groaning for love?" },
    { r = {"MERCUTIO"}, t = "Now art thou sociable, now art thou Romeo; now art thou what thou art, by art as well as by nature." },
    { r = {"MERCUTIO"}, t = "For this drivelling love is like a great natural, that runs lolling up and down to hide his bauble in a hole." },
    { r = {"BENVOLIO"}, t = "Stop there, stop there." },
    { r = {"MERCUTIO"}, t = "Thou desirest me to stop in my tale against the hair." },
    { r = {"BENVOLIO"}, t = "Thou wouldst else have made thy tale large." },
    { r = {"MERCUTIO"}, t = "O, thou art deceived; I would have made it short, for I was come to the whole depth of my tale, and meant indeed to occupy the argument no longer." },
    { d = "Enter Nurse and Peter" },
    { r = {"ROMEO"}, t = "Here’s goodly gear!" },
    { r = {"ROMEO"}, t = "A sail, a sail!" },
    { r = {"MERCUTIO"}, t = "Two, two; a shirt and a smock." },
    { r = {"NURSE"}, t = "Peter!" },
    { r = {"PETER"}, t = "Anon." },
    { r = {"NURSE"}, t = "My fan, Peter." },
    { r = {"MERCUTIO"}, t = "Good Peter, to hide her face; for her fan’s the fairer face." },
    { r = {"NURSE"}, t = "God ye good morrow, gentlemen." },
    { r = {"MERCUTIO"}, t = "God ye good-den, fair gentlewoman." },
    { r = {"NURSE"}, t = "Is it good-den?" },
    { r = {"MERCUTIO"}, t = "’Tis no less, I tell ye; for the bawdy hand of the dial is now upon the prick of noon." },
    { r = {"NURSE"}, t = "Out upon you! What a man are you?" },
    { r = {"ROMEO"}, t = "One, gentlewoman, that God hath made for himself to mar." },
    { r = {"NURSE"}, t = "By my troth, it is well said; for himself to mar, quoth a?" },
    { r = {"NURSE"}, t = "Gentlemen, can any of you tell me where I may find the young Romeo?" },
    { r = {"ROMEO"}, t = "I can tell you: but young Romeo will be older when you have found him than he was when you sought him." },
    { r = {"ROMEO"}, t = "I am the youngest of that name, for fault of a worse." },
    { r = {"NURSE"}, t = "You say well." },
    { r = {"MERCUTIO"}, t = "Yea, is the worst well? Very well took, i’faith; wisely, wisely." },
    { r = {"NURSE"}, t = "If you be he, sir, I desire some confidence with you." },
    { r = {"BENVOLIO"}, t = "She will endite him to some supper." },
    { r = {"MERCUTIO"}, t = "A bawd, a bawd, a bawd! So ho!" },
    { r = {"ROMEO"}, t = "What hast thou found?" },
    { r = {"MERCUTIO"}, t = "No hare, sir; unless a hare, sir, in a lenten pie, that is something stale and hoar ere it be spent." },
    { r = {"MERCUTIO"}, t = "An old hare hoar,", d = "Sings" },
    { r = {"MERCUTIO"}, t = "And an old hare hoar," },
    { r = {"MERCUTIO"}, t = "Is very good meat in Lent;" },
    { r = {"MERCUTIO"}, t = "But a hare that is hoar" },
    { r = {"MERCUTIO"}, t = "Is too much for a score" },
    { r = {"MERCUTIO"}, t = "When it hoars ere it be spent." },
    { r = {"MERCUTIO"}, t = "Romeo, will you come to your father’s? We’ll to dinner thither." },
    { r = {"ROMEO"}, t = "I will follow you." },
    { r = {"MERCUTIO"}, t = "Farewell, ancient lady; farewell, lady, lady, lady." },
    { d = "Exeunt Mercutio and Benvolio" },
    { r = {"NURSE"}, t = "I pray you, sir, what saucy merchant was this that was so full of his ropery?" },
    { r = {"ROMEO"}, t = "A gentleman, Nurse, that loves to hear himself talk, and will speak more in a minute than he will stand to in a month." },
    { r = {"NURSE"}, t = "And a speak anything against me, I’ll take him down, and a were lustier than he is, and twenty such Jacks." },
    { r = {"NURSE"}, t = "And if I cannot, I’ll find those that shall." },
    { r = {"NURSE"}, t = "Scurvy knave!" },
    { r = {"NURSE"}, t = "I am none of his flirt-gills; I am none of his skains-mates.—And thou must stand by too and suffer every knave to use me at his pleasure!" },
    { r = {"PETER"}, t = "I saw no man use you at his pleasure; if I had, my weapon should quickly have been out." },
    { r = {"PETER"}, t = "I warrant you, I dare draw as soon as another man, if I see occasion in a good quarrel, and the law on my side." },
    { r = {"NURSE"}, t = "Now, afore God, I am so vexed that every part about me quivers." },
    { r = {"NURSE"}, t = "Scurvy knave." },
    { r = {"NURSE"}, t = "Pray you, sir, a word: and as I told you, my young lady bid me enquire you out; what she bade me say, I will keep to myself." },
    { r = {"NURSE"}, t = "But first let me tell ye, if ye should lead her in a fool’s paradise, as they say, it were a very gross kind of behaviour, as they say; for the gentlewoman is young." },
    { r = {"NURSE"}, t = "And therefore, if you should deal double with her, truly it were an ill thing to be offered to any gentlewoman, and very weak dealing." },
    { r = {"ROMEO"}, t = "Nurse, commend me to thy lady and mistress." },
    { r = {"ROMEO"}, t = "I protest unto thee," },
    { r = {"NURSE"}, t = "Good heart, and i’faith I will tell her as much." },
    { r = {"NURSE"}, t = "Lord, Lord, she will be a joyful woman." },
    { r = {"ROMEO"}, t = "What wilt thou tell her, Nurse? Thou dost not mark me." },
    { r = {"NURSE"}, t = "I will tell her, sir, that you do protest, which, as I take it, is a gentlemanlike offer." },
    { r = {"ROMEO"}, t = "Bid her devise" },
    { r = {"ROMEO"}, t = "Some means to come to shrift this afternoon," },
    { r = {"ROMEO"}, t = "And there she shall at Friar Lawrence’ cell" },
    { r = {"ROMEO"}, t = "Be shriv’d and married. Here is for thy pains." },
    { r = {"NURSE"}, t = "No truly, sir; not a penny." },
    { r = {"ROMEO"}, t = "Go to; I say you shall." },
    { r = {"NURSE"}, t = "This afternoon, sir? Well, she shall be there." },
    { r = {"ROMEO"}, t = "And stay, good Nurse, behind the abbey wall." },
    { r = {"ROMEO"}, t = "Within this hour my man shall be with thee," },
    { r = {"ROMEO"}, t = "And bring thee cords made like a tackled stair," },
    { r = {"ROMEO"}, t = "Which to the high topgallant of my joy" },
    { r = {"ROMEO"}, t = "Must be my convoy in the secret night." },
    { r = {"ROMEO"}, t = "Farewell, be trusty, and I’ll quit thy pains;" },
    { r = {"ROMEO"}, t = "Farewell; commend me to thy mistress." },
    { r = {"NURSE"}, t = "Now God in heaven bless thee. Hark you, sir." },
    { r = {"ROMEO"}, t = "What say’st thou, my dear Nurse?" },
    { r = {"NURSE"}, t = "Is your man secret? Did you ne’er hear say," },
    { r = {"NURSE"}, t = "Two may keep counsel, putting one away?" },
    { r = {"ROMEO"}, t = "I warrant thee my man’s as true as steel." },
    { r = {"NURSE"}, t = "Well, sir, my mistress is the sweetest lady." },
    { r = {"NURSE"}, t = "Lord, Lord!" },
    { r = {"NURSE"}, t = "When ’twas a little prating thing,—O, there is a nobleman in town, one Paris, that would fain lay knife aboard; but she, good soul, had as lief see a toad, a very toad, as see him." },
    { r = {"NURSE"}, t = "I anger her sometimes, and tell her that Paris is the properer man, but I’ll warrant you, when I say so, she looks as pale as any clout in the versal world." },
    { r = {"NURSE"}, t = "Doth not rosemary and Romeo begin both with a letter?" },
    { r = {"ROMEO"}, t = "Ay, Nurse; what of that? Both with an R." },
    { r = {"NURSE"}, t = "Ah, mocker!" },
    { r = {"NURSE"}, t = "That’s the dog’s name." },
    { r = {"NURSE"}, t = "R is for the—no, I know it begins with some other letter, and she hath the prettiest sententious of it, of you and rosemary, that it would do you good to hear it." },
    { r = {"ROMEO"}, t = "Commend me to thy lady." },
    { r = {"NURSE"}, t = "Ay, a thousand times. Peter!" },
    { d = "Exit Romeo" },
    { r = {"PETER"}, t = "Anon." },
    { r = {"NURSE"}, t = "Before and apace." },
    { d = "Exeunt" },
    { d = "Act 2, Scene 5. Capulet’s Garden.", h = true },
    { d = "Enter Juliet" },
    { r = {"JULIET"}, t = "The clock struck nine when I did send the Nurse," },
    { r = {"JULIET"}, t = "In half an hour she promised to return." },
    { r = {"JULIET"}, t = "Perchance she cannot meet him. That’s not so." },
    { r = {"JULIET"}, t = "O, she is lame. Love’s heralds should be thoughts," },
    { r = {"JULIET"}, t = "Which ten times faster glides than the sun’s beams," },
    { r = {"JULIET"}, t = "Driving back shadows over lowering hills:" },
    { r = {"JULIET"}, t = "Therefore do nimble-pinion’d doves draw love," },
    { r = {"JULIET"}, t = "And therefore hath the wind-swift Cupid wings." },
    { r = {"JULIET"}, t = "Now is the sun upon the highmost hill" },
    { r = {"JULIET"}, t = "Of this day’s journey, and from nine till twelve" },
    { r = {"JULIET"}, t = "Is three long hours, yet she is not come." },
    { r = {"JULIET"}, t = "Had she affections and warm youthful blood," },
    { r = {"JULIET"}, t = "She’d be as swift in motion as a ball;" },
    { r = {"JULIET"}, t = "My words would bandy her to my sweet love," },
    { r = {"JULIET"}, t = "And his to me." },
    { r = {"JULIET"}, t = "But old folks, many feign as they were dead;" },
    { r = {"JULIET"}, t = "Unwieldy, slow, heavy and pale as lead." },
    { d = "Enter Nurse and Peter" },
    { r = {"JULIET"}, t = "O God, she comes. O honey Nurse, what news?" },
    { r = {"JULIET"}, t = "Hast thou met with him? Send thy man away." },
    { r = {"NURSE"}, t = "Peter, stay at the gate." },
    { d = "Exit Peter" },
    { r = {"JULIET"}, t = "Now, good sweet Nurse,—O Lord, why look’st thou sad?" },
    { r = {"JULIET"}, t = "Though news be sad, yet tell them merrily;" },
    { r = {"JULIET"}, t = "If good, thou sham’st the music of sweet news" },
    { r = {"JULIET"}, t = "By playing it to me with so sour a face." },
    { r = {"NURSE"}, t = "I am aweary, give me leave awhile;" },
    { r = {"NURSE"}, t = "Fie, how my bones ache! What a jaunt have I had!" },
    { r = {"JULIET"}, t = "I would thou hadst my bones, and I thy news:" },
    { r = {"JULIET"}, t = "Nay come, I pray thee speak; good, good Nurse, speak." },
    { r = {"NURSE"}, t = "Jesu, what haste?" },
    { r = {"NURSE"}, t = "Can you not stay a while?" },
    { r = {"NURSE"}, t = "Do you not see that I am out of breath?" },
    { r = {"JULIET"}, t = "How art thou out of breath, when thou hast breath" },
    { r = {"JULIET"}, t = "To say to me that thou art out of breath?" },
    { r = {"JULIET"}, t = "The excuse that thou dost make in this delay" },
    { r = {"JULIET"}, t = "Is longer than the tale thou dost excuse." },
    { r = {"JULIET"}, t = "Is thy news good or bad? Answer to that;" },
    { r = {"JULIET"}, t = "Say either, and I’ll stay the circumstance." },
    { r = {"JULIET"}, t = "Let me be satisfied, is’t good or bad?" },
    { r = {"NURSE"}, t = "Well, you have made a simple choice; you know not how to choose a man." },
    { r = {"NURSE"}, t = "Romeo?" },
    { r = {"NURSE"}, t = "No, not he." },
    { r = {"NURSE"}, t = "Though his face be better than any man’s, yet his leg excels all men’s, and for a hand and a foot, and a body, though they be not to be talked on, yet they are past compare." },
    { r = {"NURSE"}, t = "He is not the flower of courtesy, but I’ll warrant him as gentle as a lamb." },
    { r = {"NURSE"}, t = "Go thy ways, wench, serve God." },
    { r = {"NURSE"}, t = "What, have you dined at home?" },
    { r = {"JULIET"}, t = "No, no. But all this did I know before." },
    { r = {"JULIET"}, t = "What says he of our marriage? What of that?" },
    { r = {"NURSE"}, t = "Lord, how my head aches! What a head have I!" },
    { r = {"NURSE"}, t = "It beats as it would fall in twenty pieces." },
    { r = {"NURSE"}, t = "My back o’ t’other side,—O my back, my back!" },
    { r = {"NURSE"}, t = "Beshrew your heart for sending me about" },
    { r = {"NURSE"}, t = "To catch my death with jauncing up and down." },
    { r = {"JULIET"}, t = "I’faith, I am sorry that thou art not well." },
    { r = {"JULIET"}, t = "Sweet, sweet, sweet Nurse, tell me, what says my love?" },
    { r = {"NURSE"}, t = "Your love says like an honest gentleman," },
    { r = {"NURSE"}, t = "And a courteous, and a kind, and a handsome," },
    { r = {"NURSE"}, t = "And I warrant a virtuous,—Where is your mother?" },
    { r = {"JULIET"}, t = "Where is my mother? Why, she is within." },
    { r = {"JULIET"}, t = "Where should she be? How oddly thou repliest." },
    { r = {"JULIET"}, t = "‘Your love says, like an honest gentleman," },
    { r = {"JULIET"}, t = "‘Where is your mother?’" },
    { r = {"NURSE"}, t = "O God’s lady dear," },
    { r = {"NURSE"}, t = "Are you so hot? Marry, come up, I trow." },
    { r = {"NURSE"}, t = "Is this the poultice for my aching bones?" },
    { r = {"NURSE"}, t = "Henceforward do your messages yourself." },
    { r = {"JULIET"}, t = "Here’s such a coil. Come, what says Romeo?" },
    { r = {"NURSE"}, t = "Have you got leave to go to shrift today?" },
    { r = {"JULIET"}, t = "I have." },
    { r = {"NURSE"}, t = "Then hie you hence to Friar Lawrence’ cell;" },
    { r = {"NURSE"}, t = "There stays a husband to make you a wife." },
    { r = {"NURSE"}, t = "Now comes the wanton blood up in your cheeks," },
    { r = {"NURSE"}, t = "They’ll be in scarlet straight at any news." },
    { r = {"NURSE"}, t = "Hie you to church. I must another way," },
    { r = {"NURSE"}, t = "To fetch a ladder by the which your love" },
    { r = {"NURSE"}, t = "Must climb a bird’s nest soon when it is dark." },
    { r = {"NURSE"}, t = "I am the drudge, and toil in your delight;" },
    { r = {"NURSE"}, t = "But you shall bear the burden soon at night." },
    { r = {"NURSE"}, t = "Go. I’ll to dinner; hie you to the cell." },
    { r = {"JULIET"}, t = "Hie to high fortune! Honest Nurse, farewell." },
    { d = "Exeunt" },
    { d = "Act 2, Scene 6. Friar Lawrence’s Cell.", h = true },
    { d = "Enter Friar Lawrence and Romeo" },
    { r = {"FRIAR LAWRENCE"}, t = "So smile the heavens upon this holy act" },
    { r = {"FRIAR LAWRENCE"}, t = "That after-hours with sorrow chide us not." },
    { r = {"ROMEO"}, t = "Amen, amen, but come what sorrow can," },
    { r = {"ROMEO"}, t = "It cannot countervail the exchange of joy" },
    { r = {"ROMEO"}, t = "That one short minute gives me in her sight." },
    { r = {"ROMEO"}, t = "Do thou but close our hands with holy words," },
    { r = {"ROMEO"}, t = "Then love-devouring death do what he dare," },
    { r = {"ROMEO"}, t = "It is enough I may but call her mine." },
    { r = {"FRIAR LAWRENCE"}, t = "These violent delights have violent ends," },
    { r = {"FRIAR LAWRENCE"}, t = "And in their triumph die; like fire and powder," },
    { r = {"FRIAR LAWRENCE"}, t = "Which as they kiss consume. The sweetest honey" },
    { r = {"FRIAR LAWRENCE"}, t = "Is loathsome in his own deliciousness," },
    { r = {"FRIAR LAWRENCE"}, t = "And in the taste confounds the appetite." },
    { r = {"FRIAR LAWRENCE"}, t = "Therefore love moderately: long love doth so;" },
    { r = {"FRIAR LAWRENCE"}, t = "Too swift arrives as tardy as too slow." },
    { d = "Enter Juliet" },
    { r = {"FRIAR LAWRENCE"}, t = "Here comes the lady. O, so light a foot" },
    { r = {"FRIAR LAWRENCE"}, t = "Will ne’er wear out the everlasting flint." },
    { r = {"FRIAR LAWRENCE"}, t = "A lover may bestride the gossamers" },
    { r = {"FRIAR LAWRENCE"}, t = "That idles in the wanton summer air" },
    { r = {"FRIAR LAWRENCE"}, t = "And yet not fall; so light is vanity." },
    { r = {"JULIET"}, t = "Good even to my ghostly confessor." },
    { r = {"FRIAR LAWRENCE"}, t = "Romeo shall thank thee, daughter, for us both." },
    { r = {"JULIET"}, t = "As much to him, else is his thanks too much." },
    { r = {"ROMEO"}, t = "Ah, Juliet, if the measure of thy joy" },
    { r = {"ROMEO"}, t = "Be heap’d like mine, and that thy skill be more" },
    { r = {"ROMEO"}, t = "To blazon it, then sweeten with thy breath" },
    { r = {"ROMEO"}, t = "This neighbour air, and let rich music’s tongue" },
    { r = {"ROMEO"}, t = "Unfold the imagin’d happiness that both" },
    { r = {"ROMEO"}, t = "Receive in either by this dear encounter." },
    { r = {"JULIET"}, t = "Conceit more rich in matter than in words," },
    { r = {"JULIET"}, t = "Brags of his substance, not of ornament." },
    { r = {"JULIET"}, t = "They are but beggars that can count their worth;" },
    { r = {"JULIET"}, t = "But my true love is grown to such excess," },
    { r = {"JULIET"}, t = "I cannot sum up sum of half my wealth." },
    { r = {"FRIAR LAWRENCE"}, t = "Come, come with me, and we will make short work," },
    { r = {"FRIAR LAWRENCE"}, t = "For, by your leaves, you shall not stay alone" },
    { r = {"FRIAR LAWRENCE"}, t = "Till holy church incorporate two in one." },
    { d = "Exeunt" },
    { d = "Act 3, Scene 1. A public Place.", h = true },
    { d = "Enter Mercutio, Benvolio, Page and Servants" },
    { r = {"BENVOLIO"}, t = "I pray thee, good Mercutio, let’s retire:" },
    { r = {"BENVOLIO"}, t = "The day is hot, the Capulets abroad," },
    { r = {"BENVOLIO"}, t = "And if we meet, we shall not scape a brawl," },
    { r = {"BENVOLIO"}, t = "For now these hot days, is the mad blood stirring." },
    { r = {"MERCUTIO"}, t = "Thou art like one of these fellows that, when he enters the confines of a tavern, claps me his sword upon the table, and says ‘God send me no need of thee!’ and by the operation of the second cup draws him on the drawer," },
    { r = {"MERCUTIO"}, t = "when indeed there is no need." },
    { r = {"BENVOLIO"}, t = "Am I like such a fellow?" },
    { r = {"MERCUTIO"}, t = "Come, come, thou art as hot a Jack in thy mood as any in Italy; and as soon moved to be moody, and as soon moody to be moved." },
    { r = {"BENVOLIO"}, t = "And what to?" },
    { r = {"MERCUTIO"}, t = "Nay, an there were two such, we should have none shortly, for one would kill the other." },
    { r = {"MERCUTIO"}, t = "Thou?" },
    { r = {"MERCUTIO"}, t = "Why, thou wilt quarrel with a man that hath a hair more or a hair less in his beard than thou hast." },
    { r = {"MERCUTIO"}, t = "Thou wilt quarrel with a man for cracking nuts, having no other reason but because thou hast hazel eyes." },
    { r = {"MERCUTIO"}, t = "What eye but such an eye would spy out such a quarrel?" },
    { r = {"MERCUTIO"}, t = "Thy head is as full of quarrels as an egg is full of meat, and yet thy head hath been beaten as addle as an egg for quarrelling." },
    { r = {"MERCUTIO"}, t = "Thou hast quarrelled with a man for coughing in the street, because he hath wakened thy dog that hath lain asleep in the sun." },
    { r = {"MERCUTIO"}, t = "Didst thou not fall out with a tailor for wearing his new doublet before Easter? with another for tying his new shoes with an old riband?" },
    { r = {"MERCUTIO"}, t = "And yet thou wilt tutor me from quarrelling!" },
    { r = {"BENVOLIO"}, t = "And I were so apt to quarrel as thou art, any man should buy the fee simple of my life for an hour and a quarter." },
    { r = {"MERCUTIO"}, t = "The fee simple! O simple!" },
    { d = "Enter Tybalt and others" },
    { r = {"BENVOLIO"}, t = "By my head, here comes the Capulets." },
    { r = {"MERCUTIO"}, t = "By my heel, I care not." },
    { r = {"TYBALT"}, t = "Follow me close, for I will speak to them." },
    { r = {"TYBALT"}, t = "Gentlemen, good-den: a word with one of you." },
    { r = {"MERCUTIO"}, t = "And but one word with one of us?" },
    { r = {"MERCUTIO"}, t = "Couple it with something; make it a word and a blow." },
    { r = {"TYBALT"}, t = "You shall find me apt enough to that, sir, and you will give me occasion." },
    { r = {"MERCUTIO"}, t = "Could you not take some occasion without giving?" },
    { r = {"TYBALT"}, t = "Mercutio, thou consortest with Romeo." },
    { r = {"MERCUTIO"}, t = "Consort?" },
    { r = {"MERCUTIO"}, t = "What, dost thou make us minstrels?" },
    { r = {"MERCUTIO"}, t = "And thou make minstrels of us, look to hear nothing but discords." },
    { r = {"MERCUTIO"}, t = "Here’s my fiddlestick, here’s that shall make you dance." },
    { r = {"MERCUTIO"}, t = "Zounds, consort!" },
    { r = {"BENVOLIO"}, t = "We talk here in the public haunt of men." },
    { r = {"BENVOLIO"}, t = "Either withdraw unto some private place," },
    { r = {"BENVOLIO"}, t = "And reason coldly of your grievances," },
    { r = {"BENVOLIO"}, t = "Or else depart; here all eyes gaze on us." },
    { r = {"MERCUTIO"}, t = "Men’s eyes were made to look, and let them gaze." },
    { r = {"MERCUTIO"}, t = "I will not budge for no man’s pleasure, I." },
    { d = "Enter Romeo" },
    { r = {"TYBALT"}, t = "Well, peace be with you, sir, here comes my man." },
    { r = {"MERCUTIO"}, t = "But I’ll be hanged, sir, if he wear your livery." },
    { r = {"MERCUTIO"}, t = "Marry, go before to field, he’ll be your follower;" },
    { r = {"MERCUTIO"}, t = "Your worship in that sense may call him man." },
    { r = {"TYBALT"}, t = "Romeo, the love I bear thee can afford" },
    { r = {"TYBALT"}, t = "No better term than this: Thou art a villain." },
    { r = {"ROMEO"}, t = "Tybalt, the reason that I have to love thee" },
    { r = {"ROMEO"}, t = "Doth much excuse the appertaining rage" },
    { r = {"ROMEO"}, t = "To such a greeting. Villain am I none;" },
    { r = {"ROMEO"}, t = "Therefore farewell; I see thou know’st me not." },
    { r = {"TYBALT"}, t = "Boy, this shall not excuse the injuries" },
    { r = {"TYBALT"}, t = "That thou hast done me, therefore turn and draw." },
    { r = {"ROMEO"}, t = "I do protest I never injur’d thee," },
    { r = {"ROMEO"}, t = "But love thee better than thou canst devise" },
    { r = {"ROMEO"}, t = "Till thou shalt know the reason of my love." },
    { r = {"ROMEO"}, t = "And so good Capulet, which name I tender" },
    { r = {"ROMEO"}, t = "As dearly as mine own, be satisfied." },
    { r = {"MERCUTIO"}, t = "O calm, dishonourable, vile submission!" },
    { r = {"MERCUTIO"}, t = "Alla stoccata carries it away.", d = "Draws" },
    { r = {"MERCUTIO"}, t = "Tybalt, you rat-catcher, will you walk?" },
    { r = {"TYBALT"}, t = "What wouldst thou have with me?" },
    { r = {"MERCUTIO"}, t = "Good King of Cats, nothing but one of your nine lives; that I mean to make bold withal, and, as you shall use me hereafter, dry-beat the rest of the eight." },
    { r = {"MERCUTIO"}, t = "Will you pluck your sword out of his pilcher by the ears?" },
    { r = {"MERCUTIO"}, t = "Make haste, lest mine be about your ears ere it be out." },
    { r = {"TYBALT"}, t = "I am for you.", d = "Drawing" },
    { r = {"ROMEO"}, t = "Gentle Mercutio, put thy rapier up." },
    { r = {"MERCUTIO"}, t = "Come, sir, your passado." },
    { d = "They fight" },
    { r = {"ROMEO"}, t = "Draw, Benvolio; beat down their weapons." },
    { r = {"ROMEO"}, t = "Gentlemen, for shame, forbear this outrage," },
    { r = {"ROMEO"}, t = "Tybalt, Mercutio, the Prince expressly hath" },
    { r = {"ROMEO"}, t = "Forbid this bandying in Verona streets." },
    { r = {"ROMEO"}, t = "Hold, Tybalt! Good Mercutio!" },
    { d = "Exeunt Tybalt with his Partizans" },
    { r = {"MERCUTIO"}, t = "I am hurt." },
    { r = {"MERCUTIO"}, t = "A plague o’ both your houses. I am sped." },
    { r = {"MERCUTIO"}, t = "Is he gone, and hath nothing?" },
    { r = {"BENVOLIO"}, t = "What, art thou hurt?" },
    { r = {"MERCUTIO"}, t = "Ay, ay, a scratch, a scratch. Marry, ’tis enough." },
    { r = {"MERCUTIO"}, t = "Where is my page? Go villain, fetch a surgeon." },
    { d = "Exit Page" },
    { r = {"ROMEO"}, t = "Courage, man; the hurt cannot be much." },
    { r = {"MERCUTIO"}, t = "No, ’tis not so deep as a well, nor so wide as a church door, but ’tis enough, ’twill serve." },
    { r = {"MERCUTIO"}, t = "Ask for me tomorrow, and you shall find me a grave man." },
    { r = {"MERCUTIO"}, t = "I am peppered, I warrant, for this world." },
    { r = {"MERCUTIO"}, t = "A plague o’ both your houses." },
    { r = {"MERCUTIO"}, t = "Zounds, a dog, a rat, a mouse, a cat, to scratch a man to death." },
    { r = {"MERCUTIO"}, t = "A braggart, a rogue, a villain, that fights by the book of arithmetic!—Why the devil came you between us?" },
    { r = {"MERCUTIO"}, t = "I was hurt under your arm." },
    { r = {"ROMEO"}, t = "I thought all for the best." },
    { r = {"MERCUTIO"}, t = "Help me into some house, Benvolio," },
    { r = {"MERCUTIO"}, t = "Or I shall faint. A plague o’ both your houses." },
    { r = {"MERCUTIO"}, t = "They have made worms’ meat of me." },
    { r = {"MERCUTIO"}, t = "I have it, and soundly too. Your houses!" },
    { d = "Exeunt Mercutio and Benvolio" },
    { r = {"ROMEO"}, t = "This gentleman, the Prince’s near ally," },
    { r = {"ROMEO"}, t = "My very friend, hath got his mortal hurt" },
    { r = {"ROMEO"}, t = "In my behalf; my reputation stain’d" },
    { r = {"ROMEO"}, t = "With Tybalt’s slander,—Tybalt, that an hour" },
    { r = {"ROMEO"}, t = "Hath been my cousin. O sweet Juliet," },
    { r = {"ROMEO"}, t = "Thy beauty hath made me effeminate" },
    { r = {"ROMEO"}, t = "And in my temper soften’d valour’s steel." },
    { d = "Re-enter Benvolio" },
    { r = {"BENVOLIO"}, t = "O Romeo, Romeo, brave Mercutio’s dead," },
    { r = {"BENVOLIO"}, t = "That gallant spirit hath aspir’d the clouds," },
    { r = {"BENVOLIO"}, t = "Which too untimely here did scorn the earth." },
    { r = {"ROMEO"}, t = "This day’s black fate on mo days doth depend;" },
    { r = {"ROMEO"}, t = "This but begins the woe others must end." },
    { d = "Re-enter Tybalt" },
    { r = {"BENVOLIO"}, t = "Here comes the furious Tybalt back again." },
    { r = {"ROMEO"}, t = "Again in triumph, and Mercutio slain?" },
    { r = {"ROMEO"}, t = "Away to heaven respective lenity," },
    { r = {"ROMEO"}, t = "And fire-ey’d fury be my conduct now!" },
    { r = {"ROMEO"}, t = "Now, Tybalt, take the ‘villain’ back again" },
    { r = {"ROMEO"}, t = "That late thou gav’st me, for Mercutio’s soul" },
    { r = {"ROMEO"}, t = "Is but a little way above our heads," },
    { r = {"ROMEO"}, t = "Staying for thine to keep him company." },
    { r = {"ROMEO"}, t = "Either thou or I, or both, must go with him." },
    { r = {"TYBALT"}, t = "Thou wretched boy, that didst consort him here," },
    { r = {"TYBALT"}, t = "Shalt with him hence." },
    { r = {"ROMEO"}, t = "This shall determine that." },
    { r = {"TYBALT"}, d = "They fight; Tybalt falls", e = "/lie", s = {"Feign Death"} },
    { r = {"BENVOLIO"}, t = "Romeo, away, be gone!" },
    { r = {"BENVOLIO"}, t = "The citizens are up, and Tybalt slain." },
    { r = {"BENVOLIO"}, t = "Stand not amaz’d. The Prince will doom thee death" },
    { r = {"BENVOLIO"}, t = "If thou art taken. Hence, be gone, away!" },
    { r = {"ROMEO"}, t = "O, I am fortune’s fool!" },
    { r = {"BENVOLIO"}, t = "Why dost thou stay?" },
    { d = "Exit Romeo" },
    { d = "Enter Citizens" },
    { r = {"FIRST CITIZEN"}, t = "Which way ran he that kill’d Mercutio?" },
    { r = {"FIRST CITIZEN"}, t = "Tybalt, that murderer, which way ran he?" },
    { r = {"BENVOLIO"}, t = "There lies that Tybalt." },
    { r = {"FIRST CITIZEN"}, t = "Up, sir, go with me." },
    { r = {"FIRST CITIZEN"}, t = "I charge thee in the Prince’s name obey." },
    { d = "Enter Prince, attended; Montague, Capulet, their Wives and others" },
    { r = {"ESCALUS"}, t = "Where are the vile beginners of this fray?" },
    { r = {"BENVOLIO"}, t = "O noble Prince, I can discover all" },
    { r = {"BENVOLIO"}, t = "The unlucky manage of this fatal brawl." },
    { r = {"BENVOLIO"}, t = "There lies the man, slain by young Romeo," },
    { r = {"BENVOLIO"}, t = "That slew thy kinsman, brave Mercutio." },
    { r = {"LADY CAPULET"}, t = "Tybalt, my cousin! O my brother’s child!" },
    { r = {"LADY CAPULET"}, t = "O Prince! O husband! O, the blood is spill’d" },
    { r = {"LADY CAPULET"}, t = "Of my dear kinsman! Prince, as thou art true," },
    { r = {"LADY CAPULET"}, t = "For blood of ours shed blood of Montague." },
    { r = {"LADY CAPULET"}, t = "O cousin, cousin." },
    { r = {"ESCALUS"}, t = "Benvolio, who began this bloody fray?" },
    { r = {"BENVOLIO"}, t = "Tybalt, here slain, whom Romeo’s hand did slay;" },
    { r = {"BENVOLIO"}, t = "Romeo, that spoke him fair, bid him bethink" },
    { r = {"BENVOLIO"}, t = "How nice the quarrel was, and urg’d withal" },
    { r = {"BENVOLIO"}, t = "Your high displeasure. All this uttered" },
    { r = {"BENVOLIO"}, t = "With gentle breath, calm look, knees humbly bow’d" },
    { r = {"BENVOLIO"}, t = "Could not take truce with the unruly spleen" },
    { r = {"BENVOLIO"}, t = "Of Tybalt, deaf to peace, but that he tilts" },
    { r = {"BENVOLIO"}, t = "With piercing steel at bold Mercutio’s breast," },
    { r = {"BENVOLIO"}, t = "Who, all as hot, turns deadly point to point," },
    { r = {"BENVOLIO"}, t = "And, with a martial scorn, with one hand beats" },
    { r = {"BENVOLIO"}, t = "Cold death aside, and with the other sends" },
    { r = {"BENVOLIO"}, t = "It back to Tybalt, whose dexterity" },
    { r = {"BENVOLIO"}, t = "Retorts it. Romeo he cries aloud," },
    { r = {"BENVOLIO"}, t = "‘Hold, friends! Friends, part!’ and swifter than his tongue," },
    { r = {"BENVOLIO"}, t = "His agile arm beats down their fatal points," },
    { r = {"BENVOLIO"}, t = "And ’twixt them rushes; underneath whose arm" },
    { r = {"BENVOLIO"}, t = "An envious thrust from Tybalt hit the life" },
    { r = {"BENVOLIO"}, t = "Of stout Mercutio, and then Tybalt fled." },
    { r = {"BENVOLIO"}, t = "But by and by comes back to Romeo," },
    { r = {"BENVOLIO"}, t = "Who had but newly entertain’d revenge," },
    { r = {"BENVOLIO"}, t = "And to’t they go like lightning; for, ere I" },
    { r = {"BENVOLIO"}, t = "Could draw to part them was stout Tybalt slain;" },
    { r = {"BENVOLIO"}, t = "And as he fell did Romeo turn and fly." },
    { r = {"BENVOLIO"}, t = "This is the truth, or let Benvolio die." },
    { r = {"LADY CAPULET"}, t = "He is a kinsman to the Montague." },
    { r = {"LADY CAPULET"}, t = "Affection makes him false, he speaks not true." },
    { r = {"LADY CAPULET"}, t = "Some twenty of them fought in this black strife," },
    { r = {"LADY CAPULET"}, t = "And all those twenty could but kill one life." },
    { r = {"LADY CAPULET"}, t = "I beg for justice, which thou, Prince, must give;" },
    { r = {"LADY CAPULET"}, t = "Romeo slew Tybalt, Romeo must not live." },
    { r = {"ESCALUS"}, t = "Romeo slew him, he slew Mercutio." },
    { r = {"ESCALUS"}, t = "Who now the price of his dear blood doth owe?" },
    { r = {"MONTAGUE"}, t = "Not Romeo, Prince, he was Mercutio’s friend;" },
    { r = {"MONTAGUE"}, t = "His fault concludes but what the law should end," },
    { r = {"MONTAGUE"}, t = "The life of Tybalt." },
    { r = {"ESCALUS"}, t = "And for that offence" },
    { r = {"ESCALUS"}, t = "Immediately we do exile him hence." },
    { r = {"ESCALUS"}, t = "I have an interest in your hate’s proceeding," },
    { r = {"ESCALUS"}, t = "My blood for your rude brawls doth lie a-bleeding." },
    { r = {"ESCALUS"}, t = "But I’ll amerce you with so strong a fine" },
    { r = {"ESCALUS"}, t = "That you shall all repent the loss of mine." },
    { r = {"ESCALUS"}, t = "I will be deaf to pleading and excuses;" },
    { r = {"ESCALUS"}, t = "Nor tears nor prayers shall purchase out abuses." },
    { r = {"ESCALUS"}, t = "Therefore use none. Let Romeo hence in haste," },
    { r = {"ESCALUS"}, t = "Else, when he is found, that hour is his last." },
    { r = {"ESCALUS"}, t = "Bear hence this body, and attend our will." },
    { r = {"ESCALUS"}, t = "Mercy but murders, pardoning those that kill." },
    { d = "Exeunt" },
    { d = "Act 3, Scene 2. A Room in Capulet’s House.", h = true },
    { d = "Enter Juliet" },
    { r = {"JULIET"}, t = "Gallop apace, you fiery-footed steeds," },
    { r = {"JULIET"}, t = "Towards Phoebus’ lodging. Such a waggoner" },
    { r = {"JULIET"}, t = "As Phaeton would whip you to the west" },
    { r = {"JULIET"}, t = "And bring in cloudy night immediately." },
    { r = {"JULIET"}, t = "Spread thy close curtain, love-performing night," },
    { r = {"JULIET"}, t = "That runaway’s eyes may wink, and Romeo" },
    { r = {"JULIET"}, t = "Leap to these arms, untalk’d of and unseen." },
    { r = {"JULIET"}, t = "Lovers can see to do their amorous rites" },
    { r = {"JULIET"}, t = "By their own beauties: or, if love be blind," },
    { r = {"JULIET"}, t = "It best agrees with night. Come, civil night," },
    { r = {"JULIET"}, t = "Thou sober-suited matron, all in black," },
    { r = {"JULIET"}, t = "And learn me how to lose a winning match," },
    { r = {"JULIET"}, t = "Play’d for a pair of stainless maidenhoods." },
    { r = {"JULIET"}, t = "Hood my unmann’d blood, bating in my cheeks," },
    { r = {"JULIET"}, t = "With thy black mantle, till strange love, grow bold," },
    { r = {"JULIET"}, t = "Think true love acted simple modesty." },
    { r = {"JULIET"}, t = "Come, night, come Romeo; come, thou day in night;" },
    { r = {"JULIET"}, t = "For thou wilt lie upon the wings of night" },
    { r = {"JULIET"}, t = "Whiter than new snow upon a raven’s back." },
    { r = {"JULIET"}, t = "Come gentle night, come loving black-brow’d night," },
    { r = {"JULIET"}, t = "Give me my Romeo, and when I shall die," },
    { r = {"JULIET"}, t = "Take him and cut him out in little stars," },
    { r = {"JULIET"}, t = "And he will make the face of heaven so fine" },
    { r = {"JULIET"}, t = "That all the world will be in love with night," },
    { r = {"JULIET"}, t = "And pay no worship to the garish sun." },
    { r = {"JULIET"}, t = "O, I have bought the mansion of a love," },
    { r = {"JULIET"}, t = "But not possess’d it; and though I am sold," },
    { r = {"JULIET"}, t = "Not yet enjoy’d. So tedious is this day" },
    { r = {"JULIET"}, t = "As is the night before some festival" },
    { r = {"JULIET"}, t = "To an impatient child that hath new robes" },
    { r = {"JULIET"}, t = "And may not wear them. O, here comes my Nurse," },
    { r = {"JULIET"}, t = "And she brings news, and every tongue that speaks" },
    { r = {"JULIET"}, t = "But Romeo’s name speaks heavenly eloquence." },
    { d = "Enter Nurse, with cords" },
    { r = {"JULIET"}, t = "Now, Nurse, what news? What hast thou there?" },
    { r = {"JULIET"}, t = "The cords that Romeo bid thee fetch?" },
    { r = {"NURSE"}, t = "Ay, ay, the cords." },
    { d = "Throws them down" },
    { r = {"JULIET"}, t = "Ay me, what news? Why dost thou wring thy hands?" },
    { r = {"NURSE"}, t = "Ah, well-a-day, he’s dead, he’s dead, he’s dead!" },
    { r = {"NURSE"}, t = "We are undone, lady, we are undone." },
    { r = {"NURSE"}, t = "Alack the day, he’s gone, he’s kill’d, he’s dead." },
    { r = {"JULIET"}, t = "Can heaven be so envious?" },
    { r = {"NURSE"}, t = "Romeo can," },
    { r = {"NURSE"}, t = "Though heaven cannot. O Romeo, Romeo." },
    { r = {"NURSE"}, t = "Who ever would have thought it? Romeo!" },
    { r = {"JULIET"}, t = "What devil art thou, that dost torment me thus?" },
    { r = {"JULIET"}, t = "This torture should be roar’d in dismal hell." },
    { r = {"JULIET"}, t = "Hath Romeo slain himself? Say thou but Ay," },
    { r = {"JULIET"}, t = "And that bare vowel I shall poison more" },
    { r = {"JULIET"}, t = "Than the death-darting eye of cockatrice." },
    { r = {"JULIET"}, t = "I am not I if there be such an I;" },
    { r = {"JULIET"}, t = "Or those eyes shut that make thee answer Ay." },
    { r = {"JULIET"}, t = "If he be slain, say Ay; or if not, No." },
    { r = {"JULIET"}, t = "Brief sounds determine of my weal or woe." },
    { r = {"NURSE"}, t = "I saw the wound, I saw it with mine eyes," },
    { r = {"NURSE"}, t = "God save the mark!—here on his manly breast." },
    { r = {"NURSE"}, t = "A piteous corse, a bloody piteous corse;" },
    { r = {"NURSE"}, t = "Pale, pale as ashes, all bedaub’d in blood," },
    { r = {"NURSE"}, t = "All in gore-blood. I swounded at the sight." },
    { r = {"JULIET"}, t = "O, break, my heart. Poor bankrout, break at once." },
    { r = {"JULIET"}, t = "To prison, eyes; ne’er look on liberty." },
    { r = {"JULIET"}, t = "Vile earth to earth resign; end motion here," },
    { r = {"JULIET"}, t = "And thou and Romeo press one heavy bier." },
    { r = {"NURSE"}, t = "O Tybalt, Tybalt, the best friend I had." },
    { r = {"NURSE"}, t = "O courteous Tybalt, honest gentleman!" },
    { r = {"NURSE"}, t = "That ever I should live to see thee dead." },
    { r = {"JULIET"}, t = "What storm is this that blows so contrary?" },
    { r = {"JULIET"}, t = "Is Romeo slaughter’d and is Tybalt dead?" },
    { r = {"JULIET"}, t = "My dearest cousin, and my dearer lord?" },
    { r = {"JULIET"}, t = "Then dreadful trumpet sound the general doom," },
    { r = {"JULIET"}, t = "For who is living, if those two are gone?" },
    { r = {"NURSE"}, t = "Tybalt is gone, and Romeo banished," },
    { r = {"NURSE"}, t = "Romeo that kill’d him, he is banished." },
    { r = {"JULIET"}, t = "O God! Did Romeo’s hand shed Tybalt’s blood?" },
    { r = {"NURSE"}, t = "It did, it did; alas the day, it did." },
    { r = {"JULIET"}, t = "O serpent heart, hid with a flowering face!" },
    { r = {"JULIET"}, t = "Did ever dragon keep so fair a cave?" },
    { r = {"JULIET"}, t = "Beautiful tyrant, fiend angelical," },
    { r = {"JULIET"}, t = "Dove-feather’d raven, wolvish-ravening lamb!" },
    { r = {"JULIET"}, t = "Despised substance of divinest show!" },
    { r = {"JULIET"}, t = "Just opposite to what thou justly seem’st," },
    { r = {"JULIET"}, t = "A damned saint, an honourable villain!" },
    { r = {"JULIET"}, t = "O nature, what hadst thou to do in hell" },
    { r = {"JULIET"}, t = "When thou didst bower the spirit of a fiend" },
    { r = {"JULIET"}, t = "In mortal paradise of such sweet flesh?" },
    { r = {"JULIET"}, t = "Was ever book containing such vile matter" },
    { r = {"JULIET"}, t = "So fairly bound? O, that deceit should dwell" },
    { r = {"JULIET"}, t = "In such a gorgeous palace." },
    { r = {"NURSE"}, t = "There’s no trust," },
    { r = {"NURSE"}, t = "No faith, no honesty in men. All perjur’d," },
    { r = {"NURSE"}, t = "All forsworn, all naught, all dissemblers." },
    { r = {"NURSE"}, t = "Ah, where’s my man? Give me some aqua vitae." },
    { r = {"NURSE"}, t = "These griefs, these woes, these sorrows make me old." },
    { r = {"NURSE"}, t = "Shame come to Romeo." },
    { r = {"JULIET"}, t = "Blister’d be thy tongue" },
    { r = {"JULIET"}, t = "For such a wish! He was not born to shame." },
    { r = {"JULIET"}, t = "Upon his brow shame is asham’d to sit;" },
    { r = {"JULIET"}, t = "For ’tis a throne where honour may be crown’d" },
    { r = {"JULIET"}, t = "Sole monarch of the universal earth." },
    { r = {"JULIET"}, t = "O, what a beast was I to chide at him!" },
    { r = {"NURSE"}, t = "Will you speak well of him that kill’d your cousin?" },
    { r = {"JULIET"}, t = "Shall I speak ill of him that is my husband?" },
    { r = {"JULIET"}, t = "Ah, poor my lord, what tongue shall smooth thy name," },
    { r = {"JULIET"}, t = "When I thy three-hours’ wife have mangled it?" },
    { r = {"JULIET"}, t = "But wherefore, villain, didst thou kill my cousin?" },
    { r = {"JULIET"}, t = "That villain cousin would have kill’d my husband." },
    { r = {"JULIET"}, t = "Back, foolish tears, back to your native spring," },
    { r = {"JULIET"}, t = "Your tributary drops belong to woe," },
    { r = {"JULIET"}, t = "Which you mistaking offer up to joy." },
    { r = {"JULIET"}, t = "My husband lives, that Tybalt would have slain," },
    { r = {"JULIET"}, t = "And Tybalt’s dead, that would have slain my husband." },
    { r = {"JULIET"}, t = "All this is comfort; wherefore weep I then?" },
    { r = {"JULIET"}, t = "Some word there was, worser than Tybalt’s death," },
    { r = {"JULIET"}, t = "That murder’d me. I would forget it fain," },
    { r = {"JULIET"}, t = "But O, it presses to my memory" },
    { r = {"JULIET"}, t = "Like damned guilty deeds to sinners’ minds." },
    { r = {"JULIET"}, t = "Tybalt is dead, and Romeo banished." },
    { r = {"JULIET"}, t = "That ‘banished,’ that one word ‘banished,’" },
    { r = {"JULIET"}, t = "Hath slain ten thousand Tybalts. Tybalt’s death" },
    { r = {"JULIET"}, t = "Was woe enough, if it had ended there." },
    { r = {"JULIET"}, t = "Or if sour woe delights in fellowship," },
    { r = {"JULIET"}, t = "And needly will be rank’d with other griefs," },
    { r = {"JULIET"}, t = "Why follow’d not, when she said Tybalt’s dead," },
    { r = {"JULIET"}, t = "Thy father or thy mother, nay or both," },
    { r = {"JULIET"}, t = "Which modern lamentation might have mov’d?" },
    { r = {"JULIET"}, t = "But with a rear-ward following Tybalt’s death," },
    { r = {"JULIET"}, t = "‘Romeo is banished’—to speak that word" },
    { r = {"JULIET"}, t = "Is father, mother, Tybalt, Romeo, Juliet," },
    { r = {"JULIET"}, t = "All slain, all dead. Romeo is banished," },
    { r = {"JULIET"}, t = "There is no end, no limit, measure, bound," },
    { r = {"JULIET"}, t = "In that word’s death, no words can that woe sound." },
    { r = {"JULIET"}, t = "Where is my father and my mother, Nurse?" },
    { r = {"NURSE"}, t = "Weeping and wailing over Tybalt’s corse." },
    { r = {"NURSE"}, t = "Will you go to them? I will bring you thither." },
    { r = {"JULIET"}, t = "Wash they his wounds with tears. Mine shall be spent," },
    { r = {"JULIET"}, t = "When theirs are dry, for Romeo’s banishment." },
    { r = {"JULIET"}, t = "Take up those cords. Poor ropes, you are beguil’d," },
    { r = {"JULIET"}, t = "Both you and I; for Romeo is exil’d." },
    { r = {"JULIET"}, t = "He made you for a highway to my bed," },
    { r = {"JULIET"}, t = "But I, a maid, die maiden-widowed." },
    { r = {"JULIET"}, t = "Come cords, come Nurse, I’ll to my wedding bed," },
    { r = {"JULIET"}, t = "And death, not Romeo, take my maidenhead." },
    { r = {"NURSE"}, t = "Hie to your chamber. I’ll find Romeo" },
    { r = {"NURSE"}, t = "To comfort you. I wot well where he is." },
    { r = {"NURSE"}, t = "Hark ye, your Romeo will be here at night." },
    { r = {"NURSE"}, t = "I’ll to him, he is hid at Lawrence’ cell." },
    { r = {"JULIET"}, t = "O find him, give this ring to my true knight," },
    { r = {"JULIET"}, t = "And bid him come to take his last farewell." },
    { d = "Exeunt" },
    { d = "Act 3, Scene 3. Friar Lawrence’s cell.", h = true },
    { d = "Enter Friar Lawrence" },
    { r = {"FRIAR LAWRENCE"}, t = "Romeo, come forth; come forth, thou fearful man." },
    { r = {"FRIAR LAWRENCE"}, t = "Affliction is enanmour’d of thy parts" },
    { r = {"FRIAR LAWRENCE"}, t = "And thou art wedded to calamity." },
    { d = "Enter Romeo" },
    { r = {"ROMEO"}, t = "Father, what news? What is the Prince’s doom?" },
    { r = {"ROMEO"}, t = "What sorrow craves acquaintance at my hand," },
    { r = {"ROMEO"}, t = "That I yet know not?" },
    { r = {"FRIAR LAWRENCE"}, t = "Too familiar" },
    { r = {"FRIAR LAWRENCE"}, t = "Is my dear son with such sour company." },
    { r = {"FRIAR LAWRENCE"}, t = "I bring thee tidings of the Prince’s doom." },
    { r = {"ROMEO"}, t = "What less than doomsday is the Prince’s doom?" },
    { r = {"FRIAR LAWRENCE"}, t = "A gentler judgment vanish’d from his lips," },
    { r = {"FRIAR LAWRENCE"}, t = "Not body’s death, but body’s banishment." },
    { r = {"ROMEO"}, t = "Ha, banishment? Be merciful, say death;" },
    { r = {"ROMEO"}, t = "For exile hath more terror in his look," },
    { r = {"ROMEO"}, t = "Much more than death. Do not say banishment." },
    { r = {"FRIAR LAWRENCE"}, t = "Hence from Verona art thou banished." },
    { r = {"FRIAR LAWRENCE"}, t = "Be patient, for the world is broad and wide." },
    { r = {"ROMEO"}, t = "There is no world without Verona walls," },
    { r = {"ROMEO"}, t = "But purgatory, torture, hell itself." },
    { r = {"ROMEO"}, t = "Hence banished is banish’d from the world," },
    { r = {"ROMEO"}, t = "And world’s exile is death. Then banished" },
    { r = {"ROMEO"}, t = "Is death misterm’d. Calling death banished," },
    { r = {"ROMEO"}, t = "Thou cutt’st my head off with a golden axe," },
    { r = {"ROMEO"}, t = "And smilest upon the stroke that murders me." },
    { r = {"FRIAR LAWRENCE"}, t = "O deadly sin, O rude unthankfulness!" },
    { r = {"FRIAR LAWRENCE"}, t = "Thy fault our law calls death, but the kind Prince," },
    { r = {"FRIAR LAWRENCE"}, t = "Taking thy part, hath brush’d aside the law," },
    { r = {"FRIAR LAWRENCE"}, t = "And turn’d that black word death to banishment." },
    { r = {"FRIAR LAWRENCE"}, t = "This is dear mercy, and thou see’st it not." },
    { r = {"ROMEO"}, t = "’Tis torture, and not mercy. Heaven is here" },
    { r = {"ROMEO"}, t = "Where Juliet lives, and every cat and dog," },
    { r = {"ROMEO"}, t = "And little mouse, every unworthy thing," },
    { r = {"ROMEO"}, t = "Live here in heaven and may look on her," },
    { r = {"ROMEO"}, t = "But Romeo may not. More validity," },
    { r = {"ROMEO"}, t = "More honourable state, more courtship lives" },
    { r = {"ROMEO"}, t = "In carrion flies than Romeo. They may seize" },
    { r = {"ROMEO"}, t = "On the white wonder of dear Juliet’s hand," },
    { r = {"ROMEO"}, t = "And steal immortal blessing from her lips," },
    { r = {"ROMEO"}, t = "Who, even in pure and vestal modesty" },
    { r = {"ROMEO"}, t = "Still blush, as thinking their own kisses sin." },
    { r = {"ROMEO"}, t = "But Romeo may not, he is banished." },
    { r = {"ROMEO"}, t = "This may flies do, when I from this must fly." },
    { r = {"ROMEO"}, t = "They are free men but I am banished." },
    { r = {"ROMEO"}, t = "And say’st thou yet that exile is not death?" },
    { r = {"ROMEO"}, t = "Hadst thou no poison mix’d, no sharp-ground knife," },
    { r = {"ROMEO"}, t = "No sudden mean of death, though ne’er so mean," },
    { r = {"ROMEO"}, t = "But banished to kill me? Banished?" },
    { r = {"ROMEO"}, t = "O Friar, the damned use that word in hell." },
    { r = {"ROMEO"}, t = "Howling attends it. How hast thou the heart," },
    { r = {"ROMEO"}, t = "Being a divine, a ghostly confessor," },
    { r = {"ROMEO"}, t = "A sin-absolver, and my friend profess’d," },
    { r = {"ROMEO"}, t = "To mangle me with that word banished?" },
    { r = {"FRIAR LAWRENCE"}, t = "Thou fond mad man, hear me speak a little," },
    { r = {"ROMEO"}, t = "O, thou wilt speak again of banishment." },
    { r = {"FRIAR LAWRENCE"}, t = "I’ll give thee armour to keep off that word," },
    { r = {"FRIAR LAWRENCE"}, t = "Adversity’s sweet milk, philosophy," },
    { r = {"FRIAR LAWRENCE"}, t = "To comfort thee, though thou art banished." },
    { r = {"ROMEO"}, t = "Yet banished? Hang up philosophy." },
    { r = {"ROMEO"}, t = "Unless philosophy can make a Juliet," },
    { r = {"ROMEO"}, t = "Displant a town, reverse a Prince’s doom," },
    { r = {"ROMEO"}, t = "It helps not, it prevails not, talk no more." },
    { r = {"FRIAR LAWRENCE"}, t = "O, then I see that mad men have no ears." },
    { r = {"ROMEO"}, t = "How should they, when that wise men have no eyes?" },
    { r = {"FRIAR LAWRENCE"}, t = "Let me dispute with thee of thy estate." },
    { r = {"ROMEO"}, t = "Thou canst not speak of that thou dost not feel." },
    { r = {"ROMEO"}, t = "Wert thou as young as I, Juliet thy love," },
    { r = {"ROMEO"}, t = "An hour but married, Tybalt murdered," },
    { r = {"ROMEO"}, t = "Doting like me, and like me banished," },
    { r = {"ROMEO"}, t = "Then mightst thou speak, then mightst thou tear thy hair," },
    { r = {"ROMEO"}, t = "And fall upon the ground as I do now," },
    { r = {"ROMEO"}, t = "Taking the measure of an unmade grave." },
    { d = "Knocking within" },
    { r = {"FRIAR LAWRENCE"}, t = "Arise; one knocks. Good Romeo, hide thyself." },
    { r = {"ROMEO"}, t = "Not I, unless the breath of heartsick groans" },
    { r = {"ROMEO"}, t = "Mist-like infold me from the search of eyes." },
    { d = "Knocking" },
    { r = {"FRIAR LAWRENCE"}, t = "Hark, how they knock!—Who’s there?—Romeo, arise," },
    { r = {"FRIAR LAWRENCE"}, t = "Thou wilt be taken.—Stay awhile.—Stand up." },
    { d = "Knocking" },
    { r = {"FRIAR LAWRENCE"}, t = "Run to my study.—By-and-by.—God’s will," },
    { r = {"FRIAR LAWRENCE"}, t = "What simpleness is this.—I come, I come." },
    { d = "Knocking" },
    { r = {"FRIAR LAWRENCE"}, t = "Who knocks so hard? Whence come you, what’s your will?" },
    { r = {"NURSE"}, t = "Let me come in, and you shall know my errand.", d = "Within" },
    { r = {"NURSE"}, t = "I come from Lady Juliet." },
    { r = {"FRIAR LAWRENCE"}, t = "Welcome then." },
    { d = "Enter Nurse" },
    { r = {"NURSE"}, t = "O holy Friar, O, tell me, holy Friar," },
    { r = {"NURSE"}, t = "Where is my lady’s lord, where’s Romeo?" },
    { r = {"FRIAR LAWRENCE"}, t = "There on the ground, with his own tears made drunk." },
    { r = {"NURSE"}, t = "O, he is even in my mistress’ case." },
    { r = {"NURSE"}, t = "Just in her case! O woeful sympathy!" },
    { r = {"NURSE"}, t = "Piteous predicament. Even so lies she," },
    { r = {"NURSE"}, t = "Blubbering and weeping, weeping and blubbering." },
    { r = {"NURSE"}, t = "Stand up, stand up; stand, and you be a man." },
    { r = {"NURSE"}, t = "For Juliet’s sake, for her sake, rise and stand." },
    { r = {"NURSE"}, t = "Why should you fall into so deep an O?" },
    { r = {"ROMEO"}, t = "Nurse." },
    { r = {"NURSE"}, t = "Ah sir, ah sir, death’s the end of all." },
    { r = {"ROMEO"}, t = "Spakest thou of Juliet? How is it with her?" },
    { r = {"ROMEO"}, t = "Doth not she think me an old murderer," },
    { r = {"ROMEO"}, t = "Now I have stain’d the childhood of our joy" },
    { r = {"ROMEO"}, t = "With blood remov’d but little from her own?" },
    { r = {"ROMEO"}, t = "Where is she? And how doth she? And what says" },
    { r = {"ROMEO"}, t = "My conceal’d lady to our cancell’d love?" },
    { r = {"NURSE"}, t = "O, she says nothing, sir, but weeps and weeps;" },
    { r = {"NURSE"}, t = "And now falls on her bed, and then starts up," },
    { r = {"NURSE"}, t = "And Tybalt calls, and then on Romeo cries," },
    { r = {"NURSE"}, t = "And then down falls again." },
    { r = {"ROMEO"}, t = "As if that name," },
    { r = {"ROMEO"}, t = "Shot from the deadly level of a gun," },
    { r = {"ROMEO"}, t = "Did murder her, as that name’s cursed hand" },
    { r = {"ROMEO"}, t = "Murder’d her kinsman. O, tell me, Friar, tell me," },
    { r = {"ROMEO"}, t = "In what vile part of this anatomy" },
    { r = {"ROMEO"}, t = "Doth my name lodge? Tell me, that I may sack" },
    { r = {"ROMEO"}, t = "The hateful mansion." },
    { d = "Drawing his sword" },
    { r = {"FRIAR LAWRENCE"}, t = "Hold thy desperate hand." },
    { r = {"FRIAR LAWRENCE"}, t = "Art thou a man? Thy form cries out thou art." },
    { r = {"FRIAR LAWRENCE"}, t = "Thy tears are womanish, thy wild acts denote" },
    { r = {"FRIAR LAWRENCE"}, t = "The unreasonable fury of a beast." },
    { r = {"FRIAR LAWRENCE"}, t = "Unseemly woman in a seeming man," },
    { r = {"FRIAR LAWRENCE"}, t = "And ill-beseeming beast in seeming both!" },
    { r = {"FRIAR LAWRENCE"}, t = "Thou hast amaz’d me. By my holy order," },
    { r = {"FRIAR LAWRENCE"}, t = "I thought thy disposition better temper’d." },
    { r = {"FRIAR LAWRENCE"}, t = "Hast thou slain Tybalt? Wilt thou slay thyself?" },
    { r = {"FRIAR LAWRENCE"}, t = "And slay thy lady, that in thy life lives," },
    { r = {"FRIAR LAWRENCE"}, t = "By doing damned hate upon thyself?" },
    { r = {"FRIAR LAWRENCE"}, t = "Why rail’st thou on thy birth, the heaven and earth?" },
    { r = {"FRIAR LAWRENCE"}, t = "Since birth, and heaven and earth, all three do meet" },
    { r = {"FRIAR LAWRENCE"}, t = "In thee at once; which thou at once wouldst lose." },
    { r = {"FRIAR LAWRENCE"}, t = "Fie, fie, thou sham’st thy shape, thy love, thy wit," },
    { r = {"FRIAR LAWRENCE"}, t = "Which, like a usurer, abound’st in all," },
    { r = {"FRIAR LAWRENCE"}, t = "And usest none in that true use indeed" },
    { r = {"FRIAR LAWRENCE"}, t = "Which should bedeck thy shape, thy love, thy wit." },
    { r = {"FRIAR LAWRENCE"}, t = "Thy noble shape is but a form of wax," },
    { r = {"FRIAR LAWRENCE"}, t = "Digressing from the valour of a man;" },
    { r = {"FRIAR LAWRENCE"}, t = "Thy dear love sworn but hollow perjury," },
    { r = {"FRIAR LAWRENCE"}, t = "Killing that love which thou hast vow’d to cherish;" },
    { r = {"FRIAR LAWRENCE"}, t = "Thy wit, that ornament to shape and love," },
    { r = {"FRIAR LAWRENCE"}, t = "Misshapen in the conduct of them both," },
    { r = {"FRIAR LAWRENCE"}, t = "Like powder in a skilless soldier’s flask," },
    { r = {"FRIAR LAWRENCE"}, t = "Is set afire by thine own ignorance," },
    { r = {"FRIAR LAWRENCE"}, t = "And thou dismember’d with thine own defence." },
    { r = {"FRIAR LAWRENCE"}, t = "What, rouse thee, man. Thy Juliet is alive," },
    { r = {"FRIAR LAWRENCE"}, t = "For whose dear sake thou wast but lately dead." },
    { r = {"FRIAR LAWRENCE"}, t = "There art thou happy. Tybalt would kill thee," },
    { r = {"FRIAR LAWRENCE"}, t = "But thou slew’st Tybalt; there art thou happy." },
    { r = {"FRIAR LAWRENCE"}, t = "The law that threaten’d death becomes thy friend," },
    { r = {"FRIAR LAWRENCE"}, t = "And turns it to exile; there art thou happy." },
    { r = {"FRIAR LAWRENCE"}, t = "A pack of blessings light upon thy back;" },
    { r = {"FRIAR LAWRENCE"}, t = "Happiness courts thee in her best array;" },
    { r = {"FRIAR LAWRENCE"}, t = "But like a misshaped and sullen wench," },
    { r = {"FRIAR LAWRENCE"}, t = "Thou putt’st up thy Fortune and thy love." },
    { r = {"FRIAR LAWRENCE"}, t = "Take heed, take heed, for such die miserable." },
    { r = {"FRIAR LAWRENCE"}, t = "Go, get thee to thy love as was decreed," },
    { r = {"FRIAR LAWRENCE"}, t = "Ascend her chamber, hence and comfort her." },
    { r = {"FRIAR LAWRENCE"}, t = "But look thou stay not till the watch be set," },
    { r = {"FRIAR LAWRENCE"}, t = "For then thou canst not pass to Mantua;" },
    { r = {"FRIAR LAWRENCE"}, t = "Where thou shalt live till we can find a time" },
    { r = {"FRIAR LAWRENCE"}, t = "To blaze your marriage, reconcile your friends," },
    { r = {"FRIAR LAWRENCE"}, t = "Beg pardon of the Prince, and call thee back" },
    { r = {"FRIAR LAWRENCE"}, t = "With twenty hundred thousand times more joy" },
    { r = {"FRIAR LAWRENCE"}, t = "Than thou went’st forth in lamentation." },
    { r = {"FRIAR LAWRENCE"}, t = "Go before, Nurse. Commend me to thy lady," },
    { r = {"FRIAR LAWRENCE"}, t = "And bid her hasten all the house to bed," },
    { r = {"FRIAR LAWRENCE"}, t = "Which heavy sorrow makes them apt unto." },
    { r = {"FRIAR LAWRENCE"}, t = "Romeo is coming." },
    { r = {"NURSE"}, t = "O Lord, I could have stay’d here all the night" },
    { r = {"NURSE"}, t = "To hear good counsel. O, what learning is!" },
    { r = {"NURSE"}, t = "My lord, I’ll tell my lady you will come." },
    { r = {"ROMEO"}, t = "Do so, and bid my sweet prepare to chide." },
    { r = {"NURSE"}, t = "Here sir, a ring she bid me give you, sir." },
    { r = {"NURSE"}, t = "Hie you, make haste, for it grows very late." },
    { d = "Exit" },
    { r = {"ROMEO"}, t = "How well my comfort is reviv’d by this." },
    { r = {"FRIAR LAWRENCE"}, t = "Go hence, good night, and here stands all your state:" },
    { r = {"FRIAR LAWRENCE"}, t = "Either be gone before the watch be set," },
    { r = {"FRIAR LAWRENCE"}, t = "Or by the break of day disguis’d from hence." },
    { r = {"FRIAR LAWRENCE"}, t = "Sojourn in Mantua. I’ll find out your man," },
    { r = {"FRIAR LAWRENCE"}, t = "And he shall signify from time to time" },
    { r = {"FRIAR LAWRENCE"}, t = "Every good hap to you that chances here." },
    { r = {"FRIAR LAWRENCE"}, t = "Give me thy hand; ’tis late; farewell; good night." },
    { r = {"ROMEO"}, t = "But that a joy past joy calls out on me," },
    { r = {"ROMEO"}, t = "It were a grief so brief to part with thee." },
    { r = {"ROMEO"}, t = "Farewell." },
    { d = "Exeunt" },
    { d = "Act 3, Scene 4. A Room in Capulet’s House.", h = true },
    { d = "Enter Capulet, Lady Capulet and Paris" },
    { r = {"CAPULET"}, t = "Things have fallen out, sir, so unluckily" },
    { r = {"CAPULET"}, t = "That we have had no time to move our daughter." },
    { r = {"CAPULET"}, t = "Look you, she lov’d her kinsman Tybalt dearly," },
    { r = {"CAPULET"}, t = "And so did I. Well, we were born to die." },
    { r = {"CAPULET"}, t = "’Tis very late; she’ll not come down tonight." },
    { r = {"CAPULET"}, t = "I promise you, but for your company," },
    { r = {"CAPULET"}, t = "I would have been abed an hour ago." },
    { r = {"PARIS"}, t = "These times of woe afford no tune to woo." },
    { r = {"PARIS"}, t = "Madam, good night. Commend me to your daughter." },
    { r = {"LADY CAPULET"}, t = "I will, and know her mind early tomorrow;" },
    { r = {"LADY CAPULET"}, t = "Tonight she’s mew’d up to her heaviness." },
    { r = {"CAPULET"}, t = "Sir Paris, I will make a desperate tender" },
    { r = {"CAPULET"}, t = "Of my child’s love. I think she will be rul’d" },
    { r = {"CAPULET"}, t = "In all respects by me; nay more, I doubt it not." },
    { r = {"CAPULET"}, t = "Wife, go you to her ere you go to bed," },
    { r = {"CAPULET"}, t = "Acquaint her here of my son Paris’ love," },
    { r = {"CAPULET"}, t = "And bid her, mark you me, on Wednesday next," },
    { r = {"CAPULET"}, t = "But, soft, what day is this?" },
    { r = {"PARIS"}, t = "Monday, my lord." },
    { r = {"CAPULET"}, t = "Monday! Ha, ha! Well, Wednesday is too soon," },
    { r = {"CAPULET"}, t = "A Thursday let it be; a Thursday, tell her," },
    { r = {"CAPULET"}, t = "She shall be married to this noble earl." },
    { r = {"CAPULET"}, t = "Will you be ready? Do you like this haste?" },
    { r = {"CAPULET"}, t = "We’ll keep no great ado,—a friend or two," },
    { r = {"CAPULET"}, t = "For, hark you, Tybalt being slain so late," },
    { r = {"CAPULET"}, t = "It may be thought we held him carelessly," },
    { r = {"CAPULET"}, t = "Being our kinsman, if we revel much." },
    { r = {"CAPULET"}, t = "Therefore we’ll have some half a dozen friends," },
    { r = {"CAPULET"}, t = "And there an end. But what say you to Thursday?" },
    { r = {"PARIS"}, t = "My lord, I would that Thursday were tomorrow." },
    { r = {"CAPULET"}, t = "Well, get you gone. A Thursday be it then." },
    { r = {"CAPULET"}, t = "Go you to Juliet ere you go to bed," },
    { r = {"CAPULET"}, t = "Prepare her, wife, against this wedding day." },
    { r = {"CAPULET"}, t = "Farewell, my lord.—Light to my chamber, ho!" },
    { r = {"CAPULET"}, t = "Afore me, it is so very very late that we" },
    { r = {"CAPULET"}, t = "May call it early by and by. Good night." },
    { d = "Exeunt" },
    { d = "Act 3, Scene 5. An open Gallery to Juliet’s Chamber, overlooking the Garden.", h = true },
    { d = "Enter Romeo and Juliet" },
    { r = {"JULIET"}, t = "Wilt thou be gone? It is not yet near day." },
    { r = {"JULIET"}, t = "It was the nightingale, and not the lark," },
    { r = {"JULIET"}, t = "That pierc’d the fearful hollow of thine ear;" },
    { r = {"JULIET"}, t = "Nightly she sings on yond pomegranate tree." },
    { r = {"JULIET"}, t = "Believe me, love, it was the nightingale." },
    { r = {"ROMEO"}, t = "It was the lark, the herald of the morn," },
    { r = {"ROMEO"}, t = "No nightingale. Look, love, what envious streaks" },
    { r = {"ROMEO"}, t = "Do lace the severing clouds in yonder east." },
    { r = {"ROMEO"}, t = "Night’s candles are burnt out, and jocund day" },
    { r = {"ROMEO"}, t = "Stands tiptoe on the misty mountain tops." },
    { r = {"ROMEO"}, t = "I must be gone and live, or stay and die." },
    { r = {"JULIET"}, t = "Yond light is not daylight, I know it, I." },
    { r = {"JULIET"}, t = "It is some meteor that the sun exhales" },
    { r = {"JULIET"}, t = "To be to thee this night a torchbearer" },
    { r = {"JULIET"}, t = "And light thee on thy way to Mantua." },
    { r = {"JULIET"}, t = "Therefore stay yet, thou need’st not to be gone." },
    { r = {"ROMEO"}, t = "Let me be ta’en, let me be put to death," },
    { r = {"ROMEO"}, t = "I am content, so thou wilt have it so." },
    { r = {"ROMEO"}, t = "I’ll say yon grey is not the morning’s eye," },
    { r = {"ROMEO"}, t = "’Tis but the pale reflex of Cynthia’s brow." },
    { r = {"ROMEO"}, t = "Nor that is not the lark whose notes do beat" },
    { r = {"ROMEO"}, t = "The vaulty heaven so high above our heads." },
    { r = {"ROMEO"}, t = "I have more care to stay than will to go." },
    { r = {"ROMEO"}, t = "Come, death, and welcome. Juliet wills it so." },
    { r = {"ROMEO"}, t = "How is’t, my soul? Let’s talk. It is not day." },
    { r = {"JULIET"}, t = "It is, it is! Hie hence, be gone, away." },
    { r = {"JULIET"}, t = "It is the lark that sings so out of tune," },
    { r = {"JULIET"}, t = "Straining harsh discords and unpleasing sharps." },
    { r = {"JULIET"}, t = "Some say the lark makes sweet division;" },
    { r = {"JULIET"}, t = "This doth not so, for she divideth us." },
    { r = {"JULIET"}, t = "Some say the lark and loathed toad change eyes." },
    { r = {"JULIET"}, t = "O, now I would they had chang’d voices too," },
    { r = {"JULIET"}, t = "Since arm from arm that voice doth us affray," },
    { r = {"JULIET"}, t = "Hunting thee hence with hunt’s-up to the day." },
    { r = {"JULIET"}, t = "O now be gone, more light and light it grows." },
    { r = {"ROMEO"}, t = "More light and light, more dark and dark our woes." },
    { d = "Enter Nurse" },
    { r = {"NURSE"}, t = "Madam." },
    { r = {"JULIET"}, t = "Nurse?" },
    { r = {"NURSE"}, t = "Your lady mother is coming to your chamber." },
    { r = {"NURSE"}, t = "The day is broke, be wary, look about." },
    { d = "Exit" },
    { r = {"JULIET"}, t = "Then, window, let day in, and let life out." },
    { r = {"ROMEO"}, t = "Farewell, farewell, one kiss, and I’ll descend." },
    { d = "Descends" },
    { r = {"JULIET"}, t = "Art thou gone so? Love, lord, ay husband, friend," },
    { r = {"JULIET"}, t = "I must hear from thee every day in the hour," },
    { r = {"JULIET"}, t = "For in a minute there are many days." },
    { r = {"JULIET"}, t = "O, by this count I shall be much in years" },
    { r = {"JULIET"}, t = "Ere I again behold my Romeo." },
    { r = {"ROMEO"}, t = "Farewell!" },
    { r = {"ROMEO"}, t = "I will omit no opportunity" },
    { r = {"ROMEO"}, t = "That may convey my greetings, love, to thee." },
    { r = {"JULIET"}, t = "O thinkest thou we shall ever meet again?" },
    { r = {"ROMEO"}, t = "I doubt it not, and all these woes shall serve" },
    { r = {"ROMEO"}, t = "For sweet discourses in our time to come." },
    { r = {"JULIET"}, t = "O God! I have an ill-divining soul!" },
    { r = {"JULIET"}, t = "Methinks I see thee, now thou art so low," },
    { r = {"JULIET"}, t = "As one dead in the bottom of a tomb." },
    { r = {"JULIET"}, t = "Either my eyesight fails, or thou look’st pale." },
    { r = {"ROMEO"}, t = "And trust me, love, in my eye so do you." },
    { r = {"ROMEO"}, t = "Dry sorrow drinks our blood. Adieu, adieu." },
    { d = "Exit below" },
    { r = {"JULIET"}, t = "O Fortune, Fortune! All men call thee fickle," },
    { r = {"JULIET"}, t = "If thou art fickle, what dost thou with him" },
    { r = {"JULIET"}, t = "That is renown’d for faith? Be fickle, Fortune;" },
    { r = {"JULIET"}, t = "For then, I hope thou wilt not keep him long" },
    { r = {"JULIET"}, t = "But send him back." },
    { r = {"LADY CAPULET"}, t = "Ho, daughter, are you up?", d = "Within" },
    { r = {"JULIET"}, t = "Who is’t that calls? Is it my lady mother?" },
    { r = {"JULIET"}, t = "Is she not down so late, or up so early?" },
    { r = {"JULIET"}, t = "What unaccustom’d cause procures her hither?" },
    { d = "Enter Lady Capulet" },
    { r = {"LADY CAPULET"}, t = "Why, how now, Juliet?" },
    { r = {"JULIET"}, t = "Madam, I am not well." },
    { r = {"LADY CAPULET"}, t = "Evermore weeping for your cousin’s death?" },
    { r = {"LADY CAPULET"}, t = "What, wilt thou wash him from his grave with tears?" },
    { r = {"LADY CAPULET"}, t = "And if thou couldst, thou couldst not make him live." },
    { r = {"LADY CAPULET"}, t = "Therefore have done: some grief shows much of love," },
    { r = {"LADY CAPULET"}, t = "But much of grief shows still some want of wit." },
    { r = {"JULIET"}, t = "Yet let me weep for such a feeling loss." },
    { r = {"LADY CAPULET"}, t = "So shall you feel the loss, but not the friend" },
    { r = {"LADY CAPULET"}, t = "Which you weep for." },
    { r = {"JULIET"}, t = "Feeling so the loss," },
    { r = {"JULIET"}, t = "I cannot choose but ever weep the friend." },
    { r = {"LADY CAPULET"}, t = "Well, girl, thou weep’st not so much for his death" },
    { r = {"LADY CAPULET"}, t = "As that the villain lives which slaughter’d him." },
    { r = {"JULIET"}, t = "What villain, madam?" },
    { r = {"LADY CAPULET"}, t = "That same villain Romeo." },
    { r = {"JULIET"}, t = "Villain and he be many miles asunder." },
    { r = {"JULIET"}, t = "God pardon him. I do, with all my heart." },
    { r = {"JULIET"}, t = "And yet no man like he doth grieve my heart." },
    { r = {"LADY CAPULET"}, t = "That is because the traitor murderer lives." },
    { r = {"JULIET"}, t = "Ay madam, from the reach of these my hands." },
    { r = {"JULIET"}, t = "Would none but I might venge my cousin’s death." },
    { r = {"LADY CAPULET"}, t = "We will have vengeance for it, fear thou not." },
    { r = {"LADY CAPULET"}, t = "Then weep no more. I’ll send to one in Mantua," },
    { r = {"LADY CAPULET"}, t = "Where that same banish’d runagate doth live," },
    { r = {"LADY CAPULET"}, t = "Shall give him such an unaccustom’d dram" },
    { r = {"LADY CAPULET"}, t = "That he shall soon keep Tybalt company:" },
    { r = {"LADY CAPULET"}, t = "And then I hope thou wilt be satisfied." },
    { r = {"JULIET"}, t = "Indeed I never shall be satisfied" },
    { r = {"JULIET"}, t = "With Romeo till I behold him—dead—" },
    { r = {"JULIET"}, t = "Is my poor heart so for a kinsman vex’d." },
    { r = {"JULIET"}, t = "Madam, if you could find out but a man" },
    { r = {"JULIET"}, t = "To bear a poison, I would temper it," },
    { r = {"JULIET"}, t = "That Romeo should upon receipt thereof," },
    { r = {"JULIET"}, t = "Soon sleep in quiet. O, how my heart abhors" },
    { r = {"JULIET"}, t = "To hear him nam’d, and cannot come to him," },
    { r = {"JULIET"}, t = "To wreak the love I bore my cousin" },
    { r = {"JULIET"}, t = "Upon his body that hath slaughter’d him." },
    { r = {"LADY CAPULET"}, t = "Find thou the means, and I’ll find such a man." },
    { r = {"LADY CAPULET"}, t = "But now I’ll tell thee joyful tidings, girl." },
    { r = {"JULIET"}, t = "And joy comes well in such a needy time." },
    { r = {"JULIET"}, t = "What are they, I beseech your ladyship?" },
    { r = {"LADY CAPULET"}, t = "Well, well, thou hast a careful father, child;" },
    { r = {"LADY CAPULET"}, t = "One who to put thee from thy heaviness," },
    { r = {"LADY CAPULET"}, t = "Hath sorted out a sudden day of joy," },
    { r = {"LADY CAPULET"}, t = "That thou expects not, nor I look’d not for." },
    { r = {"JULIET"}, t = "Madam, in happy time, what day is that?" },
    { r = {"LADY CAPULET"}, t = "Marry, my child, early next Thursday morn" },
    { r = {"LADY CAPULET"}, t = "The gallant, young, and noble gentleman," },
    { r = {"LADY CAPULET"}, t = "The County Paris, at Saint Peter’s Church," },
    { r = {"LADY CAPULET"}, t = "Shall happily make thee there a joyful bride." },
    { r = {"JULIET"}, t = "Now by Saint Peter’s Church, and Peter too," },
    { r = {"JULIET"}, t = "He shall not make me there a joyful bride." },
    { r = {"JULIET"}, t = "I wonder at this haste, that I must wed" },
    { r = {"JULIET"}, t = "Ere he that should be husband comes to woo." },
    { r = {"JULIET"}, t = "I pray you tell my lord and father, madam," },
    { r = {"JULIET"}, t = "I will not marry yet; and when I do, I swear" },
    { r = {"JULIET"}, t = "It shall be Romeo, whom you know I hate," },
    { r = {"JULIET"}, t = "Rather than Paris. These are news indeed." },
    { r = {"LADY CAPULET"}, t = "Here comes your father, tell him so yourself," },
    { r = {"LADY CAPULET"}, t = "And see how he will take it at your hands." },
    { d = "Enter Capulet and Nurse" },
    { r = {"CAPULET"}, t = "When the sun sets, the air doth drizzle dew;" },
    { r = {"CAPULET"}, t = "But for the sunset of my brother’s son" },
    { r = {"CAPULET"}, t = "It rains downright." },
    { r = {"CAPULET"}, t = "How now? A conduit, girl? What, still in tears?" },
    { r = {"CAPULET"}, t = "Evermore showering? In one little body" },
    { r = {"CAPULET"}, t = "Thou counterfeits a bark, a sea, a wind." },
    { r = {"CAPULET"}, t = "For still thy eyes, which I may call the sea," },
    { r = {"CAPULET"}, t = "Do ebb and flow with tears; the bark thy body is," },
    { r = {"CAPULET"}, t = "Sailing in this salt flood, the winds, thy sighs," },
    { r = {"CAPULET"}, t = "Who raging with thy tears and they with them," },
    { r = {"CAPULET"}, t = "Without a sudden calm will overset" },
    { r = {"CAPULET"}, t = "Thy tempest-tossed body. How now, wife?" },
    { r = {"CAPULET"}, t = "Have you deliver’d to her our decree?" },
    { r = {"LADY CAPULET"}, t = "Ay, sir; but she will none, she gives you thanks." },
    { r = {"LADY CAPULET"}, t = "I would the fool were married to her grave." },
    { r = {"CAPULET"}, t = "Soft. Take me with you, take me with you, wife." },
    { r = {"CAPULET"}, t = "How, will she none? Doth she not give us thanks?" },
    { r = {"CAPULET"}, t = "Is she not proud? Doth she not count her blest," },
    { r = {"CAPULET"}, t = "Unworthy as she is, that we have wrought" },
    { r = {"CAPULET"}, t = "So worthy a gentleman to be her bridegroom?" },
    { r = {"JULIET"}, t = "Not proud you have, but thankful that you have." },
    { r = {"JULIET"}, t = "Proud can I never be of what I hate;" },
    { r = {"JULIET"}, t = "But thankful even for hate that is meant love." },
    { r = {"CAPULET"}, t = "How now, how now, chopp’d logic? What is this?" },
    { r = {"CAPULET"}, t = "Proud, and, I thank you, and I thank you not;" },
    { r = {"CAPULET"}, t = "And yet not proud. Mistress minion you," },
    { r = {"CAPULET"}, t = "Thank me no thankings, nor proud me no prouds," },
    { r = {"CAPULET"}, t = "But fettle your fine joints ’gainst Thursday next" },
    { r = {"CAPULET"}, t = "To go with Paris to Saint Peter’s Church," },
    { r = {"CAPULET"}, t = "Or I will drag thee on a hurdle thither." },
    { r = {"CAPULET"}, t = "Out, you green-sickness carrion! Out, you baggage!" },
    { r = {"CAPULET"}, t = "You tallow-face!" },
    { r = {"LADY CAPULET"}, t = "Fie, fie! What, are you mad?" },
    { r = {"JULIET"}, t = "Good father, I beseech you on my knees," },
    { r = {"JULIET"}, t = "Hear me with patience but to speak a word." },
    { r = {"CAPULET"}, t = "Hang thee young baggage, disobedient wretch!" },
    { r = {"CAPULET"}, t = "I tell thee what,—get thee to church a Thursday," },
    { r = {"CAPULET"}, t = "Or never after look me in the face." },
    { r = {"CAPULET"}, t = "Speak not, reply not, do not answer me." },
    { r = {"CAPULET"}, t = "My fingers itch. Wife, we scarce thought us blest" },
    { r = {"CAPULET"}, t = "That God had lent us but this only child;" },
    { r = {"CAPULET"}, t = "But now I see this one is one too much," },
    { r = {"CAPULET"}, t = "And that we have a curse in having her." },
    { r = {"CAPULET"}, t = "Out on her, hilding." },
    { r = {"NURSE"}, t = "God in heaven bless her." },
    { r = {"NURSE"}, t = "You are to blame, my lord, to rate her so." },
    { r = {"CAPULET"}, t = "And why, my lady wisdom? Hold your tongue," },
    { r = {"CAPULET"}, t = "Good prudence; smatter with your gossips, go." },
    { r = {"NURSE"}, t = "I speak no treason." },
    { r = {"CAPULET"}, t = "O God ye good-en!" },
    { r = {"NURSE"}, t = "May not one speak?" },
    { r = {"CAPULET"}, t = "Peace, you mumbling fool!" },
    { r = {"CAPULET"}, t = "Utter your gravity o’er a gossip’s bowl," },
    { r = {"CAPULET"}, t = "For here we need it not." },
    { r = {"LADY CAPULET"}, t = "You are too hot." },
    { r = {"CAPULET"}, t = "God’s bread, it makes me mad!" },
    { r = {"CAPULET"}, t = "Day, night, hour, ride, time, work, play," },
    { r = {"CAPULET"}, t = "Alone, in company, still my care hath been" },
    { r = {"CAPULET"}, t = "To have her match’d, and having now provided" },
    { r = {"CAPULET"}, t = "A gentleman of noble parentage," },
    { r = {"CAPULET"}, t = "Of fair demesnes, youthful, and nobly allied," },
    { r = {"CAPULET"}, t = "Stuff’d, as they say, with honourable parts," },
    { r = {"CAPULET"}, t = "Proportion’d as one’s thought would wish a man," },
    { r = {"CAPULET"}, t = "And then to have a wretched puling fool," },
    { r = {"CAPULET"}, t = "A whining mammet, in her fortune’s tender," },
    { r = {"CAPULET"}, t = "To answer, ‘I’ll not wed, I cannot love," },
    { r = {"CAPULET"}, t = "I am too young, I pray you pardon me.’" },
    { r = {"CAPULET"}, t = "But, and you will not wed, I’ll pardon you." },
    { r = {"CAPULET"}, t = "Graze where you will, you shall not house with me." },
    { r = {"CAPULET"}, t = "Look to’t, think on’t, I do not use to jest." },
    { r = {"CAPULET"}, t = "Thursday is near; lay hand on heart, advise." },
    { r = {"CAPULET"}, t = "And you be mine, I’ll give you to my friend;" },
    { r = {"CAPULET"}, t = "And you be not, hang, beg, starve, die in the streets," },
    { r = {"CAPULET"}, t = "For by my soul, I’ll ne’er acknowledge thee," },
    { r = {"CAPULET"}, t = "Nor what is mine shall never do thee good." },
    { r = {"CAPULET"}, t = "Trust to’t, bethink you, I’ll not be forsworn." },
    { d = "Exit" },
    { r = {"JULIET"}, t = "Is there no pity sitting in the clouds," },
    { r = {"JULIET"}, t = "That sees into the bottom of my grief?" },
    { r = {"JULIET"}, t = "O sweet my mother, cast me not away," },
    { r = {"JULIET"}, t = "Delay this marriage for a month, a week," },
    { r = {"JULIET"}, t = "Or, if you do not, make the bridal bed" },
    { r = {"JULIET"}, t = "In that dim monument where Tybalt lies." },
    { r = {"LADY CAPULET"}, t = "Talk not to me, for I’ll not speak a word." },
    { r = {"LADY CAPULET"}, t = "Do as thou wilt, for I have done with thee." },
    { d = "Exit" },
    { r = {"JULIET"}, t = "O God! O Nurse, how shall this be prevented?" },
    { r = {"JULIET"}, t = "My husband is on earth, my faith in heaven." },
    { r = {"JULIET"}, t = "How shall that faith return again to earth," },
    { r = {"JULIET"}, t = "Unless that husband send it me from heaven" },
    { r = {"JULIET"}, t = "By leaving earth? Comfort me, counsel me." },
    { r = {"JULIET"}, t = "Alack, alack, that heaven should practise stratagems" },
    { r = {"JULIET"}, t = "Upon so soft a subject as myself." },
    { r = {"JULIET"}, t = "What say’st thou? Hast thou not a word of joy?" },
    { r = {"JULIET"}, t = "Some comfort, Nurse." },
    { r = {"NURSE"}, t = "Faith, here it is." },
    { r = {"NURSE"}, t = "Romeo is banished; and all the world to nothing" },
    { r = {"NURSE"}, t = "That he dares ne’er come back to challenge you." },
    { r = {"NURSE"}, t = "Or if he do, it needs must be by stealth." },
    { r = {"NURSE"}, t = "Then, since the case so stands as now it doth," },
    { r = {"NURSE"}, t = "I think it best you married with the County." },
    { r = {"NURSE"}, t = "O, he’s a lovely gentleman." },
    { r = {"NURSE"}, t = "Romeo’s a dishclout to him. An eagle, madam," },
    { r = {"NURSE"}, t = "Hath not so green, so quick, so fair an eye" },
    { r = {"NURSE"}, t = "As Paris hath. Beshrew my very heart," },
    { r = {"NURSE"}, t = "I think you are happy in this second match," },
    { r = {"NURSE"}, t = "For it excels your first: or if it did not," },
    { r = {"NURSE"}, t = "Your first is dead, or ’twere as good he were," },
    { r = {"NURSE"}, t = "As living here and you no use of him." },
    { r = {"JULIET"}, t = "Speakest thou from thy heart?" },
    { r = {"NURSE"}, t = "And from my soul too," },
    { r = {"NURSE"}, t = "Or else beshrew them both." },
    { r = {"JULIET"}, t = "Amen." },
    { r = {"NURSE"}, t = "What?" },
    { r = {"JULIET"}, t = "Well, thou hast comforted me marvellous much." },
    { r = {"JULIET"}, t = "Go in, and tell my lady I am gone," },
    { r = {"JULIET"}, t = "Having displeas’d my father, to Lawrence’ cell," },
    { r = {"JULIET"}, t = "To make confession and to be absolv’d." },
    { r = {"NURSE"}, t = "Marry, I will; and this is wisely done." },
    { d = "Exit" },
    { r = {"JULIET"}, t = "Ancient damnation! O most wicked fiend!" },
    { r = {"JULIET"}, t = "Is it more sin to wish me thus forsworn," },
    { r = {"JULIET"}, t = "Or to dispraise my lord with that same tongue" },
    { r = {"JULIET"}, t = "Which she hath prais’d him with above compare" },
    { r = {"JULIET"}, t = "So many thousand times? Go, counsellor." },
    { r = {"JULIET"}, t = "Thou and my bosom henceforth shall be twain." },
    { r = {"JULIET"}, t = "I’ll to the Friar to know his remedy." },
    { r = {"JULIET"}, t = "If all else fail, myself have power to die." },
    { d = "Exit" },
    { d = "Act 4, Scene 1. Friar Lawrence’s Cell.", h = true },
    { d = "Enter Friar Lawrence and Paris" },
    { r = {"FRIAR LAWRENCE"}, t = "On Thursday, sir? The time is very short." },
    { r = {"PARIS"}, t = "My father Capulet will have it so;" },
    { r = {"PARIS"}, t = "And I am nothing slow to slack his haste." },
    { r = {"FRIAR LAWRENCE"}, t = "You say you do not know the lady’s mind." },
    { r = {"FRIAR LAWRENCE"}, t = "Uneven is the course; I like it not." },
    { r = {"PARIS"}, t = "Immoderately she weeps for Tybalt’s death," },
    { r = {"PARIS"}, t = "And therefore have I little talk’d of love;" },
    { r = {"PARIS"}, t = "For Venus smiles not in a house of tears." },
    { r = {"PARIS"}, t = "Now, sir, her father counts it dangerous" },
    { r = {"PARIS"}, t = "That she do give her sorrow so much sway;" },
    { r = {"PARIS"}, t = "And in his wisdom, hastes our marriage," },
    { r = {"PARIS"}, t = "To stop the inundation of her tears," },
    { r = {"PARIS"}, t = "Which, too much minded by herself alone," },
    { r = {"PARIS"}, t = "May be put from her by society." },
    { r = {"PARIS"}, t = "Now do you know the reason of this haste." },
    { r = {"FRIAR LAWRENCE"}, t = "I would I knew not why it should be slow’d.—", d = "Aside" },
    { r = {"FRIAR LAWRENCE"}, t = "Look, sir, here comes the lady toward my cell." },
    { d = "Enter Juliet" },
    { r = {"PARIS"}, t = "Happily met, my lady and my wife!" },
    { r = {"JULIET"}, t = "That may be, sir, when I may be a wife." },
    { r = {"PARIS"}, t = "That may be, must be, love, on Thursday next." },
    { r = {"JULIET"}, t = "What must be shall be." },
    { r = {"FRIAR LAWRENCE"}, t = "That’s a certain text." },
    { r = {"PARIS"}, t = "Come you to make confession to this father?" },
    { r = {"JULIET"}, t = "To answer that, I should confess to you." },
    { r = {"PARIS"}, t = "Do not deny to him that you love me." },
    { r = {"JULIET"}, t = "I will confess to you that I love him." },
    { r = {"PARIS"}, t = "So will ye, I am sure, that you love me." },
    { r = {"JULIET"}, t = "If I do so, it will be of more price," },
    { r = {"JULIET"}, t = "Being spoke behind your back than to your face." },
    { r = {"PARIS"}, t = "Poor soul, thy face is much abus’d with tears." },
    { r = {"JULIET"}, t = "The tears have got small victory by that;" },
    { r = {"JULIET"}, t = "For it was bad enough before their spite." },
    { r = {"PARIS"}, t = "Thou wrong’st it more than tears with that report." },
    { r = {"JULIET"}, t = "That is no slander, sir, which is a truth," },
    { r = {"JULIET"}, t = "And what I spake, I spake it to my face." },
    { r = {"PARIS"}, t = "Thy face is mine, and thou hast slander’d it." },
    { r = {"JULIET"}, t = "It may be so, for it is not mine own." },
    { r = {"JULIET"}, t = "Are you at leisure, holy father, now," },
    { r = {"JULIET"}, t = "Or shall I come to you at evening mass?" },
    { r = {"FRIAR LAWRENCE"}, t = "My leisure serves me, pensive daughter, now.—" },
    { r = {"FRIAR LAWRENCE"}, t = "My lord, we must entreat the time alone." },
    { r = {"PARIS"}, t = "God shield I should disturb devotion!—" },
    { r = {"PARIS"}, t = "Juliet, on Thursday early will I rouse ye," },
    { r = {"PARIS"}, t = "Till then, adieu; and keep this holy kiss." },
    { d = "Exit" },
    { r = {"JULIET"}, t = "O shut the door, and when thou hast done so," },
    { r = {"JULIET"}, t = "Come weep with me, past hope, past cure, past help!" },
    { r = {"FRIAR LAWRENCE"}, t = "O Juliet, I already know thy grief;" },
    { r = {"FRIAR LAWRENCE"}, t = "It strains me past the compass of my wits." },
    { r = {"FRIAR LAWRENCE"}, t = "I hear thou must, and nothing may prorogue it," },
    { r = {"FRIAR LAWRENCE"}, t = "On Thursday next be married to this County." },
    { r = {"JULIET"}, t = "Tell me not, Friar, that thou hear’st of this," },
    { r = {"JULIET"}, t = "Unless thou tell me how I may prevent it." },
    { r = {"JULIET"}, t = "If in thy wisdom, thou canst give no help," },
    { r = {"JULIET"}, t = "Do thou but call my resolution wise," },
    { r = {"JULIET"}, t = "And with this knife I’ll help it presently." },
    { r = {"JULIET"}, t = "God join’d my heart and Romeo’s, thou our hands;" },
    { r = {"JULIET"}, t = "And ere this hand, by thee to Romeo’s seal’d," },
    { r = {"JULIET"}, t = "Shall be the label to another deed," },
    { r = {"JULIET"}, t = "Or my true heart with treacherous revolt" },
    { r = {"JULIET"}, t = "Turn to another, this shall slay them both." },
    { r = {"JULIET"}, t = "Therefore, out of thy long-experienc’d time," },
    { r = {"JULIET"}, t = "Give me some present counsel, or behold" },
    { r = {"JULIET"}, t = "’Twixt my extremes and me this bloody knife" },
    { r = {"JULIET"}, t = "Shall play the empire, arbitrating that" },
    { r = {"JULIET"}, t = "Which the commission of thy years and art" },
    { r = {"JULIET"}, t = "Could to no issue of true honour bring." },
    { r = {"JULIET"}, t = "Be not so long to speak. I long to die," },
    { r = {"JULIET"}, t = "If what thou speak’st speak not of remedy." },
    { r = {"FRIAR LAWRENCE"}, t = "Hold, daughter. I do spy a kind of hope," },
    { r = {"FRIAR LAWRENCE"}, t = "Which craves as desperate an execution" },
    { r = {"FRIAR LAWRENCE"}, t = "As that is desperate which we would prevent." },
    { r = {"FRIAR LAWRENCE"}, t = "If, rather than to marry County Paris" },
    { r = {"FRIAR LAWRENCE"}, t = "Thou hast the strength of will to slay thyself," },
    { r = {"FRIAR LAWRENCE"}, t = "Then is it likely thou wilt undertake" },
    { r = {"FRIAR LAWRENCE"}, t = "A thing like death to chide away this shame," },
    { r = {"FRIAR LAWRENCE"}, t = "That cop’st with death himself to scape from it." },
    { r = {"FRIAR LAWRENCE"}, t = "And if thou dar’st, I’ll give thee remedy." },
    { r = {"JULIET"}, t = "O, bid me leap, rather than marry Paris," },
    { r = {"JULIET"}, t = "From off the battlements of yonder tower," },
    { r = {"JULIET"}, t = "Or walk in thievish ways, or bid me lurk" },
    { r = {"JULIET"}, t = "Where serpents are. Chain me with roaring bears;" },
    { r = {"JULIET"}, t = "Or hide me nightly in a charnel-house," },
    { r = {"JULIET"}, t = "O’er-cover’d quite with dead men’s rattling bones," },
    { r = {"JULIET"}, t = "With reeky shanks and yellow chapless skulls." },
    { r = {"JULIET"}, t = "Or bid me go into a new-made grave," },
    { r = {"JULIET"}, t = "And hide me with a dead man in his shroud;" },
    { r = {"JULIET"}, t = "Things that, to hear them told, have made me tremble," },
    { r = {"JULIET"}, t = "And I will do it without fear or doubt," },
    { r = {"JULIET"}, t = "To live an unstain’d wife to my sweet love." },
    { r = {"FRIAR LAWRENCE"}, t = "Hold then. Go home, be merry, give consent" },
    { r = {"FRIAR LAWRENCE"}, t = "To marry Paris. Wednesday is tomorrow;" },
    { r = {"FRIAR LAWRENCE"}, t = "Tomorrow night look that thou lie alone," },
    { r = {"FRIAR LAWRENCE"}, t = "Let not thy Nurse lie with thee in thy chamber." },
    { r = {"FRIAR LAWRENCE"}, t = "Take thou this vial, being then in bed," },
    { r = {"FRIAR LAWRENCE"}, t = "And this distilled liquor drink thou off," },
    { r = {"FRIAR LAWRENCE"}, t = "When presently through all thy veins shall run" },
    { r = {"FRIAR LAWRENCE"}, t = "A cold and drowsy humour; for no pulse" },
    { r = {"FRIAR LAWRENCE"}, t = "Shall keep his native progress, but surcease." },
    { r = {"FRIAR LAWRENCE"}, t = "No warmth, no breath shall testify thou livest," },
    { r = {"FRIAR LAWRENCE"}, t = "The roses in thy lips and cheeks shall fade" },
    { r = {"FRIAR LAWRENCE"}, t = "To paly ashes; thy eyes’ windows fall," },
    { r = {"FRIAR LAWRENCE"}, t = "Like death when he shuts up the day of life." },
    { r = {"FRIAR LAWRENCE"}, t = "Each part depriv’d of supple government," },
    { r = {"FRIAR LAWRENCE"}, t = "Shall stiff and stark and cold appear like death." },
    { r = {"FRIAR LAWRENCE"}, t = "And in this borrow’d likeness of shrunk death" },
    { r = {"FRIAR LAWRENCE"}, t = "Thou shalt continue two and forty hours," },
    { r = {"FRIAR LAWRENCE"}, t = "And then awake as from a pleasant sleep." },
    { r = {"FRIAR LAWRENCE"}, t = "Now when the bridegroom in the morning comes" },
    { r = {"FRIAR LAWRENCE"}, t = "To rouse thee from thy bed, there art thou dead." },
    { r = {"FRIAR LAWRENCE"}, t = "Then as the manner of our country is," },
    { r = {"FRIAR LAWRENCE"}, t = "In thy best robes, uncover’d, on the bier," },
    { r = {"FRIAR LAWRENCE"}, t = "Thou shalt be borne to that same ancient vault" },
    { r = {"FRIAR LAWRENCE"}, t = "Where all the kindred of the Capulets lie." },
    { r = {"FRIAR LAWRENCE"}, t = "In the meantime, against thou shalt awake," },
    { r = {"FRIAR LAWRENCE"}, t = "Shall Romeo by my letters know our drift," },
    { r = {"FRIAR LAWRENCE"}, t = "And hither shall he come, and he and I" },
    { r = {"FRIAR LAWRENCE"}, t = "Will watch thy waking, and that very night" },
    { r = {"FRIAR LAWRENCE"}, t = "Shall Romeo bear thee hence to Mantua." },
    { r = {"FRIAR LAWRENCE"}, t = "And this shall free thee from this present shame," },
    { r = {"FRIAR LAWRENCE"}, t = "If no inconstant toy nor womanish fear" },
    { r = {"FRIAR LAWRENCE"}, t = "Abate thy valour in the acting it." },
    { r = {"JULIET"}, t = "Give me, give me! O tell not me of fear!" },
    { r = {"FRIAR LAWRENCE"}, t = "Hold; get you gone, be strong and prosperous" },
    { r = {"FRIAR LAWRENCE"}, t = "In this resolve. I’ll send a friar with speed" },
    { r = {"FRIAR LAWRENCE"}, t = "To Mantua, with my letters to thy lord." },
    { r = {"JULIET"}, t = "Love give me strength, and strength shall help afford." },
    { r = {"JULIET"}, t = "Farewell, dear father." },
    { d = "Exeunt" },
    { d = "Act 4, Scene 2. Hall in Capulet’s House.", h = true },
    { d = "Enter Capulet, Lady Capulet, Nurse and Servants" },
    { r = {"CAPULET"}, t = "So many guests invite as here are writ." },
    { d = "Exit first Servant" },
    { r = {"CAPULET"}, t = "Sirrah, go hire me twenty cunning cooks." },
    { r = {"SECOND SERVANT"}, t = "You shall have none ill, sir; for I’ll try if they can lick their fingers." },
    { r = {"CAPULET"}, t = "How canst thou try them so?" },
    { r = {"SECOND SERVANT"}, t = "Marry, sir, ’tis an ill cook that cannot lick his own fingers; therefore he that cannot lick his fingers goes not with me." },
    { r = {"CAPULET"}, t = "Go, begone." },
    { d = "Exit second Servant" },
    { r = {"CAPULET"}, t = "We shall be much unfurnish’d for this time." },
    { r = {"CAPULET"}, t = "What, is my daughter gone to Friar Lawrence?" },
    { r = {"NURSE"}, t = "Ay, forsooth." },
    { r = {"CAPULET"}, t = "Well, he may chance to do some good on her." },
    { r = {"CAPULET"}, t = "A peevish self-will’d harlotry it is." },
    { d = "Enter Juliet" },
    { r = {"NURSE"}, t = "See where she comes from shrift with merry look." },
    { r = {"CAPULET"}, t = "How now, my headstrong. Where have you been gadding?" },
    { r = {"JULIET"}, t = "Where I have learnt me to repent the sin" },
    { r = {"JULIET"}, t = "Of disobedient opposition" },
    { r = {"JULIET"}, t = "To you and your behests; and am enjoin’d" },
    { r = {"JULIET"}, t = "By holy Lawrence to fall prostrate here," },
    { r = {"JULIET"}, t = "To beg your pardon. Pardon, I beseech you." },
    { r = {"JULIET"}, t = "Henceforward I am ever rul’d by you." },
    { r = {"CAPULET"}, t = "Send for the County, go tell him of this." },
    { r = {"CAPULET"}, t = "I’ll have this knot knit up tomorrow morning." },
    { r = {"JULIET"}, t = "I met the youthful lord at Lawrence’ cell," },
    { r = {"JULIET"}, t = "And gave him what becomed love I might," },
    { r = {"JULIET"}, t = "Not stepping o’er the bounds of modesty." },
    { r = {"CAPULET"}, t = "Why, I am glad on’t. This is well. Stand up." },
    { r = {"CAPULET"}, t = "This is as’t should be. Let me see the County." },
    { r = {"CAPULET"}, t = "Ay, marry. Go, I say, and fetch him hither." },
    { r = {"CAPULET"}, t = "Now afore God, this reverend holy Friar," },
    { r = {"CAPULET"}, t = "All our whole city is much bound to him." },
    { r = {"JULIET"}, t = "Nurse, will you go with me into my closet," },
    { r = {"JULIET"}, t = "To help me sort such needful ornaments" },
    { r = {"JULIET"}, t = "As you think fit to furnish me tomorrow?" },
    { r = {"LADY CAPULET"}, t = "No, not till Thursday. There is time enough." },
    { r = {"CAPULET"}, t = "Go, Nurse, go with her. We’ll to church tomorrow." },
    { d = "Exeunt Juliet and Nurse" },
    { r = {"LADY CAPULET"}, t = "We shall be short in our provision," },
    { r = {"LADY CAPULET"}, t = "’Tis now near night." },
    { r = {"CAPULET"}, t = "Tush, I will stir about," },
    { r = {"CAPULET"}, t = "And all things shall be well, I warrant thee, wife." },
    { r = {"CAPULET"}, t = "Go thou to Juliet, help to deck up her." },
    { r = {"CAPULET"}, t = "I’ll not to bed tonight, let me alone." },
    { r = {"CAPULET"}, t = "I’ll play the housewife for this once.—What, ho!—" },
    { r = {"CAPULET"}, t = "They are all forth: well, I will walk myself" },
    { r = {"CAPULET"}, t = "To County Paris, to prepare him up" },
    { r = {"CAPULET"}, t = "Against tomorrow. My heart is wondrous light" },
    { r = {"CAPULET"}, t = "Since this same wayward girl is so reclaim’d." },
    { d = "Exeunt" },
    { d = "Act 4, Scene 3. Juliet’s Chamber.", h = true },
    { d = "Enter Juliet and Nurse" },
    { r = {"JULIET"}, t = "Ay, those attires are best. But, gentle Nurse," },
    { r = {"JULIET"}, t = "I pray thee leave me to myself tonight;" },
    { r = {"JULIET"}, t = "For I have need of many orisons" },
    { r = {"JULIET"}, t = "To move the heavens to smile upon my state," },
    { r = {"JULIET"}, t = "Which, well thou know’st, is cross and full of sin." },
    { d = "Enter Lady Capulet" },
    { r = {"LADY CAPULET"}, t = "What, are you busy, ho? Need you my help?" },
    { r = {"JULIET"}, t = "No, madam; we have cull’d such necessaries" },
    { r = {"JULIET"}, t = "As are behoveful for our state tomorrow." },
    { r = {"JULIET"}, t = "So please you, let me now be left alone," },
    { r = {"JULIET"}, t = "And let the nurse this night sit up with you," },
    { r = {"JULIET"}, t = "For I am sure you have your hands full all" },
    { r = {"JULIET"}, t = "In this so sudden business." },
    { r = {"LADY CAPULET"}, t = "Good night." },
    { r = {"LADY CAPULET"}, t = "Get thee to bed and rest, for thou hast need." },
    { d = "Exeunt Lady Capulet and Nurse" },
    { r = {"JULIET"}, t = "Farewell. God knows when we shall meet again." },
    { r = {"JULIET"}, t = "I have a faint cold fear thrills through my veins" },
    { r = {"JULIET"}, t = "That almost freezes up the heat of life." },
    { r = {"JULIET"}, t = "I’ll call them back again to comfort me." },
    { r = {"JULIET"}, t = "Nurse!—What should she do here?" },
    { r = {"JULIET"}, t = "My dismal scene I needs must act alone." },
    { r = {"JULIET"}, t = "Come, vial." },
    { r = {"JULIET"}, t = "What if this mixture do not work at all?" },
    { r = {"JULIET"}, t = "Shall I be married then tomorrow morning?" },
    { r = {"JULIET"}, t = "No, No! This shall forbid it. Lie thou there." },
    { d = "Laying down her dagger" },
    { r = {"JULIET"}, t = "What if it be a poison, which the Friar" },
    { r = {"JULIET"}, t = "Subtly hath minister’d to have me dead," },
    { r = {"JULIET"}, t = "Lest in this marriage he should be dishonour’d," },
    { r = {"JULIET"}, t = "Because he married me before to Romeo?" },
    { r = {"JULIET"}, t = "I fear it is. And yet methinks it should not," },
    { r = {"JULIET"}, t = "For he hath still been tried a holy man." },
    { r = {"JULIET"}, t = "How if, when I am laid into the tomb," },
    { r = {"JULIET"}, t = "I wake before the time that Romeo" },
    { r = {"JULIET"}, t = "Come to redeem me? There’s a fearful point!" },
    { r = {"JULIET"}, t = "Shall I not then be stifled in the vault," },
    { r = {"JULIET"}, t = "To whose foul mouth no healthsome air breathes in," },
    { r = {"JULIET"}, t = "And there die strangled ere my Romeo comes?" },
    { r = {"JULIET"}, t = "Or, if I live, is it not very like," },
    { r = {"JULIET"}, t = "The horrible conceit of death and night," },
    { r = {"JULIET"}, t = "Together with the terror of the place," },
    { r = {"JULIET"}, t = "As in a vault, an ancient receptacle," },
    { r = {"JULIET"}, t = "Where for this many hundred years the bones" },
    { r = {"JULIET"}, t = "Of all my buried ancestors are pack’d," },
    { r = {"JULIET"}, t = "Where bloody Tybalt, yet but green in earth," },
    { r = {"JULIET"}, t = "Lies festering in his shroud; where, as they say," },
    { r = {"JULIET"}, t = "At some hours in the night spirits resort—" },
    { r = {"JULIET"}, t = "Alack, alack, is it not like that I," },
    { r = {"JULIET"}, t = "So early waking, what with loathsome smells," },
    { r = {"JULIET"}, t = "And shrieks like mandrakes torn out of the earth," },
    { r = {"JULIET"}, t = "That living mortals, hearing them, run mad." },
    { r = {"JULIET"}, t = "O, if I wake, shall I not be distraught," },
    { r = {"JULIET"}, t = "Environed with all these hideous fears," },
    { r = {"JULIET"}, t = "And madly play with my forefathers’ joints?" },
    { r = {"JULIET"}, t = "And pluck the mangled Tybalt from his shroud?" },
    { r = {"JULIET"}, t = "And, in this rage, with some great kinsman’s bone," },
    { r = {"JULIET"}, t = "As with a club, dash out my desperate brains?" },
    { r = {"JULIET"}, t = "O look, methinks I see my cousin’s ghost" },
    { r = {"JULIET"}, t = "Seeking out Romeo that did spit his body" },
    { r = {"JULIET"}, t = "Upon a rapier’s point. Stay, Tybalt, stay!" },
    { r = {"JULIET"}, t = "Romeo, Romeo, Romeo, here’s drink! I drink to thee.", u = {"Refreshing Spring Water"} },
    { r = {"JULIET"}, d = "Throws herself on the bed", e = "/sleep", s = {"Feign Death"} },
    { d = "Act 4, Scene 4. Hall in Capulet’s House.", h = true },
    { d = "Enter Lady Capulet and Nurse" },
    { r = {"LADY CAPULET"}, t = "Hold, take these keys and fetch more spices, Nurse." },
    { r = {"NURSE"}, t = "They call for dates and quinces in the pastry." },
    { d = "Enter Capulet" },
    { r = {"CAPULET"}, t = "Come, stir, stir, stir! The second cock hath crow’d," },
    { r = {"CAPULET"}, t = "The curfew bell hath rung, ’tis three o’clock." },
    { r = {"CAPULET"}, t = "Look to the bak’d meats, good Angelica;" },
    { r = {"CAPULET"}, t = "Spare not for cost." },
    { r = {"NURSE"}, t = "Go, you cot-quean, go," },
    { r = {"NURSE"}, t = "Get you to bed; faith, you’ll be sick tomorrow" },
    { r = {"NURSE"}, t = "For this night’s watching." },
    { r = {"CAPULET"}, t = "No, not a whit. What! I have watch’d ere now" },
    { r = {"CAPULET"}, t = "All night for lesser cause, and ne’er been sick." },
    { r = {"LADY CAPULET"}, t = "Ay, you have been a mouse-hunt in your time;" },
    { r = {"LADY CAPULET"}, t = "But I will watch you from such watching now." },
    { d = "Exeunt Lady Capulet and Nurse" },
    { r = {"CAPULET"}, t = "A jealous-hood, a jealous-hood!" },
    { d = "Enter Servants, with spits, logs and baskets" },
    { r = {"CAPULET"}, t = "Now, fellow, what’s there?" },
    { r = {"FIRST SERVANT"}, t = "Things for the cook, sir; but I know not what." },
    { r = {"CAPULET"}, t = "Make haste, make haste." },
    { d = "Exit First Servant" },
    { r = {"CAPULET"}, t = "Sirrah, fetch drier logs." },
    { r = {"CAPULET"}, t = "Call Peter, he will show thee where they are." },
    { r = {"SECOND SERVANT"}, t = "I have a head, sir, that will find out logs" },
    { r = {"SECOND SERVANT"}, t = "And never trouble Peter for the matter." },
    { d = "Exit" },
    { r = {"CAPULET"}, t = "Mass and well said; a merry whoreson, ha." },
    { r = {"CAPULET"}, t = "Thou shalt be loggerhead.—Good faith, ’tis day." },
    { r = {"CAPULET"}, t = "The County will be here with music straight," },
    { r = {"CAPULET"}, t = "For so he said he would. I hear him near." },
    { d = "Play music" },
    { r = {"CAPULET"}, t = "Nurse! Wife! What, ho! What, Nurse, I say!" },
    { d = "Re-enter Nurse" },
    { r = {"CAPULET"}, t = "Go waken Juliet, go and trim her up." },
    { r = {"CAPULET"}, t = "I’ll go and chat with Paris. Hie, make haste," },
    { r = {"CAPULET"}, t = "Make haste; the bridegroom he is come already." },
    { r = {"CAPULET"}, t = "Make haste I say." },
    { d = "Exeunt" },
    { d = "Act 4, Scene 5. Juliet’s Chamber; Juliet on the bed.", h = true },
    { d = "Enter Nurse" },
    { r = {"NURSE"}, t = "Mistress! What, mistress! Juliet! Fast, I warrant her, she." },
    { r = {"NURSE"}, t = "Why, lamb, why, lady, fie, you slug-abed!" },
    { r = {"NURSE"}, t = "Why, love, I say! Madam! Sweetheart! Why, bride!" },
    { r = {"NURSE"}, t = "What, not a word? You take your pennyworths now." },
    { r = {"NURSE"}, t = "Sleep for a week; for the next night, I warrant," },
    { r = {"NURSE"}, t = "The County Paris hath set up his rest" },
    { r = {"NURSE"}, t = "That you shall rest but little. God forgive me!" },
    { r = {"NURSE"}, t = "Marry and amen. How sound is she asleep!" },
    { r = {"NURSE"}, t = "I needs must wake her. Madam, madam, madam!" },
    { r = {"NURSE"}, t = "Ay, let the County take you in your bed," },
    { r = {"NURSE"}, t = "He’ll fright you up, i’faith. Will it not be?" },
    { r = {"NURSE"}, t = "What, dress’d, and in your clothes, and down again?" },
    { r = {"NURSE"}, t = "I must needs wake you. Lady! Lady! Lady!" },
    { r = {"NURSE"}, t = "Alas, alas! Help, help! My lady’s dead!" },
    { r = {"NURSE"}, t = "O, well-a-day that ever I was born." },
    { r = {"NURSE"}, t = "Some aqua vitae, ho! My lord! My lady!" },
    { d = "Enter Lady Capulet" },
    { r = {"LADY CAPULET"}, t = "What noise is here?" },
    { r = {"NURSE"}, t = "O lamentable day!" },
    { r = {"LADY CAPULET"}, t = "What is the matter?" },
    { r = {"NURSE"}, t = "Look, look! O heavy day!" },
    { r = {"LADY CAPULET"}, t = "O me, O me! My child, my only life." },
    { r = {"LADY CAPULET"}, t = "Revive, look up, or I will die with thee." },
    { r = {"LADY CAPULET"}, t = "Help, help! Call help." },
    { d = "Enter Capulet" },
    { r = {"CAPULET"}, t = "For shame, bring Juliet forth, her lord is come." },
    { r = {"NURSE"}, t = "She’s dead, deceas’d, she’s dead; alack the day!" },
    { r = {"LADY CAPULET"}, t = "Alack the day, she’s dead, she’s dead, she’s dead!" },
    { r = {"CAPULET"}, t = "Ha! Let me see her. Out alas! She’s cold," },
    { r = {"CAPULET"}, t = "Her blood is settled and her joints are stiff." },
    { r = {"CAPULET"}, t = "Life and these lips have long been separated." },
    { r = {"CAPULET"}, t = "Death lies on her like an untimely frost" },
    { r = {"CAPULET"}, t = "Upon the sweetest flower of all the field." },
    { r = {"NURSE"}, t = "O lamentable day!" },
    { r = {"LADY CAPULET"}, t = "O woful time!" },
    { r = {"CAPULET"}, t = "Death, that hath ta’en her hence to make me wail," },
    { r = {"CAPULET"}, t = "Ties up my tongue and will not let me speak." },
    { d = "Enter Friar Lawrence and Paris with Musicians" },
    { r = {"FRIAR LAWRENCE"}, t = "Come, is the bride ready to go to church?" },
    { r = {"CAPULET"}, t = "Ready to go, but never to return." },
    { r = {"CAPULET"}, t = "O son, the night before thy wedding day" },
    { r = {"CAPULET"}, t = "Hath death lain with thy bride. There she lies," },
    { r = {"CAPULET"}, t = "Flower as she was, deflowered by him." },
    { r = {"CAPULET"}, t = "Death is my son-in-law, death is my heir;" },
    { r = {"CAPULET"}, t = "My daughter he hath wedded. I will die" },
    { r = {"CAPULET"}, t = "And leave him all; life, living, all is death’s." },
    { r = {"PARIS"}, t = "Have I thought long to see this morning’s face," },
    { r = {"PARIS"}, t = "And doth it give me such a sight as this?" },
    { r = {"LADY CAPULET"}, t = "Accurs’d, unhappy, wretched, hateful day." },
    { r = {"LADY CAPULET"}, t = "Most miserable hour that e’er time saw" },
    { r = {"LADY CAPULET"}, t = "In lasting labour of his pilgrimage." },
    { r = {"LADY CAPULET"}, t = "But one, poor one, one poor and loving child," },
    { r = {"LADY CAPULET"}, t = "But one thing to rejoice and solace in," },
    { r = {"LADY CAPULET"}, t = "And cruel death hath catch’d it from my sight." },
    { r = {"NURSE"}, t = "O woe! O woeful, woeful, woeful day." },
    { r = {"NURSE"}, t = "Most lamentable day, most woeful day" },
    { r = {"NURSE"}, t = "That ever, ever, I did yet behold!" },
    { r = {"NURSE"}, t = "O day, O day, O day, O hateful day." },
    { r = {"NURSE"}, t = "Never was seen so black a day as this." },
    { r = {"NURSE"}, t = "O woeful day, O woeful day." },
    { r = {"PARIS"}, t = "Beguil’d, divorced, wronged, spited, slain." },
    { r = {"PARIS"}, t = "Most detestable death, by thee beguil’d," },
    { r = {"PARIS"}, t = "By cruel, cruel thee quite overthrown." },
    { r = {"PARIS"}, t = "O love! O life! Not life, but love in death!" },
    { r = {"CAPULET"}, t = "Despis’d, distressed, hated, martyr’d, kill’d." },
    { r = {"CAPULET"}, t = "Uncomfortable time, why cam’st thou now" },
    { r = {"CAPULET"}, t = "To murder, murder our solemnity?" },
    { r = {"CAPULET"}, t = "O child! O child! My soul, and not my child," },
    { r = {"CAPULET"}, t = "Dead art thou. Alack, my child is dead," },
    { r = {"CAPULET"}, t = "And with my child my joys are buried." },
    { r = {"FRIAR LAWRENCE"}, t = "Peace, ho, for shame. Confusion’s cure lives not" },
    { r = {"FRIAR LAWRENCE"}, t = "In these confusions. Heaven and yourself" },
    { r = {"FRIAR LAWRENCE"}, t = "Had part in this fair maid, now heaven hath all," },
    { r = {"FRIAR LAWRENCE"}, t = "And all the better is it for the maid." },
    { r = {"FRIAR LAWRENCE"}, t = "Your part in her you could not keep from death," },
    { r = {"FRIAR LAWRENCE"}, t = "But heaven keeps his part in eternal life." },
    { r = {"FRIAR LAWRENCE"}, t = "The most you sought was her promotion," },
    { r = {"FRIAR LAWRENCE"}, t = "For ’twas your heaven she should be advanc’d," },
    { r = {"FRIAR LAWRENCE"}, t = "And weep ye now, seeing she is advanc’d" },
    { r = {"FRIAR LAWRENCE"}, t = "Above the clouds, as high as heaven itself?" },
    { r = {"FRIAR LAWRENCE"}, t = "O, in this love, you love your child so ill" },
    { r = {"FRIAR LAWRENCE"}, t = "That you run mad, seeing that she is well." },
    { r = {"FRIAR LAWRENCE"}, t = "She’s not well married that lives married long," },
    { r = {"FRIAR LAWRENCE"}, t = "But she’s best married that dies married young." },
    { r = {"FRIAR LAWRENCE"}, t = "Dry up your tears, and stick your rosemary" },
    { r = {"FRIAR LAWRENCE"}, t = "On this fair corse, and, as the custom is," },
    { r = {"FRIAR LAWRENCE"}, t = "And in her best array bear her to church;" },
    { r = {"FRIAR LAWRENCE"}, t = "For though fond nature bids us all lament," },
    { r = {"FRIAR LAWRENCE"}, t = "Yet nature’s tears are reason’s merriment." },
    { r = {"CAPULET"}, t = "All things that we ordained festival" },
    { r = {"CAPULET"}, t = "Turn from their office to black funeral:" },
    { r = {"CAPULET"}, t = "Our instruments to melancholy bells," },
    { r = {"CAPULET"}, t = "Our wedding cheer to a sad burial feast;" },
    { r = {"CAPULET"}, t = "Our solemn hymns to sullen dirges change;" },
    { r = {"CAPULET"}, t = "Our bridal flowers serve for a buried corse," },
    { r = {"CAPULET"}, t = "And all things change them to the contrary." },
    { r = {"FRIAR LAWRENCE"}, t = "Sir, go you in, and, madam, go with him," },
    { r = {"FRIAR LAWRENCE"}, t = "And go, Sir Paris, everyone prepare" },
    { r = {"FRIAR LAWRENCE"}, t = "To follow this fair corse unto her grave." },
    { r = {"FRIAR LAWRENCE"}, t = "The heavens do lower upon you for some ill;" },
    { r = {"FRIAR LAWRENCE"}, t = "Move them no more by crossing their high will." },
    { d = "Exeunt Capulet, Lady Capulet, Paris and Friar" },
    { r = {"FIRST MUSICIAN"}, t = "Faith, we may put up our pipes and be gone." },
    { r = {"NURSE"}, t = "Honest good fellows, ah, put up, put up," },
    { r = {"NURSE"}, t = "For well you know this is a pitiful case." },
    { r = {"FIRST MUSICIAN"}, t = "Ay, by my troth, the case may be amended." },
    { d = "Exit Nurse" },
    { d = "Enter Peter" },
    { r = {"PETER"}, t = "Musicians, O, musicians, ‘Heart’s ease,’ ‘Heart’s ease’, O, and you will have me live, play ‘Heart’s ease.’" },
    { r = {"FIRST MUSICIAN"}, t = "Why ‘Heart’s ease’?" },
    { r = {"PETER"}, t = "O musicians, because my heart itself plays ‘My heart is full’." },
    { r = {"PETER"}, t = "O play me some merry dump to comfort me." },
    { r = {"FIRST MUSICIAN"}, t = "Not a dump we, ’tis no time to play now." },
    { r = {"PETER"}, t = "You will not then?" },
    { r = {"FIRST MUSICIAN"}, t = "No." },
    { r = {"PETER"}, t = "I will then give it you soundly." },
    { r = {"FIRST MUSICIAN"}, t = "What will you give us?" },
    { r = {"PETER"}, t = "No money, on my faith, but the gleek! I will give you the minstrel." },
    { r = {"FIRST MUSICIAN"}, t = "Then will I give you the serving-creature." },
    { r = {"PETER"}, t = "Then will I lay the serving-creature’s dagger on your pate." },
    { r = {"PETER"}, t = "I will carry no crotchets." },
    { r = {"PETER"}, t = "I’ll re you, I’ll fa you." },
    { r = {"PETER"}, t = "Do you note me?" },
    { r = {"FIRST MUSICIAN"}, t = "And you re us and fa us, you note us." },
    { r = {"SECOND MUSICIAN"}, t = "Pray you put up your dagger, and put out your wit." },
    { r = {"PETER"}, t = "Then have at you with my wit." },
    { r = {"PETER"}, t = "I will dry-beat you with an iron wit, and put up my iron dagger." },
    { r = {"PETER"}, t = "Answer me like men." },
    { r = {"PETER"}, t = "‘When griping griefs the heart doth wound," },
    { r = {"PETER"}, t = "And doleful dumps the mind oppress," },
    { r = {"PETER"}, t = "Then music with her silver sound’—" },
    { r = {"PETER"}, t = "Why ‘silver sound’?" },
    { r = {"PETER"}, t = "Why ‘music with her silver sound’?" },
    { r = {"PETER"}, t = "What say you, Simon Catling?" },
    { r = {"FIRST MUSICIAN"}, t = "Marry, sir, because silver hath a sweet sound." },
    { r = {"PETER"}, t = "Prates. What say you, Hugh Rebeck?" },
    { r = {"SECOND MUSICIAN"}, t = "I say ‘silver sound’ because musicians sound for silver." },
    { r = {"PETER"}, t = "Prates too! What say you, James Soundpost?" },
    { r = {"THIRD MUSICIAN"}, t = "Faith, I know not what to say." },
    { r = {"PETER"}, t = "O, I cry you mercy, you are the singer." },
    { r = {"PETER"}, t = "I will say for you." },
    { r = {"PETER"}, t = "It is ‘music with her silver sound’ because musicians have no gold for sounding." },
    { r = {"PETER"}, t = "‘Then music with her silver sound" },
    { r = {"PETER"}, t = "With speedy help doth lend redress.’" },
    { d = "Exit" },
    { r = {"FIRST MUSICIAN"}, t = "What a pestilent knave is this same!" },
    { r = {"SECOND MUSICIAN"}, t = "Hang him, Jack." },
    { r = {"SECOND MUSICIAN"}, t = "Come, we’ll in here, tarry for the mourners, and stay dinner." },
    { d = "Exeunt" },
    { d = "Act 5, Scene 1. Mantua. A Street.", h = true },
    { d = "Enter Romeo" },
    { r = {"ROMEO"}, t = "If I may trust the flattering eye of sleep," },
    { r = {"ROMEO"}, t = "My dreams presage some joyful news at hand." },
    { r = {"ROMEO"}, t = "My bosom’s lord sits lightly in his throne;" },
    { r = {"ROMEO"}, t = "And all this day an unaccustom’d spirit" },
    { r = {"ROMEO"}, t = "Lifts me above the ground with cheerful thoughts." },
    { r = {"ROMEO"}, t = "I dreamt my lady came and found me dead,—" },
    { r = {"ROMEO"}, t = "Strange dream, that gives a dead man leave to think!—" },
    { r = {"ROMEO"}, t = "And breath’d such life with kisses in my lips," },
    { r = {"ROMEO"}, t = "That I reviv’d, and was an emperor." },
    { r = {"ROMEO"}, t = "Ah me, how sweet is love itself possess’d," },
    { r = {"ROMEO"}, t = "When but love’s shadows are so rich in joy." },
    { d = "Enter Balthasar" },
    { r = {"ROMEO"}, t = "News from Verona! How now, Balthasar?" },
    { r = {"ROMEO"}, t = "Dost thou not bring me letters from the Friar?" },
    { r = {"ROMEO"}, t = "How doth my lady? Is my father well?" },
    { r = {"ROMEO"}, t = "How fares my Juliet? That I ask again;" },
    { r = {"ROMEO"}, t = "For nothing can be ill if she be well." },
    { r = {"BALTHASAR"}, t = "Then she is well, and nothing can be ill." },
    { r = {"BALTHASAR"}, t = "Her body sleeps in Capel’s monument," },
    { r = {"BALTHASAR"}, t = "And her immortal part with angels lives." },
    { r = {"BALTHASAR"}, t = "I saw her laid low in her kindred’s vault," },
    { r = {"BALTHASAR"}, t = "And presently took post to tell it you." },
    { r = {"BALTHASAR"}, t = "O pardon me for bringing these ill news," },
    { r = {"BALTHASAR"}, t = "Since you did leave it for my office, sir." },
    { r = {"ROMEO"}, t = "Is it even so? Then I defy you, stars!" },
    { r = {"ROMEO"}, t = "Thou know’st my lodging. Get me ink and paper," },
    { r = {"ROMEO"}, t = "And hire post-horses. I will hence tonight." },
    { r = {"BALTHASAR"}, t = "I do beseech you sir, have patience." },
    { r = {"BALTHASAR"}, t = "Your looks are pale and wild, and do import" },
    { r = {"BALTHASAR"}, t = "Some misadventure." },
    { r = {"ROMEO"}, t = "Tush, thou art deceiv’d." },
    { r = {"ROMEO"}, t = "Leave me, and do the thing I bid thee do." },
    { r = {"ROMEO"}, t = "Hast thou no letters to me from the Friar?" },
    { r = {"BALTHASAR"}, t = "No, my good lord." },
    { r = {"ROMEO"}, t = "No matter. Get thee gone," },
    { r = {"ROMEO"}, t = "And hire those horses. I’ll be with thee straight." },
    { d = "Exit Balthasar" },
    { r = {"ROMEO"}, t = "Well, Juliet, I will lie with thee tonight." },
    { r = {"ROMEO"}, t = "Let’s see for means. O mischief thou art swift" },
    { r = {"ROMEO"}, t = "To enter in the thoughts of desperate men." },
    { r = {"ROMEO"}, t = "I do remember an apothecary,—" },
    { r = {"ROMEO"}, t = "And hereabouts he dwells,—which late I noted" },
    { r = {"ROMEO"}, t = "In tatter’d weeds, with overwhelming brows," },
    { r = {"ROMEO"}, t = "Culling of simples, meagre were his looks," },
    { r = {"ROMEO"}, t = "Sharp misery had worn him to the bones;" },
    { r = {"ROMEO"}, t = "And in his needy shop a tortoise hung," },
    { r = {"ROMEO"}, t = "An alligator stuff’d, and other skins" },
    { r = {"ROMEO"}, t = "Of ill-shaped fishes; and about his shelves" },
    { r = {"ROMEO"}, t = "A beggarly account of empty boxes," },
    { r = {"ROMEO"}, t = "Green earthen pots, bladders, and musty seeds," },
    { r = {"ROMEO"}, t = "Remnants of packthread, and old cakes of roses" },
    { r = {"ROMEO"}, t = "Were thinly scatter’d, to make up a show." },
    { r = {"ROMEO"}, t = "Noting this penury, to myself I said," },
    { r = {"ROMEO"}, t = "And if a man did need a poison now," },
    { r = {"ROMEO"}, t = "Whose sale is present death in Mantua," },
    { r = {"ROMEO"}, t = "Here lives a caitiff wretch would sell it him." },
    { r = {"ROMEO"}, t = "O, this same thought did but forerun my need," },
    { r = {"ROMEO"}, t = "And this same needy man must sell it me." },
    { r = {"ROMEO"}, t = "As I remember, this should be the house." },
    { r = {"ROMEO"}, t = "Being holiday, the beggar’s shop is shut." },
    { r = {"ROMEO"}, t = "What, ho! Apothecary!" },
    { d = "Enter Apothecary" },
    { r = {"APOTHECARY"}, t = "Who calls so loud?" },
    { r = {"ROMEO"}, t = "Come hither, man. I see that thou art poor." },
    { r = {"ROMEO"}, t = "Hold, there is forty ducats. Let me have" },
    { r = {"ROMEO"}, t = "A dram of poison, such soon-speeding gear" },
    { r = {"ROMEO"}, t = "As will disperse itself through all the veins," },
    { r = {"ROMEO"}, t = "That the life-weary taker may fall dead," },
    { r = {"ROMEO"}, t = "And that the trunk may be discharg’d of breath" },
    { r = {"ROMEO"}, t = "As violently as hasty powder fir’d" },
    { r = {"ROMEO"}, t = "Doth hurry from the fatal cannon’s womb." },
    { r = {"APOTHECARY"}, t = "Such mortal drugs I have, but Mantua’s law" },
    { r = {"APOTHECARY"}, t = "Is death to any he that utters them." },
    { r = {"ROMEO"}, t = "Art thou so bare and full of wretchedness," },
    { r = {"ROMEO"}, t = "And fear’st to die? Famine is in thy cheeks," },
    { r = {"ROMEO"}, t = "Need and oppression starveth in thine eyes," },
    { r = {"ROMEO"}, t = "Contempt and beggary hangs upon thy back." },
    { r = {"ROMEO"}, t = "The world is not thy friend, nor the world’s law;" },
    { r = {"ROMEO"}, t = "The world affords no law to make thee rich;" },
    { r = {"ROMEO"}, t = "Then be not poor, but break it and take this." },
    { r = {"APOTHECARY"}, t = "My poverty, but not my will consents." },
    { r = {"ROMEO"}, t = "I pay thy poverty, and not thy will." },
    { r = {"APOTHECARY"}, t = "Put this in any liquid thing you will" },
    { r = {"APOTHECARY"}, t = "And drink it off; and, if you had the strength" },
    { r = {"APOTHECARY"}, t = "Of twenty men, it would despatch you straight." },
    { r = {"ROMEO"}, t = "There is thy gold, worse poison to men’s souls," },
    { r = {"ROMEO"}, t = "Doing more murder in this loathsome world" },
    { r = {"ROMEO"}, t = "Than these poor compounds that thou mayst not sell." },
    { r = {"ROMEO"}, t = "I sell thee poison, thou hast sold me none." },
    { r = {"ROMEO"}, t = "Farewell, buy food, and get thyself in flesh." },
    { r = {"ROMEO"}, t = "Come, cordial and not poison, go with me" },
    { r = {"ROMEO"}, t = "To Juliet’s grave, for there must I use thee." },
    { d = "Exeunt" },
    { d = "Act 5, Scene 2. Friar Lawrence’s Cell.", h = true },
    { d = "Enter Friar John" },
    { r = {"FRIAR JOHN"}, t = "Holy Franciscan Friar! Brother, ho!" },
    { d = "Enter Friar Lawrence" },
    { r = {"FRIAR LAWRENCE"}, t = "This same should be the voice of Friar John." },
    { r = {"FRIAR LAWRENCE"}, t = "Welcome from Mantua. What says Romeo?" },
    { r = {"FRIAR LAWRENCE"}, t = "Or, if his mind be writ, give me his letter." },
    { r = {"FRIAR JOHN"}, t = "Going to find a barefoot brother out," },
    { r = {"FRIAR JOHN"}, t = "One of our order, to associate me," },
    { r = {"FRIAR JOHN"}, t = "Here in this city visiting the sick," },
    { r = {"FRIAR JOHN"}, t = "And finding him, the searchers of the town," },
    { r = {"FRIAR JOHN"}, t = "Suspecting that we both were in a house" },
    { r = {"FRIAR JOHN"}, t = "Where the infectious pestilence did reign," },
    { r = {"FRIAR JOHN"}, t = "Seal’d up the doors, and would not let us forth," },
    { r = {"FRIAR JOHN"}, t = "So that my speed to Mantua there was stay’d." },
    { r = {"FRIAR LAWRENCE"}, t = "Who bare my letter then to Romeo?" },
    { r = {"FRIAR JOHN"}, t = "I could not send it,—here it is again,—" },
    { r = {"FRIAR JOHN"}, t = "Nor get a messenger to bring it thee," },
    { r = {"FRIAR JOHN"}, t = "So fearful were they of infection." },
    { r = {"FRIAR LAWRENCE"}, t = "Unhappy fortune! By my brotherhood," },
    { r = {"FRIAR LAWRENCE"}, t = "The letter was not nice, but full of charge," },
    { r = {"FRIAR LAWRENCE"}, t = "Of dear import, and the neglecting it" },
    { r = {"FRIAR LAWRENCE"}, t = "May do much danger. Friar John, go hence," },
    { r = {"FRIAR LAWRENCE"}, t = "Get me an iron crow and bring it straight" },
    { r = {"FRIAR LAWRENCE"}, t = "Unto my cell." },
    { r = {"FRIAR JOHN"}, t = "Brother, I’ll go and bring it thee." },
    { d = "Exit" },
    { r = {"FRIAR LAWRENCE"}, t = "Now must I to the monument alone." },
    { r = {"FRIAR LAWRENCE"}, t = "Within this three hours will fair Juliet wake." },
    { r = {"FRIAR LAWRENCE"}, t = "She will beshrew me much that Romeo" },
    { r = {"FRIAR LAWRENCE"}, t = "Hath had no notice of these accidents;" },
    { r = {"FRIAR LAWRENCE"}, t = "But I will write again to Mantua," },
    { r = {"FRIAR LAWRENCE"}, t = "And keep her at my cell till Romeo come." },
    { r = {"FRIAR LAWRENCE"}, t = "Poor living corse, clos’d in a dead man’s tomb." },
    { d = "Exit" },
    { d = "Act 5, Scene 3. A churchyard; in it a Monument belonging to the Capulets.", h = true },
    { d = "Enter Paris, and his Page bearing flowers and a torch" },
    { r = {"PARIS"}, t = "Give me thy torch, boy. Hence and stand aloof." },
    { r = {"PARIS"}, t = "Yet put it out, for I would not be seen." },
    { r = {"PARIS"}, t = "Under yond yew tree lay thee all along," },
    { r = {"PARIS"}, t = "Holding thy ear close to the hollow ground;" },
    { r = {"PARIS"}, t = "So shall no foot upon the churchyard tread," },
    { r = {"PARIS"}, t = "Being loose, unfirm, with digging up of graves," },
    { r = {"PARIS"}, t = "But thou shalt hear it. Whistle then to me," },
    { r = {"PARIS"}, t = "As signal that thou hear’st something approach." },
    { r = {"PARIS"}, t = "Give me those flowers. Do as I bid thee, go." },
    { r = {"PAGE"}, t = "I am almost afraid to stand alone", d = "Aside" },
    { r = {"PAGE"}, t = "Here in the churchyard; yet I will adventure." },
    { d = "Retires" },
    { r = {"PARIS"}, t = "Sweet flower, with flowers thy bridal bed I strew." },
    { r = {"PARIS"}, t = "O woe, thy canopy is dust and stones," },
    { r = {"PARIS"}, t = "Which with sweet water nightly I will dew," },
    { r = {"PARIS"}, t = "Or wanting that, with tears distill’d by moans." },
    { r = {"PARIS"}, t = "The obsequies that I for thee will keep," },
    { r = {"PARIS"}, t = "Nightly shall be to strew thy grave and weep." },
    { d = "The Page whistles" },
    { r = {"PARIS"}, t = "The boy gives warning something doth approach." },
    { r = {"PARIS"}, t = "What cursed foot wanders this way tonight," },
    { r = {"PARIS"}, t = "To cross my obsequies and true love’s rite?" },
    { r = {"PARIS"}, t = "What, with a torch! Muffle me, night, awhile." },
    { d = "Retires" },
    { d = "Enter Romeo and Balthasar with a torch, mattock, &c" },
    { r = {"ROMEO"}, t = "Give me that mattock and the wrenching iron." },
    { r = {"ROMEO"}, t = "Hold, take this letter; early in the morning" },
    { r = {"ROMEO"}, t = "See thou deliver it to my lord and father." },
    { r = {"ROMEO"}, t = "Give me the light; upon thy life I charge thee," },
    { r = {"ROMEO"}, t = "Whate’er thou hear’st or seest, stand all aloof" },
    { r = {"ROMEO"}, t = "And do not interrupt me in my course." },
    { r = {"ROMEO"}, t = "Why I descend into this bed of death" },
    { r = {"ROMEO"}, t = "Is partly to behold my lady’s face," },
    { r = {"ROMEO"}, t = "But chiefly to take thence from her dead finger" },
    { r = {"ROMEO"}, t = "A precious ring, a ring that I must use" },
    { r = {"ROMEO"}, t = "In dear employment. Therefore hence, be gone." },
    { r = {"ROMEO"}, t = "But if thou jealous dost return to pry" },
    { r = {"ROMEO"}, t = "In what I further shall intend to do," },
    { r = {"ROMEO"}, t = "By heaven I will tear thee joint by joint," },
    { r = {"ROMEO"}, t = "And strew this hungry churchyard with thy limbs." },
    { r = {"ROMEO"}, t = "The time and my intents are savage-wild;" },
    { r = {"ROMEO"}, t = "More fierce and more inexorable far" },
    { r = {"ROMEO"}, t = "Than empty tigers or the roaring sea." },
    { r = {"BALTHASAR"}, t = "I will be gone, sir, and not trouble you." },
    { r = {"ROMEO"}, t = "So shalt thou show me friendship. Take thou that." },
    { r = {"ROMEO"}, t = "Live, and be prosperous, and farewell, good fellow." },
    { r = {"BALTHASAR"}, t = "For all this same, I’ll hide me hereabout." },
    { r = {"BALTHASAR"}, t = "His looks I fear, and his intents I doubt." },
    { d = "Retires" },
    { r = {"ROMEO"}, t = "Thou detestable maw, thou womb of death," },
    { r = {"ROMEO"}, t = "Gorg’d with the dearest morsel of the earth," },
    { r = {"ROMEO"}, t = "Thus I enforce thy rotten jaws to open," },
    { d = "Breaking open the door of the monument" },
    { r = {"ROMEO"}, t = "And in despite, I’ll cram thee with more food." },
    { r = {"PARIS"}, t = "This is that banish’d haughty Montague" },
    { r = {"PARIS"}, t = "That murder’d my love’s cousin,—with which grief," },
    { r = {"PARIS"}, t = "It is supposed, the fair creature died,—" },
    { r = {"PARIS"}, t = "And here is come to do some villainous shame" },
    { r = {"PARIS"}, t = "To the dead bodies. I will apprehend him." },
    { d = "Advances" },
    { r = {"PARIS"}, t = "Stop thy unhallow’d toil, vile Montague." },
    { r = {"PARIS"}, t = "Can vengeance be pursu’d further than death?" },
    { r = {"PARIS"}, t = "Condemned villain, I do apprehend thee." },
    { r = {"PARIS"}, t = "Obey, and go with me, for thou must die." },
    { r = {"ROMEO"}, t = "I must indeed; and therefore came I hither." },
    { r = {"ROMEO"}, t = "Good gentle youth, tempt not a desperate man." },
    { r = {"ROMEO"}, t = "Fly hence and leave me. Think upon these gone;" },
    { r = {"ROMEO"}, t = "Let them affright thee. I beseech thee, youth," },
    { r = {"ROMEO"}, t = "Put not another sin upon my head" },
    { r = {"ROMEO"}, t = "By urging me to fury. O be gone." },
    { r = {"ROMEO"}, t = "By heaven I love thee better than myself;" },
    { r = {"ROMEO"}, t = "For I come hither arm’d against myself." },
    { r = {"ROMEO"}, t = "Stay not, be gone, live, and hereafter say," },
    { r = {"ROMEO"}, t = "A madman’s mercy bid thee run away." },
    { r = {"PARIS"}, t = "I do defy thy conjuration," },
    { r = {"PARIS"}, t = "And apprehend thee for a felon here." },
    { r = {"ROMEO"}, t = "Wilt thou provoke me? Then have at thee, boy!" },
    { d = "They fight" },
    { r = {"PAGE"}, t = "O lord, they fight! I will go call the watch." },
    { d = "Exit" },
    { r = {"PARIS"}, t = "O, I am slain!" },
    { r = {"PARIS"}, t = "If thou be merciful,", d = "Falls" },
    { r = {"PARIS"}, t = "Open the tomb, lay me with Juliet." },
    { r = {"PARIS"}, d = "Dies", e = "/lie", s = {"Feign Death"} },
    { r = {"ROMEO"}, t = "In faith, I will. Let me peruse this face." },
    { r = {"ROMEO"}, t = "Mercutio’s kinsman, noble County Paris!" },
    { r = {"ROMEO"}, t = "What said my man, when my betossed soul" },
    { r = {"ROMEO"}, t = "Did not attend him as we rode? I think" },
    { r = {"ROMEO"}, t = "He told me Paris should have married Juliet." },
    { r = {"ROMEO"}, t = "Said he not so? Or did I dream it so?" },
    { r = {"ROMEO"}, t = "Or am I mad, hearing him talk of Juliet," },
    { r = {"ROMEO"}, t = "To think it was so? O, give me thy hand," },
    { r = {"ROMEO"}, t = "One writ with me in sour misfortune’s book." },
    { r = {"ROMEO"}, t = "I’ll bury thee in a triumphant grave." },
    { r = {"ROMEO"}, t = "A grave? O no, a lantern, slaught’red youth," },
    { r = {"ROMEO"}, t = "For here lies Juliet, and her beauty makes" },
    { r = {"ROMEO"}, t = "This vault a feasting presence full of light." },
    { r = {"ROMEO"}, t = "Death, lie thou there, by a dead man interr’d." },
    { d = "Laying Paris in the monument" },
    { r = {"ROMEO"}, t = "How oft when men are at the point of death" },
    { r = {"ROMEO"}, t = "Have they been merry! Which their keepers call" },
    { r = {"ROMEO"}, t = "A lightning before death. O, how may I" },
    { r = {"ROMEO"}, t = "Call this a lightning? O my love, my wife," },
    { r = {"ROMEO"}, t = "Death that hath suck’d the honey of thy breath," },
    { r = {"ROMEO"}, t = "Hath had no power yet upon thy beauty." },
    { r = {"ROMEO"}, t = "Thou art not conquer’d. Beauty’s ensign yet" },
    { r = {"ROMEO"}, t = "Is crimson in thy lips and in thy cheeks," },
    { r = {"ROMEO"}, t = "And death’s pale flag is not advanced there." },
    { r = {"ROMEO"}, t = "Tybalt, liest thou there in thy bloody sheet?" },
    { r = {"ROMEO"}, t = "O, what more favour can I do to thee" },
    { r = {"ROMEO"}, t = "Than with that hand that cut thy youth in twain" },
    { r = {"ROMEO"}, t = "To sunder his that was thine enemy?" },
    { r = {"ROMEO"}, t = "Forgive me, cousin. Ah, dear Juliet," },
    { r = {"ROMEO"}, t = "Why art thou yet so fair? Shall I believe" },
    { r = {"ROMEO"}, t = "That unsubstantial death is amorous;" },
    { r = {"ROMEO"}, t = "And that the lean abhorred monster keeps" },
    { r = {"ROMEO"}, t = "Thee here in dark to be his paramour?" },
    { r = {"ROMEO"}, t = "For fear of that I still will stay with thee," },
    { r = {"ROMEO"}, t = "And never from this palace of dim night" },
    { r = {"ROMEO"}, t = "Depart again. Here, here will I remain" },
    { r = {"ROMEO"}, t = "With worms that are thy chambermaids. O, here" },
    { r = {"ROMEO"}, t = "Will I set up my everlasting rest;" },
    { r = {"ROMEO"}, t = "And shake the yoke of inauspicious stars" },
    { r = {"ROMEO"}, t = "From this world-wearied flesh. Eyes, look your last." },
    { r = {"ROMEO"}, t = "Arms, take your last embrace! And, lips, O you" },
    { r = {"ROMEO"}, t = "The doors of breath, seal with a righteous kiss" },
    { r = {"ROMEO"}, t = "A dateless bargain to engrossing death." },
    { r = {"ROMEO"}, t = "Come, bitter conduct, come, unsavoury guide." },
    { r = {"ROMEO"}, t = "Thou desperate pilot, now at once run on" },
    { r = {"ROMEO"}, t = "The dashing rocks thy sea-sick weary bark." },
    { r = {"ROMEO"}, t = "Here’s to my love!" },
    { r = {"ROMEO"}, t = "O true apothecary!", d = "Drinks", u = {"Refreshing Spring Water"} },
    { r = {"ROMEO"}, t = "Thy drugs are quick. Thus with a kiss I die." },
    { r = {"ROMEO"}, d = "Dies", e = "/lie", s = {"Feign Death"} },
    { d = "Enter, at the other end of the Churchyard, Friar Lawrence, with a lantern, crow, and spade" },
    { r = {"FRIAR LAWRENCE"}, t = "Saint Francis be my speed. How oft tonight" },
    { r = {"FRIAR LAWRENCE"}, t = "Have my old feet stumbled at graves? Who’s there?" },
    { r = {"FRIAR LAWRENCE"}, t = "Who is it that consorts, so late, the dead?" },
    { r = {"BALTHASAR"}, t = "Here’s one, a friend, and one that knows you well." },
    { r = {"FRIAR LAWRENCE"}, t = "Bliss be upon you. Tell me, good my friend," },
    { r = {"FRIAR LAWRENCE"}, t = "What torch is yond that vainly lends his light" },
    { r = {"FRIAR LAWRENCE"}, t = "To grubs and eyeless skulls? As I discern," },
    { r = {"FRIAR LAWRENCE"}, t = "It burneth in the Capels’ monument." },
    { r = {"BALTHASAR"}, t = "It doth so, holy sir, and there’s my master," },
    { r = {"BALTHASAR"}, t = "One that you love." },
    { r = {"FRIAR LAWRENCE"}, t = "Who is it?" },
    { r = {"BALTHASAR"}, t = "Romeo." },
    { r = {"FRIAR LAWRENCE"}, t = "How long hath he been there?" },
    { r = {"BALTHASAR"}, t = "Full half an hour." },
    { r = {"FRIAR LAWRENCE"}, t = "Go with me to the vault." },
    { r = {"BALTHASAR"}, t = "I dare not, sir;" },
    { r = {"BALTHASAR"}, t = "My master knows not but I am gone hence," },
    { r = {"BALTHASAR"}, t = "And fearfully did menace me with death" },
    { r = {"BALTHASAR"}, t = "If I did stay to look on his intents." },
    { r = {"FRIAR LAWRENCE"}, t = "Stay then, I’ll go alone. Fear comes upon me." },
    { r = {"FRIAR LAWRENCE"}, t = "O, much I fear some ill unlucky thing." },
    { r = {"BALTHASAR"}, t = "As I did sleep under this yew tree here," },
    { r = {"BALTHASAR"}, t = "I dreamt my master and another fought," },
    { r = {"BALTHASAR"}, t = "And that my master slew him." },
    { r = {"FRIAR LAWRENCE"}, t = "Romeo!" },
    { r = {"FRIAR LAWRENCE"}, t = "Alack, alack, what blood is this which stains", d = "Advances" },
    { r = {"FRIAR LAWRENCE"}, t = "The stony entrance of this sepulchre?" },
    { r = {"FRIAR LAWRENCE"}, t = "What mean these masterless and gory swords" },
    { r = {"FRIAR LAWRENCE"}, t = "To lie discolour’d by this place of peace?" },
    { d = "Enters the monument" },
    { r = {"FRIAR LAWRENCE"}, t = "Romeo! O, pale! Who else? What, Paris too?" },
    { r = {"FRIAR LAWRENCE"}, t = "And steep’d in blood? Ah what an unkind hour" },
    { r = {"FRIAR LAWRENCE"}, t = "Is guilty of this lamentable chance?" },
    { r = {"FRIAR LAWRENCE"}, t = "The lady stirs." },
    { d = "Juliet wakes and stirs" },
    { r = {"JULIET"}, t = "O comfortable Friar, where is my lord?" },
    { r = {"JULIET"}, t = "I do remember well where I should be," },
    { r = {"JULIET"}, t = "And there I am. Where is my Romeo?" },
    { d = "Noise within" },
    { r = {"FRIAR LAWRENCE"}, t = "I hear some noise. Lady, come from that nest" },
    { r = {"FRIAR LAWRENCE"}, t = "Of death, contagion, and unnatural sleep." },
    { r = {"FRIAR LAWRENCE"}, t = "A greater power than we can contradict" },
    { r = {"FRIAR LAWRENCE"}, t = "Hath thwarted our intents. Come, come away." },
    { r = {"FRIAR LAWRENCE"}, t = "Thy husband in thy bosom there lies dead;" },
    { r = {"FRIAR LAWRENCE"}, t = "And Paris too. Come, I’ll dispose of thee" },
    { r = {"FRIAR LAWRENCE"}, t = "Among a sisterhood of holy nuns." },
    { r = {"FRIAR LAWRENCE"}, t = "Stay not to question, for the watch is coming." },
    { r = {"FRIAR LAWRENCE"}, t = "Come, go, good Juliet. I dare no longer stay." },
    { r = {"JULIET"}, t = "Go, get thee hence, for I will not away." },
    { d = "Exit Friar Lawrence" },
    { r = {"JULIET"}, t = "What’s here? A cup clos’d in my true love’s hand?" },
    { r = {"JULIET"}, t = "Poison, I see, hath been his timeless end." },
    { r = {"JULIET"}, t = "O churl. Drink all, and left no friendly drop" },
    { r = {"JULIET"}, t = "To help me after? I will kiss thy lips." },
    { r = {"JULIET"}, t = "Haply some poison yet doth hang on them," },
    { r = {"JULIET"}, t = "To make me die with a restorative." },
    { r = {"JULIET"}, d = "Kisses him", e = "/kiss", at = "ROMEO" },
    { r = {"JULIET"}, t = "Thy lips are warm!" },
    { r = {"FIRST WATCH"}, t = "Lead, boy. Which way?", d = "Within" },
    { r = {"JULIET"}, t = "Yea, noise? Then I’ll be brief. O happy dagger." },
    { d = "Snatching Romeo’s dagger" },
    { r = {"JULIET"}, t = "This is thy sheath." },
    { r = {"JULIET"}, t = "There rest, and let me die.", d = "stabs herself" },
    { r = {"JULIET"}, d = "Falls on Romeo’s body and dies", e = "/lie", s = {"Feign Death"} },
    { d = "Enter Watch with the Page of Paris" },
    { r = {"PAGE"}, t = "This is the place. There, where the torch doth burn." },
    { r = {"FIRST WATCH"}, t = "The ground is bloody. Search about the churchyard." },
    { r = {"FIRST WATCH"}, t = "Go, some of you, whoe’er you find attach." },
    { d = "Exeunt some of the Watch" },
    { r = {"FIRST WATCH"}, t = "Pitiful sight! Here lies the County slain," },
    { r = {"FIRST WATCH"}, t = "And Juliet bleeding, warm, and newly dead," },
    { r = {"FIRST WATCH"}, t = "Who here hath lain this two days buried." },
    { r = {"FIRST WATCH"}, t = "Go tell the Prince; run to the Capulets." },
    { r = {"FIRST WATCH"}, t = "Raise up the Montagues, some others search." },
    { d = "Exeunt others of the Watch" },
    { r = {"FIRST WATCH"}, t = "We see the ground whereon these woes do lie," },
    { r = {"FIRST WATCH"}, t = "But the true ground of all these piteous woes" },
    { r = {"FIRST WATCH"}, t = "We cannot without circumstance descry." },
    { d = "Re-enter some of the Watch with Balthasar" },
    { r = {"SECOND WATCH"}, t = "Here’s Romeo’s man. We found him in the churchyard." },
    { r = {"FIRST WATCH"}, t = "Hold him in safety till the Prince come hither." },
    { d = "Re-enter others of the Watch with Friar Lawrence" },
    { r = {"THIRD WATCH"}, t = "Here is a Friar that trembles, sighs, and weeps." },
    { r = {"THIRD WATCH"}, t = "We took this mattock and this spade from him" },
    { r = {"THIRD WATCH"}, t = "As he was coming from this churchyard side." },
    { r = {"FIRST WATCH"}, t = "A great suspicion. Stay the Friar too." },
    { d = "Enter the Prince and Attendants" },
    { r = {"ESCALUS"}, t = "What misadventure is so early up," },
    { r = {"ESCALUS"}, t = "That calls our person from our morning’s rest?" },
    { d = "Enter Capulet, Lady Capulet and others" },
    { r = {"CAPULET"}, t = "What should it be that they so shriek abroad?" },
    { r = {"LADY CAPULET"}, t = "O the people in the street cry Romeo," },
    { r = {"LADY CAPULET"}, t = "Some Juliet, and some Paris, and all run" },
    { r = {"LADY CAPULET"}, t = "With open outcry toward our monument." },
    { r = {"ESCALUS"}, t = "What fear is this which startles in our ears?" },
    { r = {"FIRST WATCH"}, t = "Sovereign, here lies the County Paris slain," },
    { r = {"FIRST WATCH"}, t = "And Romeo dead, and Juliet, dead before," },
    { r = {"FIRST WATCH"}, t = "Warm and new kill’d." },
    { r = {"ESCALUS"}, t = "Search, seek, and know how this foul murder comes." },
    { r = {"FIRST WATCH"}, t = "Here is a Friar, and slaughter’d Romeo’s man," },
    { r = {"FIRST WATCH"}, t = "With instruments upon them fit to open" },
    { r = {"FIRST WATCH"}, t = "These dead men’s tombs." },
    { r = {"CAPULET"}, t = "O heaven! O wife, look how our daughter bleeds!" },
    { r = {"CAPULET"}, t = "This dagger hath mista’en, for lo, his house" },
    { r = {"CAPULET"}, t = "Is empty on the back of Montague," },
    { r = {"CAPULET"}, t = "And it mis-sheathed in my daughter’s bosom." },
    { r = {"LADY CAPULET"}, t = "O me! This sight of death is as a bell" },
    { r = {"LADY CAPULET"}, t = "That warns my old age to a sepulchre." },
    { d = "Enter Montague and others" },
    { r = {"ESCALUS"}, t = "Come, Montague, for thou art early up," },
    { r = {"ESCALUS"}, t = "To see thy son and heir more early down." },
    { r = {"MONTAGUE"}, t = "Alas, my liege, my wife is dead tonight." },
    { r = {"MONTAGUE"}, t = "Grief of my son’s exile hath stopp’d her breath." },
    { r = {"MONTAGUE"}, t = "What further woe conspires against mine age?" },
    { r = {"ESCALUS"}, t = "Look, and thou shalt see." },
    { r = {"MONTAGUE"}, t = "O thou untaught! What manners is in this," },
    { r = {"MONTAGUE"}, t = "To press before thy father to a grave?" },
    { r = {"ESCALUS"}, t = "Seal up the mouth of outrage for a while," },
    { r = {"ESCALUS"}, t = "Till we can clear these ambiguities," },
    { r = {"ESCALUS"}, t = "And know their spring, their head, their true descent," },
    { r = {"ESCALUS"}, t = "And then will I be general of your woes," },
    { r = {"ESCALUS"}, t = "And lead you even to death. Meantime forbear," },
    { r = {"ESCALUS"}, t = "And let mischance be slave to patience." },
    { r = {"ESCALUS"}, t = "Bring forth the parties of suspicion." },
    { r = {"FRIAR LAWRENCE"}, t = "I am the greatest, able to do least," },
    { r = {"FRIAR LAWRENCE"}, t = "Yet most suspected, as the time and place" },
    { r = {"FRIAR LAWRENCE"}, t = "Doth make against me, of this direful murder." },
    { r = {"FRIAR LAWRENCE"}, t = "And here I stand, both to impeach and purge" },
    { r = {"FRIAR LAWRENCE"}, t = "Myself condemned and myself excus’d." },
    { r = {"ESCALUS"}, t = "Then say at once what thou dost know in this." },
    { r = {"FRIAR LAWRENCE"}, t = "I will be brief, for my short date of breath" },
    { r = {"FRIAR LAWRENCE"}, t = "Is not so long as is a tedious tale." },
    { r = {"FRIAR LAWRENCE"}, t = "Romeo, there dead, was husband to that Juliet," },
    { r = {"FRIAR LAWRENCE"}, t = "And she, there dead, that Romeo’s faithful wife." },
    { r = {"FRIAR LAWRENCE"}, t = "I married them; and their stol’n marriage day" },
    { r = {"FRIAR LAWRENCE"}, t = "Was Tybalt’s doomsday, whose untimely death" },
    { r = {"FRIAR LAWRENCE"}, t = "Banish’d the new-made bridegroom from this city;" },
    { r = {"FRIAR LAWRENCE"}, t = "For whom, and not for Tybalt, Juliet pin’d." },
    { r = {"FRIAR LAWRENCE"}, t = "You, to remove that siege of grief from her," },
    { r = {"FRIAR LAWRENCE"}, t = "Betroth’d, and would have married her perforce" },
    { r = {"FRIAR LAWRENCE"}, t = "To County Paris. Then comes she to me," },
    { r = {"FRIAR LAWRENCE"}, t = "And with wild looks, bid me devise some means" },
    { r = {"FRIAR LAWRENCE"}, t = "To rid her from this second marriage," },
    { r = {"FRIAR LAWRENCE"}, t = "Or in my cell there would she kill herself." },
    { r = {"FRIAR LAWRENCE"}, t = "Then gave I her, so tutored by my art," },
    { r = {"FRIAR LAWRENCE"}, t = "A sleeping potion, which so took effect" },
    { r = {"FRIAR LAWRENCE"}, t = "As I intended, for it wrought on her" },
    { r = {"FRIAR LAWRENCE"}, t = "The form of death. Meantime I writ to Romeo" },
    { r = {"FRIAR LAWRENCE"}, t = "That he should hither come as this dire night" },
    { r = {"FRIAR LAWRENCE"}, t = "To help to take her from her borrow’d grave," },
    { r = {"FRIAR LAWRENCE"}, t = "Being the time the potion’s force should cease." },
    { r = {"FRIAR LAWRENCE"}, t = "But he which bore my letter, Friar John," },
    { r = {"FRIAR LAWRENCE"}, t = "Was stay’d by accident; and yesternight" },
    { r = {"FRIAR LAWRENCE"}, t = "Return’d my letter back. Then all alone" },
    { r = {"FRIAR LAWRENCE"}, t = "At the prefixed hour of her waking" },
    { r = {"FRIAR LAWRENCE"}, t = "Came I to take her from her kindred’s vault," },
    { r = {"FRIAR LAWRENCE"}, t = "Meaning to keep her closely at my cell" },
    { r = {"FRIAR LAWRENCE"}, t = "Till I conveniently could send to Romeo." },
    { r = {"FRIAR LAWRENCE"}, t = "But when I came, some minute ere the time" },
    { r = {"FRIAR LAWRENCE"}, t = "Of her awaking, here untimely lay" },
    { r = {"FRIAR LAWRENCE"}, t = "The noble Paris and true Romeo dead." },
    { r = {"FRIAR LAWRENCE"}, t = "She wakes; and I entreated her come forth" },
    { r = {"FRIAR LAWRENCE"}, t = "And bear this work of heaven with patience." },
    { r = {"FRIAR LAWRENCE"}, t = "But then a noise did scare me from the tomb;" },
    { r = {"FRIAR LAWRENCE"}, t = "And she, too desperate, would not go with me," },
    { r = {"FRIAR LAWRENCE"}, t = "But, as it seems, did violence on herself." },
    { r = {"FRIAR LAWRENCE"}, t = "All this I know; and to the marriage" },
    { r = {"FRIAR LAWRENCE"}, t = "Her Nurse is privy. And if ought in this" },
    { r = {"FRIAR LAWRENCE"}, t = "Miscarried by my fault, let my old life" },
    { r = {"FRIAR LAWRENCE"}, t = "Be sacrific’d, some hour before his time," },
    { r = {"FRIAR LAWRENCE"}, t = "Unto the rigour of severest law." },
    { r = {"ESCALUS"}, t = "We still have known thee for a holy man." },
    { r = {"ESCALUS"}, t = "Where’s Romeo’s man? What can he say to this?" },
    { r = {"BALTHASAR"}, t = "I brought my master news of Juliet’s death," },
    { r = {"BALTHASAR"}, t = "And then in post he came from Mantua" },
    { r = {"BALTHASAR"}, t = "To this same place, to this same monument." },
    { r = {"BALTHASAR"}, t = "This letter he early bid me give his father," },
    { r = {"BALTHASAR"}, t = "And threaten’d me with death, going in the vault," },
    { r = {"BALTHASAR"}, t = "If I departed not, and left him there." },
    { r = {"ESCALUS"}, t = "Give me the letter, I will look on it." },
    { r = {"ESCALUS"}, t = "Where is the County’s Page that rais’d the watch?" },
    { r = {"ESCALUS"}, t = "Sirrah, what made your master in this place?" },
    { r = {"PAGE"}, t = "He came with flowers to strew his lady’s grave," },
    { r = {"PAGE"}, t = "And bid me stand aloof, and so I did." },
    { r = {"PAGE"}, t = "Anon comes one with light to ope the tomb," },
    { r = {"PAGE"}, t = "And by and by my master drew on him," },
    { r = {"PAGE"}, t = "And then I ran away to call the watch." },
    { r = {"ESCALUS"}, t = "This letter doth make good the Friar’s words," },
    { r = {"ESCALUS"}, t = "Their course of love, the tidings of her death." },
    { r = {"ESCALUS"}, t = "And here he writes that he did buy a poison" },
    { r = {"ESCALUS"}, t = "Of a poor ’pothecary, and therewithal" },
    { r = {"ESCALUS"}, t = "Came to this vault to die, and lie with Juliet." },
    { r = {"ESCALUS"}, t = "Where be these enemies? Capulet, Montague," },
    { r = {"ESCALUS"}, t = "See what a scourge is laid upon your hate," },
    { r = {"ESCALUS"}, t = "That heaven finds means to kill your joys with love!" },
    { r = {"ESCALUS"}, t = "And I, for winking at your discords too," },
    { r = {"ESCALUS"}, t = "Have lost a brace of kinsmen. All are punish’d." },
    { r = {"CAPULET"}, t = "O brother Montague, give me thy hand." },
    { r = {"CAPULET"}, t = "This is my daughter’s jointure, for no more" },
    { r = {"CAPULET"}, t = "Can I demand." },
    { r = {"MONTAGUE"}, t = "But I can give thee more," },
    { r = {"MONTAGUE"}, t = "For I will raise her statue in pure gold," },
    { r = {"MONTAGUE"}, t = "That whiles Verona by that name is known," },
    { r = {"MONTAGUE"}, t = "There shall no figure at such rate be set" },
    { r = {"MONTAGUE"}, t = "As that of true and faithful Juliet." },
    { r = {"CAPULET"}, t = "As rich shall Romeo’s by his lady’s lie," },
    { r = {"CAPULET"}, t = "Poor sacrifices of our enmity." },
    { r = {"ESCALUS"}, t = "A glooming peace this morning with it brings;" },
    { r = {"ESCALUS"}, t = "The sun for sorrow will not show his head." },
    { r = {"ESCALUS"}, t = "Go hence, to have more talk of these sad things." },
    { r = {"ESCALUS"}, t = "Some shall be pardon’d, and some punished," },
    { r = {"ESCALUS"}, t = "For never was a story of more woe" },
    { r = {"ESCALUS"}, t = "Than this of Juliet and her Romeo." },
    { d = "Exeunt" },
  },
}
